NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Isaiah'

CHAPTERS = {
    1: {
        1: 'Videnje Amócovega sina Izaija, ki ga je videl glede Juda in Jeruzalema v dneh Uzíjaha, Jotáma, Aháza in Ezekíja, Judovih kraljev.',
        2: 'Prisluhnite, oh nebesa in pazljivo prisluhni, oh zemlja, kajti Gospod je spregovoril: »Hranil in vzgojil sem otroke, oni pa so se uprli zoper mene.',
        3: 'Vol pozna svojega lastnika in osel jasli svojega gospodarja, toda Izrael ne pozna, moje ljudstvo ne preudari.',
        4: 'Ah, grešen narod, ljudstvo, obloženo s krivičnostjo, seme hudodelcev, otroci, ki so izprijenci. Zapustili so Gospoda, izzivali so Svetega Izraelovega k jezi, odvrnili so se nazaj.',
        5: 'Zakaj naj bi bili še udarjani? Spuntali se boste bolj in bolj. Celotna glava je bolna in celotno srce slabi.',
        6: 'Od podplata stopala celo do glave ni zdravja na njem, temveč rane, modrice in gnojne rane; te niso bile zaprte niti obvezane niti ublažene z mazilom.',
        7: 'Vaša dežela je zapuščena, vaša mesta so požgana z ognjem. Vaša dežela, tujci jo požirajo v vaši prisotnosti in ta je zapuščena, kakor premagana s tujci.',
        8: 'Hči sionska je ostala kakor koča v vinogradu, kakor lopa na kumaričnem vrtu, kakor oblegano mesto.«',
        9: 'Razen, če nam Gospod nad bojevniki ne bi pustil zelo majhnega ostanka, bi bili kakor Sódoma in podobni bi bili Gomóri.',
        10: 'Poslušajte Gospodovo besedo, vi sódomski vladarji, pazljivo prisluhnite postavi našega Boga, ljudstvo gomórsko.',
        11: '»Za kakšen namen mi je množica vaših klavnih daritev?« govori Gospod: »Sit sem žgalnih daritev ovnov in tolšče pitanih živali in ne razveseljujem se v krvi bikcev ali jagnjet ali kozlov.',
        12: 'Ko prihajate, da se pojavite pred menoj, kdo je to zahteval iz vaše roke, da teptate moje dvore?',
        13: 'Ne prinašajte več praznih daritev; kadilo mi je ogabnost. Mlajev in šabat, sklicevanja zborov ne morem prenašati; to je krivičnost, celo slovesno srečanje.',
        14: 'Vaše mlaje in vaše določene praznike sovraži moja duša. Le-ti so mi obremenitev, naveličal sem se jih prenašati.',
        15: 'Ko svoje roke iztezate naprej, bom pred vami skril svoje oči. Da, ko opravljate številne molitve, ne bom poslušal. Vaše roke so polne krvi.',
        16: 'Umijte se, očistite se. Odstranite zlo svojih dejanj izpred mojih oči, prenehajte početi zlo.',
        17: 'Naučite se delati dobro, iščite sodbo, olajšajte zatirane, sodite osirotele, potegujte se za vdovo.',
        18: 'Pridite torej in skupaj preudarimo,« govori Gospod, »čeprav bi bili vaši grehi kakor škrlat, bodo tako beli kakor sneg; čeprav bi bili rdeči, podobni škrlatnemu [črvu], bodo kakor volna.',
        19: 'Če boste voljni in poslušni, boste jedli dobro od dežele.',
        20: 'Toda če odklonite in se uprete, boste požrti z mečem, kajti Gospodova usta so to govorila.',
        21: 'Kako je zvesto mesto postalo pocestnica! Bila je polna sodbe, pravičnost je bila nastanjena v njej, toda sedaj morilci.',
        22: 'Tvoje srebro je postalo žlindra, tvoje vino pomešano z vodo,',
        23: 'tvoji princi so uporni in družabniki tatov. Vsakdo izmed njih ljubi darila in sledi podkupninam. Osirotelega ne branijo niti pravda vdov ne pride k njim.«',
        24: 'Zato govori Gospod, Gospod nad bojevniki, Mogočni Izraelov: »Ah, žal mi bo mojih nasprotnikov in maščeval se bom nad svojimi sovražniki',
        25: 'in svojo roko bom obrnil nadte in z lugom temeljito očistil proč tvojo žlindro in odvzel ves tvoj kositer',
        26: 'in povrnil bom tvoje sodnike kakor poprej in tvoje svetovalce, kakor na začetku. Potem boš imenovana: ›Mesto pravičnosti, zvesto mesto.‹',
        27: 'Sion bo odkupljen s sodbo in njegovi spreobrnjenci s pravičnostjo.',
        28: 'Uničenje prestopnikov in grešnikov bo hkratno in tisti, ki zapustijo Gospoda, bodo použiti.',
        29: 'Kajti sramovali se bodo hrastov, ki ste jih želeli in zbegani boste zaradi vrtov, ki ste jih izbrali.',
        30: 'Kajti vi boste kakor hrast, čigar list oveni in kakor vrt, ki nima vode.',
        31: 'Močni bo kakor predivo in njegov izdelovalec kakor iskra in skupaj bosta sežgana in nihče ju ne bo pogasil.«',
    },
    2: {
        1: 'Beseda, ki jo je Izaija, Amócov sin, videl glede Juda in Jeruzalema.',
        2: 'Zgodilo se bo v poslednjih dneh, da bo gora Gospodove hiše osnovana na vrhu gora in povišana bo nad hribe. In vsi narodi se bodo stekali k njej.',
        3: 'Mnogo ljudstva bo šlo in reklo: »Pridite in pojdimo gor na Gospodovo goro, k hiši Jakobovega Boga. Učil nas bo svojih poti in hodili bomo po njegovih stezah, kajti iz Siona bo izšla postava in Gospodova beseda iz Jeruzalema.«',
        4: 'Sodil bo med narodi, oštel bo mnoga ljudstva. Svoje meče bodo prekovali v lemeže in svoje sulice v obrezovalne kavlje. Narod ne bo vzdignil meča zoper narod niti se ne bodo več učili bojevanja.',
        5: 'Oh Jakobova hiša, pridite in hodímo v Gospodovi svetlobi.',
        6: 'Zatorej si zapustil svoje ljudstvo, Jakobovo hišo, ker so bili izpolnjeni od vzhoda in so napovedovalci usode kakor Filistejci in sebi ugajajo v otrocih tujcev.',
        7: 'Njihova dežela je polna srebra in zlata niti tam ni konca njihovih zakladov. Njihova dežela je polna konj niti tam ni konca njihovih bojnih voz.',
        8: 'Njihova dežela je polna malikov, obožujejo delo svojih lastnih rok, to, kar so naredili njihovi lastni prsti.',
        9: 'Zloben človek se priklanja in velik človek se ponižuje, zato jim ne odpusti.',
        10: 'Vstopi v skalo in se skrij v prahu zaradi strahu pred Gospodom in zaradi slave njegovega veličanstva.',
        11: 'Človekovi vzvišeni pogledi bodo ponižani in oholost ljudi bo upognjena in sam Gospod bo na ta dan povišan.',
        12: 'Kajti dan Gospoda nad bojevniki bo nad vsakim, ki je ponosen in vzvišen in nad vsakim, ki je povzdignjen, in ta bo ponižan;',
        13: 'in nad vsemi libanonskimi cedrami, ki so visoke in povzdignjene in nad vsemi bašánskimi hrasti',
        14: 'in nad vsemi visokimi gorami in nad vsemi hribi, ki so povzdignjeni,',
        15: 'in nad vsakim visokim stolpom in nad vsakim utrjenim zidom,',
        16: '§ in na vseh ladjah iz Taršíša in na vseh prijetnih slikah.',
        17: 'Nadutost človeka bo upognjena in oholost ljudi bo ponižana. Samo Gospod bo povišan na ta dan.',
        18: 'Malike bo popolnoma odpravil.',
        19: 'Šli bodo v skalne luknje in v zemeljske votline zaradi strahu pred Gospodom in zaradi slave njegovega veličanstva, ko se on vzdiguje, da strašno strese zemljo.',
        20: 'Na tisti dan bo človek vrgel svoje malike iz srebra in svoje malike iz zlata, ki so si jih naredili, vsakdo za oboževanje, krtom in netopirjem,',
        21: 'da bo šel v skalne razpoke in na vrhove razdrapanih skal, zaradi strahu pred Gospodom in zaradi slave njegovega veličanstva, ko se bo vzdigoval, da strašno strese zemljo.',
        22: 'Odvrnite se od človeka, katerega dih je v njegovih nosnicah, kajti v čem je ta cenjen?',
    },
    3: {
        1: 'Kajti glej, Gospod, Gospod nad bojevniki, jemlje proč od Jeruzalema in od Juda, podporo in palico, celotno podporo kruha in celotno podporo vode,',
        2: 'mogočnega človeka in bojevnika, sodnika in preroka, razsodnega in starca,',
        3: 'petdesetnika, častitljivega človeka, svetovalca, spretnega rokodelca in zgovornega govornika.',
        4: 'Otroke jim bom dal za prince in otročiči bodo vladali nad njimi.',
        5: 'Ljudstvo bo zatirano, eden od drugega in vsakdo od svojega soseda; otrok se bo ponosno vedel zoper starca in nizek zoper častitljivega.',
        6: 'Ko bo človek zgrabil svojega brata iz hiše svojega očeta, rekoč: »Oblačilo imaš, bodi naš vladar in naj bo ta razvalina pod tvojo roko,«',
        7: 'na tisti dan bo ta prisegel, rekoč: »Ne bom ranocelnik, kajti v moji hiši ni niti kruha niti obleke. Ne postavljajte me za vladarja ljudstvu.«',
        8: 'Kajti Jeruzalem je razrušen in Juda je padel, ker so njihov jezik in njihova početja zoper Gospoda, da izzivajo oči njegove slave.',
        9: 'Prikaz njihovega obličja pričuje zoper njih, ne skrivajo svojega greha, razglašajo ga kakor Sódoma. Gorje njihovi duši! Kajti nagradili so se z zlom.',
        10: 'Recite pravičnemu, da bo dobro z njim; kajti jedli bodo sad svojih dejanj.',
        11: 'Gorje zlobnemu! Z njim bo slabo, kajti dana mu bo nagrada njegovih rok.',
        12: 'Kar se tiče mojega ljudstva, so njihovi zatiralci otroci, vladajo pa jim ženske. Oh moje ljudstvo, tisti, ki te vodijo, ti povzročajo, da se motiš in uničujejo pot tvojih steza.',
        13: 'Gospod vstaja, da bi se pravdal in stoji, da bi sodil ljudstvu.',
        14: 'Gospod bo stopil na sodbo s starci svojega ljudstva in njegovimi princi, kajti požrli ste vinograd; plen ubogih je v vaših hišah.',
        15: '›Kaj nameravate, da lomite moje ljudstvo na koščke in meljete obraze revnih?‹ govori Gospod Bog nad vojskami.',
        16: 'Poleg tega Gospod govori: ›Ker so hčere sionske ošabne in hodijo z vratovi, iztegnjenimi naprej in poltenimi očmi, hodijo in drobijo medtem ko gredo in zvončkljajo s svojimi stopali,',
        17: 'zato bo Gospod s krasto udaril tême sionskih hčera in Gospod bo odkril njihove skrite dele.',
        18: 'Na tisti dan bo Gospod odvzel pogumnost njihovih zvončkljajočih ornamentov okoli njihovih stopal in njihove čepice in njihove okrogle rute, podobne luni,',
        19: 'verižice, zapestnice, šale,',
        20: 'klobučke, ornamente nog, naglavne trakove, ogrlice, uhane,',
        21: 'prstane, nosne dragocenosti,',
        22: 'zamenljive ogrinjalne kostime, plašče, plete, torbice,',
        23: 'zrcala, tanko laneno platno, kapuce in zagrinjala.',
        24: 'Zgodilo se bo, da bo namesto prijetnega vonja tam zaudarjanje, namesto pasu vrv, namesto pričeske plešavost, namesto životca opasovanje vrečevine in opeklina namesto lepote.',
        25: 'Tvoji možje bodo padli pod mečem in tvoji mogočni v vojni.',
        26: 'Njena velika vrata bodo žalovala in tulila in ona bo zapuščena sedela na tleh.',
    },
    4: {
        1: 'Na ta dan bo sedem žensk prijelo enega moškega, rekoč: »Jedle bomo svoj kruh in nosile svoje obleke; samo dovoli nam biti klicane po tvojem imenu, da odvzameš našo grajo.«',
        2: 'Na tisti dan bo Gospodova mladika krasna in veličastna in sad zemlje bo odličen in ljubek za tiste, ki so pobegnili iz Izraela.',
        3: 'Zgodilo se bo, da bo tisti, ki je ostal na Sionu in ki ostaja v Jeruzalemu, imenovan svet, celó vsak, kdor je zapisan med živimi v Jeruzalemu,',
        4: 'ko bo Gospod izmil umazanijo sionskih hčera in očistil kri [prestolnice] Jeruzalem iz njene srede, z duhom sodbe in z duhom gorenja.',
        5: 'In Gospod bo nad vsakim prebivališčem gore Sion in nad njenimi zbori ustvaril oblak in dim podnevi in svetlikanje plamenečega ognja ponoči, kajti nad vso slavo bo obramba.',
        6: 'Tam bo šotorsko svetišče za senco podnevi pred vročino, za prostor zatočišča in za skrivališče pred viharjem in dežjem.',
    },
    5: {
        1: 'Torej bom svojemu srčno ljubljenemu zapel pesem o mojem ljubljenem, glede njegovega vinograda. Moj srčno ljubljeni ima vinograd na zelo plodnem hribu',
        2: 'in ogradil ga je in pobral ven njegove kamne, ga zasadil z izbrano trto, v njegovi sredi zgradil stolp in v njem naredil tudi vinsko stiskalnico in gledal, da bi ta obrodil grozdje, pa je obrodil divje grozdje.',
        3: 'In sedaj, oh prebivalci Jeruzalema in možje iz Juda, sodite, prosim vas, med menoj in mojim vinogradom.',
        4: 'Kaj bi bilo lahko več storjeno za moj vinograd, česar nisem storil v njem? Čemu je ta, ko sem gledal, da bi obrodil grozdje, obrodil divje grozdje?',
        5: 'Sedaj pojdi, povedal ti bom, kaj bom storil svojemu vinogradu. Odstranil bom njegovo ograjo in ta bo požrt in porušil bom njegovo obzidje in ta bo pomendran.',
        6: 'Opustošil ga bom. Ne bo obrezan niti prekopan, temveč bosta tam rasla osat in trnje. Tudi oblakom bom zapovedal, da nanj ne dežujejo več dežja.',
        7: 'Kajti vinograd Gospoda nad bojevniki je Izraelova hiša in Judovi možje so njegov prijetni nasad. Iskal je sodbo, toda glej, zatiranje, za pravičnostjo, toda glej, jok.',
        8: 'Gorje tistim, ki priključujejo hišo k hiši, ki postavljajo polje k polju, dokler ni več prostora, da bi bili lahko oni sami nameščeni na sredi zemlje!',
        9: 'V moja ušesa je Gospod nad bojevniki rekel: »Resnično, mnogo hiš bo zapuščenih, celó velike in lepe, brez prebivalca.«',
        10: 'Da, deset oralov vinograda bo obrodilo en čeber in seme enega tovora bo obrodilo škaf.',
        11: 'Gorje tistim, ki vstajajo zgodaj zjutraj, da lahko sledijo močni pijači; to nadaljujejo do večera, dokler jih vino ne vname!',
        12: 'Harfa, lira, bobnič, piščal in vino so na njihovih praznovanjih; toda ne ozirajo se na Gospodovo delo niti ne preudarijo delovanja njegovih rok.',
        13: 'Zato je moje ljudstvo odšlo v ujetništvo, ker nimajo spoznanja. Njihovi častitljivi možje so izstradani in njihova množica izsušena z žejo.',
        14: 'Zato se bo pekel povečal in svoja usta odprl brez mere. Njihova slava, njihova množica, njihov pomp in kdor se razveseljuje, se bo pogreznil vanj.',
        15: 'Zloben človek bo priveden dol, mogočen človek bo ponižan in oči vzvišenih bodo ponižane,',
        16: 'toda Gospod nad bojevniki bo povišan na sodbi in Bog, ki je svet, bo posvečen v pravičnosti.',
        17: 'Potem se bodo jagnjeta pasla po svoji navadi in opustošene kraje debelih bodo pojedli tujci.',
        18: 'Gorje tistim, ki krivičnost vlečejo z vrvmi ničnosti in greh vlečejo, kakor bi bilo z garami;',
        19: 'ki pravijo: ›Naj pohiti in pospeši svoje delo, da bomo to lahko videli in naj se nasvet Svetega Izraelovega približa in pride, da bomo to lahko vedeli!',
        20: 'Gorje tistim, ki imenujejo zlo dobro in dobro zlo, ki postavljajo temo za svetlobo in svetlobo za temo, ki postavljajo grenko za sladko in sladko za grenko!',
        21: 'Gorje tistim, ki so modri v svojih lastnih očeh in razsodni v svojem lastnem pogledu!',
        22: 'Gorje tistim, ki so mogočni, da pijejo vino in možje moči, da mešajo močno pijačo,',
        23: 'ki za nagrado opravičijo zlobne in pravičnost pravičnega odvzamejo od njega!',
        24: 'Zatorej kakor ogenj požira strnišče in plamen použiva pleve, tako bo njihova korenina kakor gniloba in njihov cvet se bo dvigal gor kakor prah, ker so odvrgli postavo Gospoda nad bojevniki in prezirali besedo Svetega Izraelovega.',
        25: 'Zato je Gospodova jeza vžgana zoper njegovo ljudstvo in svojo roko je iztegnil zoper njih in jih udaril in hribi so trepetali in njihova trupla so bila raztrgana na sredi ulic. Zaradi vsega tega njegova jeza ni odvrnjena, temveč je njegova roka še vedno iztegnjena.',
        26: 'Dvignil bo zastavo narodom iz daljave in požvižgal jim bo od konca zemlje. Glej, naglo bodo prišli s hitrostjo.',
        27: 'Nihče izmed njih ne bo izmučen niti se ne bo spotaknil; nihče ne bo dremal, niti spal, niti pas njihovih ledij ne bo popuščen, niti jermen njihovih čevljev pretrgan.',
        28: 'Katerih puščice so ostre in vsi njihovi loki napeti, kopita njihovih konj bodo šteta kakor kremen in njihova kolesa kakor vrtinčast veter.',
        29: 'Njihovo rjovenje bo podobno levu, rjoveli bodo kakor mladi levi. Da, rjoveli bodo, zgrabili plen in ga varno odnesli proč in nihče ga ne bo osvobodil.',
        30: 'Na ta dan bodo besneli zoper njih, kakor besni morje in če nekdo pogleda na deželo, zagleda temo in bridkost in svetloba otemni v njegovem nebu.',
    },
    6: {
        1: 'V letu, ko je kralj Uzíjah umrl, sem videl tudi Gospoda sedeti na prestolu, visokega in dvignjenega in njegova vlečka je napolnila tempelj.',
        2: 'Nad njim so stali serafi. Vsak je imel šest peruti. Z dvema je pokril svoj obraz in z dvema je pokril svoja stopala in z dvema je letel.',
        3: 'Eden je vzklikal drugemu in govoril: »Svet, svet, svet je Gospod nad bojevniki. Celotna zemlja je polna njegove slave.«',
        4: 'Podboji vrat so se premaknili ob glasu tistega, ki je vpil in hiša je bila napolnjena z dimom.',
        5: 'Potem sem rekel: »Gorje meni! Kajti onemel sem, ker sem človek nečistih ustnic in prebivam v sredi ljudstva nečistih ustnic, kajti moje oči so videle kralja, Gospoda nad bojevniki.«',
        6: 'Potem je priletel k meni eden izmed serafov, ki je imel v svoji roki žerjavico, ki jo je s kleščami vzel od oltarja.',
        7: 'To je položil na moja usta in rekel: »Glej, to se je dotaknilo tvojih ustnic in tvoja krivičnost je odvzeta proč in tvoj greh je očiščen.«',
        8: 'Slišal sem tudi glas od Gospoda, rekoč: »Koga naj pošljem in kdo bo šel za nas?« Potem sem rekel: »Tukaj sem, pošlji mene.«',
        9: 'Rekel je: »Pojdi in povej temu ljudstvu: ›Resnično, poslušajte, toda ne razumite in resnično glejte, pa ne zaznajte.',
        10: 'Naredi srce tega ljudstva debelo in njihova ušesa naredi težka in zapri njihove oči, da ne bi videli s svojimi očmi in [ne bi] slišali s svojimi ušesi in [ne bi] razumeli s svojim srcem in ne bi bili spreobrnjeni in ne bi bili ozdravljeni.‹«',
        11: 'Tedaj sem rekel: »Gospod, doklej?« Odgovoril je: »Dokler ne bodo mesta opustošena, brez prebivalca in hiše brez človeka in ne bo dežela popolnoma zapuščena',
        12: 'in Gospod je ljudi odstranil daleč proč in tam bo veliko zapuščanja v sredi dežele.',
        13: 'Toda vendar bo v njej desetina in ta se bo vrnila in bo požrta; kakor terebinta in kakor hrast, katerega snov je v njiju, ko odvržeta svoje listje, tako bo sveto seme snov le-tega.«',
    },
    7: {
        1: 'Pripetilo se je v dneh Aháza, Jotámovega sina, Uzíjahovega sina, Judovega kralja, da sta Recín, sirski kralj in Pékah, Remaljájev sin, Izraelov kralj, odšla gor proti Jeruzalemu, da se bojujeta zoper njega, toda nista mogla prevladati zoper njega.',
        2: 'Davidovi hiši je bilo povedano, rekoč: »Sirija je združena z Efrájimom.« Njegovo srce je vztrepetalo in srce njegovega ljudstva, kakor gozdna drevesa trepetajo v vetru.',
        3: 'Potem je Gospod rekel Izaiju: »Pojdi sedaj naprej, da srečaš Aháza, ti in tvoj sin Šeár Jašúb, pri koncu kanala zgornjega ribnika, na glavni cesti pralčevega polja',
        4: 'in mu reci: ›Pazi se in bodi tiho. Ne boj se niti naj ti srce ne peša zaradi dveh repov teh kadečih kosov tlečega lesa, zaradi krute Recínove jeze s Sirijo in [zaradi] Remaljájevega sina.',
        5: 'Ker so Sirija, Efrájim in Remaljájev sin sprejeli hudoben nasvet zoper tebe, rekoč:',
        6: '›Pojdimo gor zoper Juda in ga razjezimo in si v njem naredimo vrzel zase in v njegovi sredi postavimo kralja, celó Tabeálovega sina,‹',
        7: 'tako govori Gospod Bog: ›To ne bo obstalo niti se to ne bo zgodilo.',
        8: 'Kajti glava Sirije je Damask in glava Damaska je Recín. V petinšestdesetih letih bo Efrájim zlomljen, da ne bo ljudstvo.',
        9: 'Glava Efrájima je Samarija in glava Samarije je Remaljájev sin. Če ne boste verjeli, zagotovo ne boste utrjeni.‹«',
        10: 'Poleg tega je Gospod ponovno spregovoril Aházu, rekoč:',
        11: '»Izprosi si znamenje od Gospoda, svojega Boga, prosi ga ali v globini ali na višini zgoraj.«',
        12: 'Toda Aház je rekel: »Ne bom prosil niti ne bom skušal Gospoda.«',
        13: 'In ta je rekel: »Poslušajte sedaj, oh Davidova hiša: › Ali je za vas malenkost, da izmučite ljudi, toda ali hočete izmučiti tudi mojega Boga?‹',
        14: '§ Zato vam bo sam Gospod dal znamenje: ›Glejte, devica bo spočela, rodila sina in njegovo ime bo klicala Emanuel.',
        15: 'Maslo in med bo jedel, da bo znal odkloniti zlo in izbrati dobro.',
        16: 'Kajti preden bo otrok znal odkloniti zlo in izbrati dobro, bo dežela, ki jo preziraš, postala zapuščena od obeh njunih kraljev.‹',
        17: 'Gospod bo nadte in nad tvoje ljudstvo in nad hišo tvojega očeta privedel dneve, ki niso prišli od dni, ko je Efrájim odšel od Juda, celó asirskega kralja.«',
        18: 'Na tisti dan se bo zgodilo, da bo Gospod požvižgal muhi, ki je na najbolj oddaljenem delu egiptovskih rek in čebeli, ki je v asirski deželi.',
        19: 'Prišle bodo in vse izmed njih bodo počivale po zapuščenih dolinah, v skalnih jamah, na vsem trnju in po vsem grmovju.',
        20: 'Na isti dan bo Gospod obril z britvico, ki je najeta, namreč, s tistimi preko reke, z asirskim kraljem, glavo in dlake stopal in ta bo použila tudi brado.',
        21: 'Na tisti dan se bo zgodilo, da bo človek redil mlado kravo in dve ovci',
        22: 'in zgodilo se bo zaradi oblice mleka, ki ga bodo dajale, da bo jedel maslo. Kajti maslo in med bo jedel vsakdo, ki je ostal v deželi.',
        23: 'Na tisti dan se bo zgodilo, da bo vsak kraj, kjer je bilo tisoč trt kakor tisoč malih srebrnih kovancev, ta celó za osat in trnje.',
        24: 'S puščicami in loki bodo tja prišli možje, ker bo vsa dežela postala osat in trnje.',
        25: 'Po vseh hribih, ki bodo okopani z motiko, nanje ne bo prišel strah pred osatom in trnjem, temveč bo to za odpošiljanje volov in za teptanje manjše živine.',
    },
    8: {
        1: 'Poleg tega mi je Gospod rekel: »Vzemi si velik zvitek in vanj zapiši s človeškim pisalom glede Mahér Šalál Haš Baza.«',
        2: 'K sebi sem vzel zvesti priči, da zabeležita: duhovnika Urijá in Jeberehjájevega sina Zeharjá.',
        3: 'Odšel sem k prerokinji in spočela je ter rodila sina. Potem mi je Gospod rekel: »Njegovo ime kliči Mahér Šalál Haš Baz.',
        4: 'Kajti preden bo imel otrok spoznanje, da kliče: ›Moj oče in moja mati,‹ bodo bogastva Damaska in plen Samarije odvzeti pred asirskim kraljem.«',
        5: 'Gospod mi je prav tako ponovno spregovoril, rekoč:',
        6: '»Ker kakor to ljudstvo odklanja síloaške vode, ki mirno tečejo in se veselijo v Recínu in Remaljájevemu sinu,',
        7: 'zdaj torej, glej, Gospod prinaša nadnje vode iz reke, močne in številne, celó asirskega kralja in vso njegovo slavo in prestopil bo vse njegove kanale in prestopil vse njegove bregove',
        8: 'in šel bo skozi Juda, preplavil bo in šel preko, segel bo celó do vratu in razprostirajoč svoje peruti bo napolnil širino tvoje dežele, oh Emanuel.«',
        9: 'Povežite se med seboj, oh ve ljudstva in razbiti boste na koščke in pazljivo prisluhnite, vsi vi iz daljnih dežel, opašite se in zlomljeni boste na koščke, opašite se in zlomljeni boste na koščke.',
        10: 'Skupaj se posvetujte in to se bo izjalovilo, govorite besedo, pa ta ne bo obstala, kajti Bog je z nami.',
        11: 'Kajti Gospod mi je tako govoril z močno roko in me učil, da naj ne hodim po poti tega ljudstva, rekoč:',
        12: '»Ne reci: ›Zarota,‹ vsem tistim, ki jim bo to ljudstvo reklo: ›Zarota,‹ niti se ne bojte njihovega strahu niti ne bodi prestrašeni.',
        13: 'Posvečujte Gospoda nad bojevniki samega in naj bo on vaš strah in naj bo on vaša groza.',
        14: 'On vam bo svetišče, toda za kamen spotike in za skalo pohujšanja obema Izraelovima hišama, za past in za zanko prebivalcem Jeruzalema.',
        15: 'Številni izmed njih se bodo spotaknili, padli, zlomljeni bodo, ujeti v zanko in zajeti.',
        16: 'Poveži pričevanje, zapečati postavo med mojimi učenci.',
        17: 'Čakal bom na Gospoda, ki svoj obraz skriva pred Jakobovo hišo in iskal ga bom.',
        18: 'Glejte, jaz in otroci, ki mi jih je dal Gospod, smo za znamenja in za čudeže v Izraelu od Gospoda nad bojevniki, ki prebiva na gori Sion.',
        19: 'Ko ti bodo rekli: »Obrni se k tem, ki imajo osebne duhove in k čarovnikom, ki čivkajo in ki mrmrajo. Mar naj ne bi ljudstvo iskalo svojega Boga? Za žive k mrtvim?«',
        20: 'K postavi in k pričevanju. Če ne govorijo glede na to besedo, je to zato, ker v njih ni svetlobe.',
        21: 'Šli bodo skozi to, silno ogorčeni in lačni. In zgodilo se bo, da ko bodo lačni, da se bodo v jezi razburili in preklinjali svojega kralja, svojega Boga in gledali navzgor.',
        22: 'Pogledali bodo na zemljo in glej stiska in tema, temačnost tesnobe in gnani bodo v temo.',
    },
    9: {
        1: 'Kljub temu temačnost ne bo takšna, kot je bila v njenem draženju, ko je najprej blago stiskal deželo Zábulon in deželo Neftáli in jo je potem bolj boleče stiskal ob poti morja, onkraj Jordana, v poganski Galileji.',
        2: 'Ljudstvo, ki je hodilo v temi, je zagledalo veliko svetlobo. Na tiste, ki prebivajo v deželi smrtne sence, je posvetila svetloba.',
        3: 'Pomnožil si narod in nisi povečal radosti. Radostijo se pred teboj, v skladu z radostjo ob žetvi in kakor se ljudje veselijo, ko delijo plen.',
        4: 'Kajti zlomil si jarem njegovega bremena in palico njegovega ramena, palico njegovega zatiralca, kakor na dan Midjána.',
        5: 'Kajti vsaka bitka bojevnika je z zmedenim hrupom in oblekami, povaljanimi v krvi, toda ta bo z gorenjem in gorivom ognju.',
        6: 'Kajti nam je rojen otrok, nam je dan sin in oblast bo na njegovem ramenu in njegovo ime bo imenovano Čudoviti, Svetovalec, Mogočni Bog, Večni Oče, Princ miru.',
        7: 'Povečanju njegovega vladarstva in miru ne bo konca nad Davidovem prestolom in nad njegovim kraljestvom, da to odredi in da to osnuje s sodbo in s pravico od tega časa naprej, celo na veke. Gorečnost Gospoda nad bojevniki bo to izvršila.',
        8: 'Gospod je poslal besedo Jakobu in jo vžgal nad Izraelom.',
        9: 'Vse ljudstvo bo vedelo, celó Efrájim in prebivalec Samarije, ki v ponosu in arogantnosti srca govorijo:',
        10: '»Opeke so padle, toda mi bomo gradili s klesanimi kamni. Egiptovske smokve so posekane, toda mi jih bomo zamenjali s cedrami.«',
        11: 'Zato bo Gospod zoper njega postavil Recínove nasprotnike in skupaj združil njegove sovražnike,',
        12: 'spredaj Sirce in zadaj Filistejce in Izrael bodo požrli z odprtimi usti. Zaradi vsega tega njegova jeza ni odvrnjena, temveč je njegova roka še vedno iztegnjena.',
        13: 'Kajti ljudstvo se ne obrača k tistemu, ki jih udarja niti ne iščejo Gospoda nad bojevniki.',
        14: 'Zato bo Gospod v enem dnevu iz Izraela iztrebil glavo in rep, palmovo vejo in ločje.',
        15: 'Starec in častitljiv, ta je glava, prerok pa, ki uči laži, ta je rep.',
        16: 'Kajti voditelji tega ljudstva jim povzročajo, da se motijo in tisti, ki so vodeni od njih, so uničeni.',
        17: 'Zato Gospod ne bo imel nobene radosti v njihovih mladeničih niti ne bo imel usmiljenja do njihovih sirot in vdov, kajti vsakdo je hinavec in hudodelec in vsaka usta govorijo neumnost. Zaradi vsega tega njegova jeza ni odvrnjena, temveč je njegova roka še vedno iztegnjena.',
        18: 'Kajti zlobnost gori kakor ogenj. Ta bo požrl osat in trnje in vnel gozdne goščave in vzdignili se bodo kakor vzdigovanje dima.',
        19: 'Preko besa Gospoda nad bojevniki je dežela zatemnjena in ljudstvo bo kakor gorivo ognju. Noben človek ne bo prizanesel svojemu bratu.',
        20: 'Hlastal bo na desnici in bo lačen, jedel bo na levici, pa ne bodo nasičeni. Vsak človek bo jedel meso svojega lastnega lakta:',
        21: 'Manáse Efrájima in Efrájim Manáseja in skupaj bosta zoper Juda. Zaradi vsega tega njegova jeza ni odvrnjena, temveč je njegova roka še vedno iztegnjena.',
    },
    10: {
        1: 'Gorje tistim, ki razglašajo krivične odloke in ki pišejo muko, ki so jo predpisali,',
        2: 'da odvrnejo pomoči potrebnega stran od sodbe in da odvzamejo pravico od revnega izmed mojega ljudstva, da bi bile lahko vdove njihov plen in da lahko oropajo osirotelega!',
        3: 'Kaj boste storili na dan obiskanja in v opustošenju, ki bo prišlo od daleč? H komu boste pobegnili po pomoč? In kje boste pustili svojo slavo?',
        4: 'Brez mene se bodo sklonili pod ujetniki in padli bodo pod umorjenimi. Zaradi vsega tega njegova jeza ni odvrnjena, temveč je njegova roka še vedno iztegnjena.',
        5: 'Oh Asirec, šiba moje jeze in palica v njihovi roki je moje ogorčenje.',
        6: 'Poslal ga bom zoper hinavski narod in zoper ljudstvo mojega besa mu bom dal zadolžitev, da vzame ukradeno blago, da vzame plen in da jih potepta kakor ulično blato.',
        7: 'Vendar on ne meni tako niti njegovo srce ne misli tako, temveč je na njegovem srcu to, da uniči in iztrebi ne malo narodov.',
        8: 'Kajti on pravi: » Mar niso moji princi vsi skupaj kralji?',
        9: 'Mar ni Kalne kakor Kárkemiš? Mar ni Hamát kakor Arpád? Mar ni Samarija kakor Damask?',
        10: 'Kakor je moja roka našla kraljestva malikov in katerih rezane podobe so nadkriljevale te iz Jeruzalema in iz Samarije,',
        11: 'mar ne bom, kakor sem storil Samariji in njenim malikom, tako storil Jeruzalemu in njegovim malikom?',
        12: 'Kjerkoli se bo to pripetilo, da ko Gospod opravi svoje celotno delo na gori Sion in v Jeruzalemu, bom kaznoval sad arogantnega srca asirskega kralja in slavo njegovih vzvišenih pogledov.',
        13: 'Ker pravi: › To sem storil z močjo svoje dlani in s svojo modrostjo, ker sem razsoden. Ljudstvu sem odstranil meje in oropal njihove zaklade in kakor hraber človek ponižal prebivalce',
        14: 'in moja roka je našla kakor gnezdo bogastva ljudstev; in kakor nekdo zbira jajca, ki so ostala, sem jaz zbral vso zemljo in nikogar ni bilo, ki bi zganil perut ali odprl usta ali začivkal.',
        15: 'Mar se bo sekira bahala pred tistim, ki z njo seka? Mar se bo žaga poveličevala pred tistim, ki jo vleče? Kakor če bi se palica tresla pred tistim, ki jo vzdiguje, ali kakor če bi se palica sama vzdigovala, kakor če ne bi bila les.',
        16: 'Zato bo Gospod, Gospod nad bojevniki, med njegove rejene poslal pustost in pod njegovo slavo bo vžgal gorenje, podobno gorenju ognja.',
        17: 'Izraelova svetloba bo za ogenj in njegov Sveti za plamen in ta bo gorel in v enem dnevu bo pogoltnil njegovo trnje in njegove osate',
        18: '§ in použil bo slavo njegovega gozda in njegovega rodovitnega polja, tako dušo kakor telo in oni bodo kakor kadar nosilec prapora slabi.',
        19: 'Preostanka dreves njegovega gozda bo malo, da jih lahko otrok zapiše.',
        20: 'Na tisti dan se bo zgodilo, da se Izraelov ostanek in tisti, ki so pobegnili od Jakobove hiše, ne bodo več ponovno naslanjali nanj, ki jih je udaril, temveč se bodo v resnici naslanjali na Gospoda, Svetega Izraelovega.',
        21: 'Preostanek se bo vrnil, celó Jakobov preostanek, k mogočnemu Bogu.',
        22: 'Kajti čeprav bo tvojega ljudstva Izraela kakor morskega peska, se bo vendar ostanek izmed njih vrnil. Odrejeno uničenje bo preplavljeno s pravičnostjo.',
        23: 'Kajti Gospod Bog nad bojevniki bo naredil uničenje, celo določeno, v sredi vse dežele.',
        24: 'Zato tako govori Gospod Bog nad bojevniki: ›Oh moje ljudstvo, ki prebivaš na Sionu, ne boj se Asirca. Udaril te bo s palico in svojo palico bo vzdignil zoper tebe po načinu Egipta.',
        25: 'Kajti še zelo kratek čas in ogorčenje bo prenehalo in moja jeza v njihovem uničenju.',
        26: 'Gospod nad bojevniki bo zanj razvnel bič, glede na pokol Midjána, pri Orébovi skali in kakor je bila njegova palica nad morjem, tako jo bo vzdignil po načinu Egipta.',
        27: 'Na tisti dan se bo zgodilo, da bo njegovo breme vzeto iz tvoje rame in njegov jarem iz tvojega vratu in jarem bo uničen zaradi maziljenja.',
        28: 'Prišel je v Ajo, prešel je do Migróna, pri Mihmášu je shranil svoje vozove.',
        29: 'Šli so preko prelaza. Pri Gebi so se nastanili, Rama je prestrašena, Savlova Gíbea je zbežala.',
        30: 'Povzdigni svoj glas, oh hči galímska. Povzroči mu, da bo ta slišan do Láješa, oh ubogi Anatót.',
        31: 'Madménah je odstranjen, prebivalci Gebíma so se zbrali skupaj, da pobegnejo.',
        32: 'Ta dan bo ostal pri Nobu. Svojo roko bo stresel zoper goro hčere sionske, jeruzalemski hrib.',
        33: 'Glej, Gospod, Gospod nad bojevniki, bo vejo obrezal s strahoto in tisti z visoko postavo bodo posekani in ošabni bodo ponižani.',
        34: 'Z železom bo posekal gozdne goščave in Libanon bo padel po mogočnem.',
    },
    11: {
        1: 'Palica bo pognala iz Jesejevega debla in Poganjek bo zrastel iz njegovih korenin',
        2: 'in Gospodov duh bo počival nad njim, duh modrosti in razumevanja, duh nasveta in moči, duh spoznanja in strahu Gospodovega.',
        3: 'Naredil ga bo hitrega razumevanja v strahu Gospodovem in ne bo sodil po pogledu svojih oči niti grajal po slišanju svojih ušes,',
        4: 'temveč bo s pravičnostjo sodil revne in odločal z nepristranskostjo krotkim na zemlji in zemljo bo udaril s palico svojih ust in z dihom svojih ustnic bo pokončal zlobnega.',
        5: 'Pravičnost bo pas njegovih ledij in zvestoba pas njegovih notranjosti.',
        6: 'Tudi volk bo prebival z jagnjetom in leopard se bo zleknil z otrokom. Tele, mlad lev in pitanček skupaj in vodil jih bo majhen otrok.',
        7: 'Krava in medvedka se bosta pasli, njuni mladiči se bodo skupaj ulegli in lev bo jedel slamo kakor vol.',
        8: 'Doječ otrok se bo igral na kobrini luknji in odstavljen otrok bo svojo roko položil na brlog strupene kače.',
        9: 'Ne bodo ne škodovali, ne uničevali na vsej moji sveti gori, kajti zemlja bo polna Gospodovega spoznanja, kakor vode pokrivajo morje.',
        10: 'Na ta dan bo Jesejeva korenina, ki bo stala kakor zastava ljudstvu; njo bodo pogani iskali in njegov počitek bo veličasten.',
        11: 'Na tisti dan se bo zgodilo, da bo Gospod ponovno, drugič, naravnal svojo roko, da obnovi preostanek svojega ljudstva, ki bo preostal od Asirije, od Egipta, od Patrósa, od Kuša, od Eláma, od Šinárja, od Hamáta in od morskih otokov.',
        12: 'Postavil bo zastavo za narode in zbral Izraelove pregnance in skupaj bo zbral razkropljene od Juda iz štirih koncev zemlje.',
        13: 'Tudi Efrájimova zavist bo odšla in Judovi nasprotniki bodo iztrebljeni. Efrájim ne bo zavidal Judu in Juda ne bo nadlegoval Efrájima.',
        14: 'Temveč bodo leteli na ramenih Filistejcev proti zahodu. Skupaj bodo oplenili tiste iz vzhoda, svojo roko bodo položili na Edóm in Moáb in Amónovi otroci jih bodo ubogali.',
        15: '§ Gospod bo popolnoma uničil jezik egiptovskega morja in s svojim mogočnim vetrom bo stresel svojo roko nad reko in udaril jo bo v sedem vodotokov in ljudem omogočil, da jih bodo prešli v sandalih.',
        16: 'Tam bo glavna cesta za preostanek njegovega ljudstva, ki bo preostalo od Asirije, kakor je bila za Izrael na dan, ko je prišel gor iz egiptovske dežele.',
    },
    12: {
        1: 'Na ta dan boš rekel: »Oh Gospod, hvalil te bom. Čeprav si bil jezen name, je tvoja jeza odvrnjena in me ti tolažiš.«',
        2: 'Glej, Bog je rešitev moje duše. Zaupal bom in ne bom prestrašen, kajti Gospod Jahve je moja moč in moja pesem; prav tako je postal rešitev moje duše.',
        3: 'Zatorej boste z radostjo zajemali vodo iz vodnjakov rešitve duš.',
        4: 'Na ta dan boste rekli: »Hvalimo Gospoda, kličimo njegovo ime, med ljudstvom razglašajmo njegova dela, omenjajmo, da je njegovo ime povišano.«',
        5: 'Prepevajmo Gospodu, kajti storil je odlične stvari. To je znano po vsej zemlji.',
        6: 'Zavriskaj in zavpij, ti prebivalec Siona, kajti velik je Sveti Izraelov v tvoji sredi.',
    },
    13: {
        1: 'Breme Babilona, ki ga je videl Izaija, Amócov sin.',
        2: 'Dvignite prapor na visoki gori, povzdignite jim glas, mahajte z roko, da lahko vstopijo v velika vrata plemičev.',
        3: 'Svojim posvečenim sem zapovedal, zaradi moje jeze sem poklical tudi moje mogočne, celó tiste, ki se razveseljujejo v mojem visočanstvu.',
        4: 'Hrup množice po gorah kakor od številnega ljudstva, bučen hrup kraljestev narodov, zbranih skupaj. Gospod nad bojevniki pregleduje vojsko za bitko.',
        5: 'Prihajajo iz daljne dežele, od konca neba, celó Gospod in orožja njegovega ogorčenja, da uničijo celotno deželo.',
        6: 'Tulite, kajti Gospodov dan je pri roki, ta bo prišel kakor uničenje od Vsemogočnega.',
        7: 'Zato bodo vse roke oslabele in srce vsakega človeka se bo stopilo',
        8: 'in bali se bodo. Ostre bolečine in bridkosti se jih bodo polastile. V bolečinah bodo kakor ženska, ki je v porodnih mukah. Osupli bodo drug nad drugim, njihovi obrazi bodo kakor plameni.',
        9: 'Glej, prihaja Gospodov dan, krut, z besom in silovito jezo, da naredi deželo opustošeno in njene grešnike bo pokončal iz nje.',
        10: 'Kajti zvezde neba in njegova ozvezdja ne bodo dajala svoje svetlobe. Sonce bo otemnelo v svojem vzhajanju in luna svoji svetlobi ne bo povzročila, da sveti.',
        11: 'Zemeljski [krog] bom kaznoval zaradi njihovega zla in zlobne zaradi njihove krivičnosti in povzročil bom, da se aroganca ponosnih konča in ponižal bom oholost strašnih.',
        12: 'Človeka bom naredil dragocenejšega kakor čisto zlato, celo človeka kakor zlat klin iz Ofírja.',
        13: 'Zato bom stresel nebo in zemlja se bo odmaknila iz svojega mesta, v besu Gospoda nad bojevniki in na dan njegove krute jeze.',
        14: 'In bo kakor preganjana srna in kakor ovca, ki je nihče ne ujame. Obrnili se bodo vsak človek k svojemu lastnemu ljudstvu in vsak bo bežal v svojo lastno deželo.',
        15: 'Vsak, kdor je najden, bo preboden in vsak, kdor jim je pridružen, bo padel pod mečem.',
        16: 'Tudi njihovi otroci bodo razbiti na koščke pred njihovimi očmi, njihove hiše bodo oplenjene in njihove žene posiljene.',
        17: 'Glej, zoper njih bom razvnel Medijce, ki se ne bodo ozirali na srebro in glede zlata, v njem se ne bodo razveseljevali.',
        18: 'Tudi njihovi loki bodo mladeniče raztreščili na koščke in ne bodo imeli usmiljenja do sadu maternice; njihovo oko ne bo prizaneslo otrokom.',
        19: 'Babilon, slava kraljestev, lepota kaldejske odličnosti, bo kakor, ko je Bog razdejal Sódomo in Gomóro.',
        20: 'Ta ne bo nikoli naseljen niti se ne bo prebivalo v njem od roda do roda, niti tam Arabec ne bo postavil šotora, niti tam pastirji ne bodo postavljali svojih staj.',
        21: 'Temveč bodo tam ležale divje puščavske živali in njihove hiše bodo polne otožnih živih ustvarjenih bitij in sove bodo prebivale tam in kozjenogi bodo tam plesali.',
        22: 'Divje živali z otokov bodo klicale v njihovih zapuščenih hišah in zmaji v njihovih prijetnih palačah in njen čas je blizu, da pride in njeni dnevi ne bodo podaljšani.',
    },
    14: {
        1: 'Kajti Gospod bo imel usmiljenje do Jakoba in bo še izbral Izrael in jih postavil v njihovo lastno deželo, in tujci bodo združeni z njimi in se bodo trdno pridružili Jakobovi hiši.',
        2: 'Ljudstvo jih bo vzelo in jih privedlo na njihov kraj. Izraelova hiša jih bo vzela v last v Gospodovi deželi za služabnice in pomočnice. Odvedli jih bodo ujete tisti, katerih ujetniki so bili in vladali bodo nad svojimi zatiralci.',
        3: 'Na ta dan se bo zgodilo, ko ti bo Gospod dal počitek pred tvojo bridkostjo, pred tvojim strahom in pred trdim suženjstvom, s čimer si bil primoran, da služiš,',
        4: 'da boš vzel ta pregovor zoper babilonskega kralja in rekel: »Kako je zatiralec končal! Zlato mesto je končalo!',
        5: 'Gospod je zlomil palico zlobnih in žezlo vladarjev.',
        6: 'Tisti, ki je v besu udaril ljudstvo z nenehnim udarcem, tisti, ki je narodom vladal v jezi, je preganjan in nihče ne zadržuje.',
        7: 'Celotna zemlja je pri počitku in mirna. Oni izbruhnejo v petje.',
        8: 'Da, ciprese se razveseljujejo ob tebi in libanonske cedre, rekoč: ›Odkar si položen dol, noben sekalec ni prišel zoper nas.‹',
        9: 'Pekel od spodaj vztrepetava zaradi tebe, da te sreča ob tvojem prihodu. Zaradi tebe razvnema mrtve, celó vse zemeljske vodje, iz njihovih prestolov je dvignil vse kralje narodov.',
        10: 'Vsi ti bodo govorili in ti rekli: ›Si tudi ti postal slaboten kakor mi? Si postal podoben nam?‹',
        11: 'Tvoj pomp je priveden dol h grobu in zvok tvojih lir. Ličinka se razteguje pod teboj in ličinke te pokrivajo.',
        12: '§ Kako si padel z neba, oh Lucifer, sin jutra! Kako si posekan na tla, ki si narode slabil!',
        13: 'Ker si rekel v svojem srcu: ›Vzpel se bom v nebesa, svoj prestol bom povzdignil nad Božje zvezde. Tudi na gori skupnosti bom sedel, na obronkih severa,',
        14: 'nad višine oblakov se bom dvignil, podoben bom Najvišjemu.‹',
        15: 'Vendar boš priveden dol v pekel, na obronke jame.',
        16: 'Tisti, ki te vidijo, te bodo natančno ogledovali in preudarjali, rekoč: ›Mar je to mož, ki je počel, da je zemlja trepetala, ki je pretresal kraljestva,',
        17: 'ki je naredil zemeljski [krog] kakor divjino in uničil njegova mesta, ki ni odprl hiše svojih ujetnikov?‹',
        18: 'Vsi kralji narodov, celó vsi izmed njih, ležijo v slavi, vsak v svoji lastni hiši.',
        19: 'Ti pa si izvržen iz svojega groba, kakor gnusna mladika in kakor oblačilo tistih, ki so umorjeni, prebodeni z mečem, ki gredo dol k jamskim kamnom, kakor truplo, pomendrano pod stopali.',
        20: 'Ne boš pridružen z njimi pri pokopu, ker si uničil svojo deželo in umoril svoje ljudstvo. Seme hudodelcev nikoli ne bo ugledno.',
        21: 'Pripravite pokol za njegove otroke zaradi krivičnosti njihovih očetov, da ne vstanejo niti ne vzamejo v last dežele niti ne napolnijo obličja zemeljskega [kroga] z mesti.',
        22: 'Kajti dvignil se bom proti njim,‹ govori Gospod nad bojevniki ›in iztrebil iz Babilona ime in ostanek, sina in nečaka,‹ govori Gospod.',
        23: '›Prav tako ga bom naredil posest za bobnarico in vodne tolmune in pometel ga bom z metlo uničenja,‹ govori Gospod nad bojevniki.',
        24: 'Gospod nad bojevniki je prisegel, rekoč: ›Zagotovo, kakor sem si zamislil, tako se bo zgodilo in kakor sem se namenil, tako bo ostalo,',
        25: 'da bom v svoji deželi zlomil Asirca in na svojih gorah ga bom pomendral pod stopalom. Potem bo njegov jarem odšel od njih in njegovo breme bo odšlo iz njihovih ramen.‹«',
        26: 'To je namen, ki je namenjen nad celotno zemljo, in to je roka, ki je iztegnjena nad vsemi narodi.',
        27: 'Kajti Gospod nad bojevniki se je namenil in kdo bo to razveljavil? Njegova roka je iztegnjena in kdo jo bo zavrnil?',
        28: 'To breme je bilo v letu, ko je kralj Aház umrl.',
        29: 'Ne razveseli se ti, celotna Filisteja, ker je palica tistega, ki te je udaril, zlomljena, kajti iz kačje korenine bo prišla strupena kača in njen sad bo ognjena leteča kača.',
        30: 'Prvorojenec revnega bo nahranjen in pomoči potreben se bo ulegel v varnosti in z lakoto bom ubil tvojo korenino, on pa bo pokončal tvoj preostanek.',
        31: 'Tulite, oh velika vrata, jokaj, oh mesto, ti, celotna Palestina si raztopljena, kajti iz severa bo prišel dim in nihče ne bo sam v svojih določenih časih.',
        32: 'Kaj bo nekdo potem odgovoril poslancem naroda? Da je Gospod ustanovil Sion in revni izmed njegovega ljudstva bodo zaupali vanj.',
    },
    15: {
        1: 'Breme Moába. Ker je ponoči Ar Moáb opustošen in priveden v tišino, ker je ponoči Kir Moáb opustošen in priveden v tišino;',
        2: '§ odšel je gor do Bajita in do Dibóna, visoka kraja, da bi jokal. Moáb bo tulil nad Nebójem in nad Médebo, na vseh njihovih glavah bo plešavost in vsaka brada bo odrezana.',
        3: 'Na njihovih ulicah se bodo opasovali z vrečevino, na vrhovih njihovih hiš in na njihovih ulicah bo vsakdo tulil, obilno jokajoč.',
        4: 'Hešbón bo vpil in Elalé. Njun glas bo slišati celó do Jahaca, zato bodo oboroženi moábski vojaki zavpili, njegovo življenje mu bo mučno.',
        5: 'Moje srce bo vpilo zaradi Moába, njegovi ubežniki bodo bežali do Coarja, telica starosti treh let, kajti ob vzpenjanju Luhíta bodo jokajoč šli gor, kajti na poti Horonájima bodo vzdignili krik pogube.',
        6: 'Kajti vode Nimríma bodo zapuščene, kajti seno je propadlo, trava je posušena, tam ni nobene zelene stvari.',
        7: 'Zato bodo obilje, ki so ga dobili in to, kar so nakopičili, odnesli proč k vrbovemu potoku.',
        8: 'Kajti vpitje je šlo naokoli Moábovih mej, njihovo tuljenje do Eglájima in njihovo tuljenje do Beêr Elíma.',
        9: 'Kajti vode Dimóna bodo polne krvi, kajti privedel bom več nad Dimón, leve nad tiste, ki pobegnejo iz Moába in nad preostanek dežele.',
    },
    16: {
        1: 'Pošljite jagnje k vladarju dežele iz Sele k divjini, h gori hčere sionske.',
        2: 'Kajti zgodilo se bo, da kakor je tavajoč ptič vržen iz gnezda, tako bodo moábske hčere pri prehodih Arnóna.',
        3: 'Posvetuj se, izvrši sodbo, svojo senco naredi kakor noč v sredi opoldneva, skrij pregnance, ne izdaj tistega, ki tava.',
        4: 'Naj moji pregnanci prebivajo s teboj, Moáb. Bodi jim skrivališče pred obličjem plenilca. Izsiljevalec je pri koncu, plenilec pojenjuje, kajti zatiralci so použiti iz dežele.',
        5: 'V usmiljenju bo prestol postavljen in sedel bo na njem v resnici, v Davidovem šotorskem svetišču, sodeč, iščoč sodbe in pospešujoč pravičnost.',
        6: 'Slišali smo o Moábovem ponosu; zelo je ponosen, celó o njegovi oholosti in njegovem ponosu in njegovem besu, toda njegove laži ne bodo takšne.',
        7: 'Zato bo Moáb tulil za Moábom, vsi bodo tulili, kajti temelji Kir Heresa bodo žalovali; zagotovo so udarjeni.',
        8: 'Kajti hešbónska polja pešajo in vino iz Sibme. Gospodarji poganov so zlomili njegove glavne sadike, prišli so celó do Jazêrja, tavali so skozi divjino. Njegovi poganjki se iztezajo, odšli so preko morja.',
        9: 'Zato bom z jokom objokoval sibmansko trto iz Jazêrja. Namakal te bom s svojimi solzami, oh Hešbón in Elaléja, zaradi vpitja za tvojimi poletnimi sadovi in ker je tvoja žetev propadla.',
        10: 'Veselje je odvzeto in radost iz obilnega polja in v vinogradih ne bo prepevanja niti ne bo vriskanja niti tam ne bo vpitja. Tlačitelji ne bodo tlačili nobenega vina v svojih stiskalnicah; njihovemu vriskanju ob trgatvi sem naredil, da odneha.',
        11: 'Zato bo moja notranjost zvenela kakor harfa za Moábom in moji notranji deli za Kir Heresom.',
        12: 'In zgodilo se bo, ko bo videno, da je Moáb izmučen na visokih krajih, da bo prišel k svojemu svetišču, da moli, toda ne bo prevladal.',
        13: 'To je beseda, ki jo je od tistega časa Gospod govoril glede Moába.',
        14: 'Toda sedaj je Gospod govoril, rekoč: »Znotraj treh let, kakor so najemnikova leta in Moábova slava bo zaničevana z vso tisto veliko množico in preostanek bo zelo majhen in slaboten.«',
    },
    17: {
        1: 'Breme Damaska: »Glej, Damask je odvzet od tega, da je mesto in bo kup razvalin.',
        2: 'Mesta Aroêrja so zapuščena. Ta bodo za trope, ki bodo legli in nihče jih ne bo strašil.',
        3: 'Trdnjava bo prav tako prenehala od Efrájima in kraljestvo od Damaska in preostanek iz Sirije. Oni bodo kakor slava Izraelovih otrok,« govori Gospod nad bojevniki.',
        4: '»Na tisti dan se bo zgodilo, da se bo Jakobova slava stanjšala in mastnost njegovega mesa bo shujšala.',
        5: 'To bo kakor ko žanjec zbira žito in s svojim laktom žanje klasje, in to bo kakor tisti, ki zbira klasje v dolini Rafájim.',
        6: 'Vendar bodo v njem ostali paberkovalni grozdi, kakor tresenje oljke, dve ali tri jagode na vrhu najvišje veje, štiri ali pet na njenih zunanjih rodovitnih mladikah,« govori Gospod, Izraelov Bog.',
        7: 'Na tisti dan bo človek gledal k svojemu Stvarniku in njegove oči bodo imele spoštovanje do Svetega Izraelovega.',
        8: 'Ne bo gledal k oltarjem, delu svojih rok niti ne bo spoštoval tega, kar so naredili njegovi prsti ali ašer ali podob.',
        9: 'Na tisti dan bodo njegova utrjena mesta kakor zapuščena veja in najvišja mladika, ki so jo pustili zaradi Izraelovih otrok in tam bo opustošenje.',
        10: 'Ker si pozabil Boga rešitve svoje duše in se nisi spominjal skale svoje moči, zato boš sadil prijetne rastline in jih cepil s tujimi cepljenci.',
        11: 'Podnevi boš svoji rastlini naredil, da zraste in zjutraj boš svojemu semenu naredil, da cveti, toda žetev bo kup na dan žalosti in obupne bridkosti.',
        12: 'Gorje množici številnih ljudi, ki zganjajo hrup, podoben hrupu morij in vrvežu narodov, ki delajo vrvež, podoben vrvežu mogočnih vodá!',
        13: 'Narodi bodo hiteli kakor besnenje mnogih vodá, toda Bog jih bo ukoril in pobegnili bodo daleč proč in pregnani bodo kakor pleve gora pred vetrom in kakor kotaleča se stvar pred vrtinčastim vetrom.',
        14: 'Glej, ob večernem času stiska in pred jutrom ga ni. To je delež tistih, ki nas plenijo in žreb tistih, ki nas ropajo.',
    },
    18: {
        1: 'Gorje deželi, zasenčeni s perutmi, ki je onkraj etiopskih rek,',
        2: '§ ki pošilja predstavnike po morju, celo v posodah iz ločja na vodah, rekoč: »Pojdite, vi nagli poslanci, k narodu, razkropljenemu in razgaljenemu, k ljudstvu, strašnemu od njihovega začetka do zdaj; narodu razdeljenemu in pomendranemu, katerega deželo so oplenile reke!',
        3: 'Vsi vi naseljenci zemeljskega [kroga] in prebivalci na zemlji, glejte, ko dviguje zastavo na gorah in ko zatrobi na šofar, prisluhnite.',
        4: 'Kajti tako mi je rekel Gospod: ›Vzel si bom počitek in preudaril bom v svojem bivališču, kakor sončna vročina na rastlinah in kakor oblak rose v vročini žetve.',
        5: '§ Kajti pred žetvijo, ko je brst popoln in kislo grozdje dozoreva v cvetu, bo z obdelovalnimi kavlji odrezal tako poganjke, kakor odvzel in odrezal mladike.',
        6: 'Skupaj bodo prepuščeni perjadi gora in zemeljskim živalim, in perjad bo na njih preživela čas žetve in vse zemeljske živali bodo prezimovale na njih.',
        7: 'V tistem času bo prineseno darilo Gospodu nad bojevniki, od ljudstva, razkropljenega in razgaljenega in od ljudstva, ki je strašno od svojega začetka do sedaj, naroda, ki je razdeljen in pomendran pod stopalom, katerega deželo so oplenile reke, do kraja imena Gospoda nad bojevniki, gore Sion.‹«',
    },
    19: {
        1: 'Breme Egipta. Glej, Gospod jaha na naglem oblaku in prišel bo v Egipt in egiptovski maliki bodo drhteli ob njegovi prisotnosti in srce Egipta se bo stopilo v njegovi sredi.',
        2: '»Egipčane bom naravnal zoper Egipčane in bojevali se bodo vsak zoper svojega brata in vsak zoper svojega soseda, mesto zoper mesto in kraljestvo zoper kraljestvo.',
        3: 'Egiptovski duh bo odpovedal v njihovi sredi in uničil bom njihov nasvet in iskali bodo k malikom in h krotilcem in k tistim, ki imajo osebne duhove in k čarovnikom.',
        4: 'Egipčane bom predal v roko krutega gospodarja in silovit kralj bo vladal nad njimi,« govori Gospod, Gospod nad bojevniki.',
        5: 'Vode iz morja se bodo posušile in reke bodo zapuščene in posušene.',
        6: 'Reke bodo obrnili daleč proč in obrambni jarki bodo izpraznjeni ter posušeni. Trstje in rogoz bo ovenelo.',
        7: '§ Papirno trstje pri potokih, pri ustju potokov in vsaka posejana stvar ob potokih bo ovenela, bo odgnana in ne bo je več.',
        8: 'Tudi ribiči bodo žalovali in vsi tisti, ki mečejo trnek v potoke, bodo žalovali in tisti, ki razširjajo mreže nad vodami, bodo pešali.',
        9: 'Poleg tega bodo zbegani tisti, ki delajo s tankim lanom in tisti, ki tkejo mreže.',
        10: '§ Zlomljeni bodo v svojih namenih vsi, ki delajo zapornice in ribnike za ribe.',
        11: 'Zagotovo so princi Coana bedaki, nasvet modrih faraonovih svetovalcev je postal brutalen. Kako pravite faraonu: »Jaz sem sin modrega, sin starodavnih kraljev?«',
        12: 'Kje so tisti? Kje so tvoji modri možje? In naj ti sedaj povedo in naj vedo kaj je Gospod nad bojevniki namenil nad Egiptom.',
        13: 'Princi Coana so postali bedaki, princi Nofa so zavedeni, zapeljali so tudi Egipt, celó tiste, ki so opora njegovih rodov.',
        14: 'Gospod je v njihovo sredo pomešal sprevrženega duha in Egiptu so storili, da se moti v vsakem svojem delu, kakor se pijan mož opoteka v svojem bruhanju.',
        15: 'Niti tam ne bo nobenega dela za Egipt, ki bi ga glava ali rep, palmova veja ali ločje lahko opravili.',
        16: 'Na tisti dan bo Egipt podoben ženski in bo prestrašen in bal se bo zaradi tresenja roke Gospoda nad bojevniki, ki jo trese nad njim.',
        17: 'Judova dežela bo strahota Egiptu. Vsak, kdor jo omenja, bo v sebi prestrašen zaradi namena Gospoda nad bojevniki, ki ga je določil zoper njega.',
        18: '§ Na tisti dan bo pet mest v egiptovski deželi govorilo kánaanski jezik in prisegalo pri Gospodu nad bojevniki; eno bo imenovano Mesto uničenja.',
        19: 'Na tisti dan bo tam oltar Gospodu v sredi egiptovske dežele in steber Gospodu pri njegovi meji.',
        20: 'Ta bo za znamenje in za pričevanje Gospodu nad bojevniki v egiptovski deželi, kajti klicali bodo h Gospodu zaradi zatiralcev in poslal jim bo rešitelja in mogočnega in ta jih bo osvobodil.',
        21: 'Gospod bo znan Egiptu in Egipčani bodo na tisti dan poznali Gospoda in opravljali klavno daritev in darovanje. Da, prisegali bodo prisego h Gospodu in jo izvedli.',
        22: 'Gospod bo udaril Egipt. Udaril ga bo in ozdravil in vrnili se bodo celó h Gospodu in izprošen bo od njih in jih bo ozdravil.',
        23: 'Na tisti dan bo tam glavna cesta iz Egipta v Asirijo in Asirec bo prišel v Egipt in Egipčan v Asirijo in Egipčani bodo služili z Asirci.',
        24: 'Na tisti dan bo Izrael tretji z Egiptom in Asirijo, celó blagoslov v sredi dežele,',
        25: 'ki ga bo Gospod nad bojevniki blagoslovil, rekoč: »Blagoslovljen bodi Egipt, moje ljudstvo in Asirija, delo mojih rok in Izrael, moja dediščina.«',
    },
    20: {
        1: '§ V letu, ko je Tartan prišel v Ašdód (ko ga je asirski kralj Sargon poslal) in se boril zoper Ašdód in ga zavzel,',
        2: 'ob istem času je spregovoril Gospod po Izaiju, Amócovemu sinu, rekoč: »Pojdi in odveži vrečevino s svojih ledij in sezuj si čevelj s svojega stopala.« In storil je tako, hodeč nag in bos.',
        3: 'Gospod je rekel: »Podobno kot moj služabnik Izaija tri leta hodi nag in bos za znamenje in čudo nad Egiptom in nad Etiopijo,',
        4: 'tako bo asirski kralj odvedel Egipčane ujetnike in Etiopijce ujetnike, mlade in stare, nage in bose, celo z njihovimi nepokritimi zadnjicami, v egiptovsko sramoto.',
        5: 'Bali se bodo in osramočeni bodo od Etiopije, njihovega pričakovanja in od Egipta, njihove slave.',
        6: 'Prebivalec tega otoka bo na tisti dan rekel: ›Glej, takšno je naše pričakovanje, kamor smo pobegnili po pomoč, da bi bili osvobojeni pred asirskim kraljem in kako bomo pobegnili?‹«',
    },
    21: {
        1: 'Breme puščave morja. Kakor gredo skozi vrtinčasti vetrovi na jugu, tako ta prihaja iz puščave, iz strašne dežele.',
        2: 'Mučno videnje mi je naznanjeno, zahrbtnež postopa zahrbtno in plenilec pleni. Pojdi gor, oh Elám. Oblegaj, oh Medija. Vsemu njihovemu vzdihovanju sem storil, da preneha.',
        3: 'Zato so moja ledja napolnjena z bolečino. Polastile so se me ostre bolečine kakor ostre bolečine ženske, ki je v porodnih mukah. Sklonjen sem bil ob poslušanju tega, ob gledanju tega sem bil zaprepaden.',
        4: 'Moje srce trepeta, grozljivost me je preplašila. Noč mojega užitka mi je obrnil v strah.',
        5: 'Pripravite mizo, stražite v stražnem stolpu, jejte, pijte. Vstanite, vi princi in pomazilite ščit.',
        6: 'Kajti tako mi je rekel Gospod: »Pojdi, postavi stražarja, naj razglasi, kar vidi.«',
        7: 'Ta je zagledal bojni voz z nekaj konjeniki, voz z osli in voz s kamelami in marljivo prisluhnil z mnogo pozornosti',
        8: 'ter zavpil: »Lev. ›Moj Gospod, nenehno stojim na stražnem stolpu podnevi in na svojo stražo sem postavljen cele noči',
        9: 'in glej, sem prihaja bojni voz z možmi, z nekaj konjeniki.‹« Odgovoril je in rekel: »Babilon je padel, padel je in vse rezane podobe njegovih bogov je zdrobil na tla.«',
        10: 'Oh moja mlatev in žito mojih tal. To, kar sem slišal od Gospoda nad bojevniki, Izraelovega Boga, sem vam naznanil.',
        11: 'Breme o Dumi. Kliče me iz Seírja: »Stražar, kaj je glede noči? Stražar, kaj je glede noči?«',
        12: 'Stražar je rekel: »Prihaja jutro in tudi noč. Če hočete poizvedeti, poizvejte. Vrnite se, pridite.«',
        13: 'Breme nad Arabijo. V arabskem gozdu boste prenočevale, oh ve, potujoče skupine Dedánovcev.',
        14: 'Prebivalci dežele Temá so prinesli vodo tistemu, ki je bil žejen. Tistega, ki je bežal, so prestregli s svojim kruhom.',
        15: 'Kajti pobegnili so pred meči, pred izvlečenim mečem, pred napetim lokom in pred bolečino vojne.',
        16: 'Kajti tako mi je rekel Gospod: »Znotraj leta, glede na najemnikova leta in vsa slava Kedárja bo padla.',
        17: 'Preostanek izmed števila lokostrelcev, močni možje izmed kedárskih otrok, bodo zmanjšani,« kajti Gospod, Izraelov Bog, je to govoril.',
    },
    22: {
        1: 'Breme doline videnj. Kaj te sedaj pesti, da si v celoti odšel gor k hišnim streham?',
        2: 'Ti, ki si poln razgrajanja, hrupno mesto, radostno mesto. Tvoji umorjeni možje niso umorjeni z mečem niti niso umrli v bitki.',
        3: 'Vsi tvoji vladarji so skupaj pobegnili. Zvezani so z lokostrelci. Vsi, ki so najdeni v tebi, so zvezani skupaj, ki so pobegnili od daleč.',
        4: 'Zatorej sem rekel: »Poglejte proč od mene, grenko bom jokal, ne trudite se, da bi me potolažili zaradi plenjenja hčere mojega ljudstva.',
        5: 'Kajti to je dan stiske, mendranja in zmedenosti od Gospoda Boga nad bojevniki v dolini videnja, podiranja zidov in vpitja h goram.',
        6: 'Elám je nosil tul z bojnimi vozovi mož in konjeniki in Kir je odkril ščit.',
        7: 'In zgodilo se bo, da bodo tvoje izbrane doline polne vozov in konjeniki se bodo postrojili pri velikih vratih.',
        8: 'Odkril je Judovo pokrivalo in na tisti dan si pogledal k bojni opremi gozdne hiše.',
        9: 'Videli ste tudi vrzeli Davidovega mesta, da jih je mnogo in zbrali ste skupaj vode spodnjega ribnika.',
        10: 'Prešteli ste jeruzalemske hiše in porušili hiše, da utrdite obzidje.',
        11: 'Naredili ste tudi jarek med dvema zidovoma za vodo iz starega ribnika, toda niste pogledali k njegovemu izdelovalcu niti niste imeli spoštovanja do tistega, ki ga je dolgo nazaj oblikoval.',
        12: 'Na tisti dan je Gospod Bog nad bojevniki klical k jokanju, žalovanju, k plešavosti in k opasovanju z vrečevino',
        13: 'in glej, radost in veselje, klanje volov in ubijanje ovc, žrtje mesa in pitja vina. Jejmo in pijmo, kajti jutri bomo umrli.',
        14: 'To je bilo razodeto v moja ušesa po Gospodu nad bojevniki: »Zagotovo ta krivičnost ne bo očiščena od vas, dokler ne umrete,« govori Gospod Bog nad bojevniki.',
        15: 'Tako govori Gospod Bog nad bojevniki: »Pojdi, stopi k temu zakladniku, celó k Šebnáju, ki je nad hišo in reci:',
        16: '›Kaj imaš tukaj? In koga imaš tukaj, da si si tukaj izklesal mavzolej kakor kdor si kleše mavzolej na višavi in ki zase vrezuje prebivališče v skali?',
        17: 'Glej, Gospod te bo odvedel proč z mogočnim ujetništvom in zagotovo te bo pokril.',
        18: 'Zagotovo se bo nasilno obrnil in te zalučal kakor žogo v veliko deželo. Tam boš umrl in tam bodo vozovi tvoje slave sramota hiši tvojega gospoda.',
        19: '»Odgnal te bom iz tvojega položaja in iz tvojega mesta te bo zvrnil.',
        20: 'Na tisti dan se bo zgodilo, da bom poklical svojega služabnika Eljakíma, Hilkijájevega sina.',
        21: 'Oblekel ga bom s tvojim svečanim oblačilom, ga ojačal s tvojim pasom in tvojo vlado bom izročil v njegovo roko in on bo oče jeruzalemskim prebivalcem in Judovi hiši.',
        22: 'Ključ Davidove hiše bom položil na njegovo ramo; tako bo odprl in nihče ne bo zaprl; in zaprl bo in nihče ne bo odprl.',
        23: 'Pritrdil ga bom kakor žebelj na zanesljivo mesto in on bo za veličasten prestol hiši svojega očeta.',
        24: 'Nanj bodo obesili vso slavo hiše njegovega očeta, potomstvo in pregnance, vse posode majhne količine, od čašastih posod, celo do vseh posod iz usnja.',
        25: 'Na ta dan,« govori Gospod nad bojevniki, »bo žebelj, ki je bil pritrjen na zanesljivem kraju, odstranjen, posekan in pade; in breme, ki je bilo na njem, bo odsekano,« kajti Gospod je to govoril.',
    },
    23: {
        1: 'Breme [naselbine] Tir. Tulite, ve ladje iz Taršíša, kajti ta je opustošena, tako da tam ni nobene hiše niti vhoda vanjo; od dežele Kitéjcev jim je razodeto.',
        2: 'Bodite mirni, vi prebivalci otoka, vi, ki so jih sidónski trgovci, ki prečkajo morje, na novo napolnili.',
        3: 'Ob velikih vodah je seme Šihórja, žetev reke, njeno poplačilo in ona je dobiček narodom.',
        4: 'Bodi osramočen, oh Sidón, kajti morje je spregovorilo, celó moč morja, rekoč: »Ne mučim se, niti ne rojevam otrok, niti ne negujem mladeničev, niti ne vzgajam devic.',
        5: 'Kakor ob poročilu glede Egipta, tako bodo boleče zaskrbljeni ob poročilu iz [naselbine] Tir.',
        6: 'Prepeljite se v Taršíš; tulite, vi prebivalci otoka.',
        7: 'Ali je to vaše radostno mesto, katerega starodavnost je od starodavnih dni? Njegova lastna stopala ga bodo odnesla daleč, da začasno biva.',
        8: 'Kdo je sprejel ta nasvet zoper [naselbino] Tir, obkrožujoče mesto, čigar trgovci so princi, čigar preprodajalci so častitljivi [ljudje] zemlje?',
        9: 'Gospod nad bojevniki je to namenil, da omadežuje ponos vse slave in da privede v zaničevanje vse častitljive [ljudi] zemlje.',
        10: '§ Prečkaj skozi svojo deželo kakor reka, oh taršíška hči. Tam ni več nobene moči.',
        11: 'Svojo roko je iztegnil nad morje, stresel je kraljestva. Gospod je izdal zapoved zoper trgovsko mesto, da uniči njegova močna oporišča.',
        12: 'Rekel je: »Ne boš se več razveseljevala, oh ti zatirana devica, hči sidónska. Vstani, prečkaj h Kitéjcem; tudi tam ne boš imela počitka.',
        13: 'Glej, dežela Kaldejcev; tega ljudstva ni bilo, dokler ga ni Asirec osnoval za tiste, ki prebivajo v divjini. Postavili so njegove stolpe, vzdignili so njegove palače; in privedel ga je do ruševin.',
        14: 'Tulite ve ladje iz Taršíša, kajti vaša moč je opustošena.',
        15: 'Na tisti dan se bo zgodilo, da bo [naselbina] Tir pozabljena sedemdeset let, glede na dneve enega kralja. Po koncu sedemdesetih let bo [naselbina] Tir pela kakor pocestnica.',
        16: 'Vzemi harfo, pojdi okoli mesta, ti pocestnica, ki si bila pozabljena; naredi prijetno melodijo, poj mnoge pesmi, da se te bodo lahko spomnili.',
        17: 'Po koncu sedemdesetih let se bo zgodilo, da bo Gospod obiskal [naselbino] Tir in se obrnil k njenemu plačilu in zagrešila bo prešuštvovanje, z vsemi kraljestvi sveta, na obličju zemlje.',
        18: 'Njeno trgovsko blago in njena nagrada bosta sveta Gospodu. To ne bo več shranjeno niti kopičeno, kajti njen trgovski dobiček bo za tiste, ki prebivajo pred Gospodom, da bodo zadostno jedli in za trpežno oblačilo.',
    },
    24: {
        1: 'Glej, Gospod prazni zemljo in jo pustoši in jo prevrača in razpršuje njene prebivalce.',
        2: 'Zgodilo se bo, kakor z ljudstvom, tako z duhovnikom; kakor s služabnikom, tako z njegovim gospodarjem; kakor s služabnico, tako z njeno gospodarico; kakor s kupcem, tako s prodajalcem; kakor s tistim, ki posoja, tako z izposojevalcem; kakor z jemalcem obresti, tako s tistim, ki mu daje obresti.',
        3: 'Dežela bo popolnoma izpraznjena in popolnoma oplenjena, kajti Gospod je spregovoril to besedo.',
        4: 'Zemlja žaluje in bledi, zemeljski [krog] peša in bledi, ošabno ljudstvo zemlje peša.',
        5: 'Tudi zemlja je omadeževana pod njenimi prebivalci, ker so prekršili postave, spremenili odredbo, prelomili večno zavezo.',
        6: 'Zato je prekletstvo požrlo zemljo in tisti, ki prebivajo na njej, so zapuščeni. Zato so prebivalci zemlje požgani in ostalo je le malo mož.',
        7: 'Novo vino žaluje, trta peša, vsi veselo–srčni vzdihujejo.',
        8: 'Veselje bobničev pojenjuje, hrup tistih, ki se veselijo, se končuje, radost harfe pojenjuje.',
        9: 'Vina ne bodo pili s pesmijo; močna pijača bo grenka tistim, ki jo pijejo.',
        10: 'Mesto zmešnjave je zlomljeno. Vsaka hiša je zaprta, da noben človek ne more vstopiti.',
        11: 'Tam je na ulicah jokanje zaradi vina; vsa radost je otemnela, veselje dežele je odšlo.',
        12: 'V mestu je ostalo opustošenje in velika vrata so udarjena z uničenjem.',
        13: 'Ko bo tako v sredi dežele med ljudstvom, bo tam kakor otresanje oljke in kakor paberkovanje grozdov, ko je trgatev končana.',
        14: 'Povzdignili bodo svoj glas, peli bodo zaradi Gospodovega veličanstva, glasno bodo klicali od morja.',
        15: 'Zatorej proslavljajte Gospoda v ognjih, celó ime Gospoda, Izraelovega Boga, na morskih otokih.',
        16: 'Od skrajnih delov zemlje smo slišali pesmi, celó slavo k pravičnemu. Toda rekel sem: »Moja pustost, moja pustost, gorje meni! Zahrbtneži so postopali zahrbtno; da, zahrbtneži so postopali zelo zahrbtno.«',
        17: 'Strah, jama in zanka so nad teboj, oh prebivalec zemlje.',
        18: 'Zgodilo se bo, da kdor pobegne pred hrupom strahu, bo padel v jamo; in kdor prihaja gor iz srede jame, bo ujet v zanko, kajti okna od zgoraj so odprta in temelji zemlje se tresejo.',
        19: 'Zemlja je popolnoma razrušena, zemlja je čisto raztopljena, zemlja je silno premaknjena.',
        20: 'Zemlja se bo opotekala sem ter tja kakor pijanec in odstranjena bo kakor koča in njen prestopek bo težak nad njo in ta bo padla in ne bo ponovno vstala.',
        21: 'Na tisti dan se bo zgodilo, da bo Gospod kaznoval vojsko vzvišenih, ki so na višavi in zemeljske kralje na zemlji.',
        22: '§ Zbrani bodo skupaj, kakor so jetniki zbrani v jami in zaprti bodo v ječi in po mnogih dneh bodo obiskani.',
        23: 'Potem bo luna zbegana in sonce osramočeno, ko bo Gospod nad bojevniki veličastno kraljeval na gori Sion in v Jeruzalemu in pred njegovimi starci.',
    },
    25: {
        1: 'Oh Gospod, ti si moj Bog; poviševal te bom, hvalil bom tvoje ime, kajti storil si čudovite stvari; tvoji nasveti od davnine so zvestoba in resnica.',
        2: 'Kajti iz mesta si naredil kup; iz obrambnega mesta razvalino, da palača tujcev ni več mesto; ta ne bo nikoli zgrajena.',
        3: 'Zato te bo močno ljudstvo proslavljalo in mesto strašnih narodov se te bo balo.',
        4: 'Kajti bil si moč revnim, moč pomoči potrebnim v njihovi tegobi, zatočišče pred viharjem, senca pred vročino, ko je udar strahovitežev kakor vihar proti zidu.',
        5: 'Hrup tujcev boš ponižal kakor vročino na suhem kraju, celó vročino s senco oblaka; mladika strahovitežev bo ponižana.',
        6: 'Na tej gori bo Gospod nad bojevniki vsem ljudstvom pripravil praznovanje mastnih stvari, praznovanje vin na drožeh, mastnih stvari, polnih mozga, dobro prečiščenih, dolgo hranjenih vin.',
        7: 'Na tej gori bo uničil obličje zagrinjala, vrženega nad vsa ljudstva in zagrinjalo, ki je razprostrto nad vsemi narodi.',
        8: 'V zmagi bo pogoltnil smrt. Gospod Bog bo obrisal solze iz vseh obrazov in sramoto svojega ljudstva bo vzel proč iz vse zemlje, kajti Gospod je to govoril.',
        9: 'Na ta dan bo rečeno: »Glejte! To je naš Bog; čakali smo nanj in on nas bo rešil. To je Gospod; čakali smo nanj, veseli bomo in se razveseljevali v njegovi rešitvi duše.«',
        10: 'Kajti na tej gori bo počivala Gospodova roka in Moáb bo pomendran pod njim, celo kakor je slama pomendrana za gnojišče.',
        11: 'Svoje roke bo razširil v njihovi sredi, kakor kdor plava razširja svoje roke za plavanje. Njihov ponos bo ponižal skupaj s pleni njihovih rok.',
        12: 'Trdnjavo visoke utrdbe tvojega obzidja bo ponižal, nizko položil in privedel k tlom, celó k prahu.',
    },
    26: {
        1: 'Na tisti dan bo ta pesem prepevana v Judovi deželi: »Imamo močno mesto; rešitev duše bo Bog določil za zidove in branike.',
        2: 'Odprite velika vrata, da bo pravičen narod, ki varuje resnico, lahko vstopil.',
        3: 'Ohranil ga boš v popolnem miru, čigar um se zadržuje na tebi, ker on zaupa vate.',
        4: 'Zaupajte v Gospoda na veke, kajti v Gospodu Jahveju je večna moč.',
        5: 'Kajti on poniža tiste, ki prebivajo na višavi; vzvišeno mesto, polaga ga nizko, polaga ga nizko, celó k tlom; prinaša ga celo k prahu.',
        6: 'Stopalo ga bo pomendralo, celó stopalo revnega in koraki pomoči potrebnih.«',
        7: 'Pot pravičnih je poštenost. Ti, najpokončnejši, tehtaš stezo pravičnih.',
        8: 'Da, na poti tvojih sodb, oh Gospod, smo čakali nate; hrepenenje naše duše je k tvojemu imenu in k spominu nate.',
        9: 'S svojo dušo sem te želel ponoči; da, s svojim duhom znotraj sebe te bom iskal zgodaj, kajti ko so tvoje sodbe na zemlji, se bodo prebivalci zemeljskega [kroga] učili pravičnosti.',
        10: 'Naj bo naklonjenost pokazana zlobnemu, vendar se ne bo naučil pravičnosti. V deželi poštenosti bo ravnal nepravično in ne bo gledal Gospodovega veličanstva.',
        11: 'Gospod, kadar je tvoja roka dvignjena, ne bodo videli. Toda videli bodo in bodo osramočeni zaradi svoje zavisti nad ljudstvom; da, požrl jih bo ogenj tvojih sovražnikov.',
        12: 'Gospod, ti nam hočeš določiti mir, kajti naredil si tudi vsa naša dela v nas.',
        13: 'Oh Gospod, naš Bog, drugi gospodarji poleg tebe so imeli gospostvo nad nami, toda samo po tebi bomo naredili omembo tvojega imena.',
        14: 'Mrtvi so, ne bodo živeli; preminuli so, ne bodo vstali. Zato si jih obiskal, uničil in storil, da ves spomin nanje izgine.',
        15: 'Povečal si narod, oh Gospod, ti si povečal narod. Proslavljen si. Odstranil si ga daleč, k vsem koncem zemlje.',
        16: 'Gospod, v stiski so te obiskali, izlili so molitev, ko je bilo nad njimi tvoje karanje.',
        17: 'Kakor je nosečnica, ko se približuje čas njenega poroda, v bolečini in vpije v svojih ostrih bolečinah, tako smo bili mi v tvojem pogledu, oh Gospod.',
        18: 'Bili smo z otrokom, bili smo v bolečini, tako smo, kakor bi rodili veter; na zemlji nismo dosegli nobene osvoboditve; niti prebivalci zemeljskega [kroga] niso padli.',
        19: 'Tvoji mrtvi možje bodo živeli, skupaj z mojim truplom bodo vstali. Zbudite se in pojte, vi, ki prebivate v prahu, kajti tvoja rosa je kakor rosa zelišč in zemlja bo izvrgla mrtve.',
        20: 'Pridite, moje ljudstvo, vstopite v svoje sobe in zaprite svoja vrata naokoli sebe. Skrijte se, kakor bi bilo za kratek trenutek, dokler ne bo ogorčenje minilo.',
        21: 'Kajti, glejte, Gospod prihaja iz svojega kraja, da kaznuje prebivalce zemlje zaradi njihove krivičnosti. Tudi zemlja bo razkrila svojo kri in ne bo več pokrivala svojih umorjenih.',
    },
    27: {
        1: 'Na tisti dan bo Gospod s svojim bridkim, velikim in močnim mečem kaznoval leviatána in ostro kačo, celó leviatána, to sprijeno kačo in pokončal bo zmaja, ki je v morju.',
        2: 'Na tisti dan ji pojte: »Vinograd rdečega vina.«',
        3: 'Jaz, Gospod, ga varujem; vsak trenutek ga bom zalival. Da ga ne bi kdorkoli poškodoval, ga bom varoval noč in dan.',
        4: 'Razjarjenosti ni v meni. Kdo bi zoper mene v bitki postavil osat in trnje? Šel bi skoznje, skupaj bi jih požgal.',
        5: 'Ali pa naj se oprime moje moči, da lahko sklene mir z menoj in sklenil bo mir z menoj.',
        6: 'Tistim, ki pridejo iz Jakoba, bo povzročil, da se ukoreninijo. Izrael bo cvetel, brstel in obličje zemeljskega [kroga] bo napolnil s sadom.',
        7: 'Mar ga je udaril, kakor je on udaril tiste, ki so ga udarili? Mar je umorjen glede na pokol tistih, ki so umorjeni po njem?',
        8: 'Po meri, ko ta poganja naprej, boš razpravljal z njim. On ustavlja njegov oster veter na dan vzhodnika.',
        9: 'Torej s tem bo Jakobova krivičnost očiščena in to je ves sad, da odvzame njegov greh, ko vse oltarne kamne naredi kakor apnenčaste kamne, ki so raztreščeni narazen; ašere in podobe ne bodo obstale.',
        10: 'Vendar bo obrambno mesto opustelo in prebivališče zapuščeno in opuščeno kakor divjina. Tam se bo paslo tele in tam se bo uleglo in použilo njegove mladike.',
        11: 'Ko njegove veje ovenijo, bodo odlomljene. Prišle bodo ženske in jih zažgale. Kajti to je ljudstvo brez razumevanja, zato tisti, ki jih je naredil, ne bo imel usmiljenja do njih in kdor jih je oblikoval, jim ne bo izkazal nobene naklonjenosti.',
        12: 'Na tisti dan se bo zgodilo, da bo Gospod otepal od rečnega kanala do egiptovskega vodotoka in zbrani boste drug za drugim, oh vi, Izraelovi otroci.',
        13: 'Na tisti dan se bo zgodilo, da bo zatrobljeno na velik šofar in prišli bodo, ki so bili pripravljeni, da se pogubijo v asirski deželi in [ki so bili] pregnanci v egiptovski deželi in oboževali bodo Gospoda na sveti gori pri Jeruzalemu.',
    },
    28: {
        1: 'Gorje kroni ponosa, efrájimskim pijancem, katerih veličastna lepota je odcvetena roža, ki je na čelu obilnih dolin tistih, ki so premagani z vinom.',
        2: 'Glej, Gospod ima mogočnega in močnega, ki bo kakor neurje s točo in uničujoč vihar, kakor poplava mogočnih vodá, ki preplavljajo, z roko vrgel dol k zemlji.',
        3: 'Krona ponosa, efrájimski pijanci, bodo pomendrani pod stopali.',
        4: 'Veličastna lepota, ki je na čelu obilne doline, bo veneča roža in kakor zgodnji sad pred poletjem; ko ga tisti, ki pogleda nanj, vidi, ga pojé, medtem ko je še v njegovi roki.',
        5: 'Na tisti dan bo Gospod nad bojevniki za krono slave in za diadem lepote preostanku svojega ljudstva',
        6: 'in za duha sodbe tistemu, ki sedi na sodbi in za moč tistim, ki bitko odvračajo k velikim vratom.',
        7: 'Vendar so tudi oni zašli zaradi vina in zaradi močne pijače so omahnili iz poti; duhovnik in prerok sta zašla zaradi močne pijače, pogoltnjena sta od vina, zaradi močne pijače sta omahnila iz poti; motita se v videnju, spotikata se v sodbi.',
        8: 'Kajti vse mize so polne izbljuvkov in umazanosti, tako da tam ni čistega prostora.',
        9: 'Koga bo učil spoznanja? In koga bo pripravil, da razume nauk? Tiste, ki so odstavljeni od mleka in odtegnjeni od prsi.',
        10: 'Kajti predpis mora biti na predpis, predpis na predpis; ukaz na ukaz, ukaz na ukaz; malo tukaj in malo tam,',
        11: 'kajti z jecljajočimi ustnicami in drugim jezikom bo govoril temu ljudstvu.',
        12: 'Katerim je rekel: »To je počitek, s katerim lahko izmučenemu storite, da počiva in to je osvežitev.« Vendar niso hoteli poslušati.',
        13: 'Toda Gospodova beseda jim je bila predpis na predpis, predpis na predpis; ukaz na ukaz, ukaz na ukaz; malo tukaj in malo tam; da lahko gredo, padejo vznak, se zlomijo, se ulovijo in ujamejo.',
        14: 'Zato poslušajte Gospodovo besedo, vi posmehljivci, ki vladate temu ljudstvu, ki je v Jeruzalemu.',
        15: 'Ker ste rekli: »Sklenili smo zavezo s smrtjo in s peklom smo v dogovoru. Ko bo šel skozi poplavljajoč bič, ta ne bo prišel k nam, kajti laži smo naredili za svoje zatočišče in pod neresnico smo se skrili.«',
        16: 'Zato tako govori Gospod Bog: »Glej, na Sionu polagam za temelj kamen, preizkušen kamen, dragocen vogalni kamen, postavljen temelj. Kdor veruje, ne bo vznemirjeno hitel.',
        17: 'Tudi sodbo bom položil k merilu in pravičnost h grezilu in toča bo pomedla zatočišče laži in vode bodo preplavile skrivališče.',
        18: 'Vaša zaveza s smrtjo bo razveljavljena in vaš dogovor s peklom ne bo obstal; ko bo skozi šel preplavljajoč bič, potem boste z njim pomendrani.',
        19: 'Od časa, ko gre ta naprej, vas bo zgrabil, kajti jutro za jutrom bo ta prehajal, podnevi in ponoči. To bo samo draženje, da razume poročilo.',
        20: 'Kajti postelja je krajša, kakor se človek lahko iztegne na njej in pokrivalo ožje, kakor se lahko zavije vanj.',
        21: 'Kajti Gospod se bo dvignil kakor na gori Peracím, ogorčen bo kakor v dolini Gibeón, da lahko opravi svoje delo, svoje čudno delo in privede, da se njegovo dejanje zgodi, njegovo čudno dejanje.',
        22: 'Zdaj torej ne bodite zasmehovalci, da ne bi vaše vezi postale močne, kajti od Gospoda Boga nad bojevniki sem slišal uničenje, celo določeno nad celotno zemljo.',
        23: 'Pazljivo prisluhnite in poslušajte moj glas, prisluhnite in poslušajte moj govor.',
        24: 'Mar orač orje ves dan, da bi sejal? Ali odpira in brana svojo zemljo?',
        25: 'Ko je njeno površino izravnal, mar ne meče naokoli pire, raztrosi kumino in meče noter glavno pšenico in določen ječmen in piriko na njihov prostor?',
        26: 'Kajti njegov Bog ga navaja k preudarnosti in ga uči.',
        27: 'Kajti pira ni mlatena z mlatilno pripravo niti kolo voza obračano nad kumino, temveč je pira otepana s palico in kumina s šibo.',
        28: '§ Krušno žito je zmleto, ker ga nikoli ne bo mlatil niti lomil s kolesom svojega voza niti ga poškodoval s konjeniki.',
        29: 'Tudi to prihaja od Gospoda nad bojevniki, ki je čudovit v nasvetu in odličen v delu.',
    },
    29: {
        1: '§ Gorje Ariélu, Ariélu, mestu, kjer je prebival David! Dodajte letu leto; naj ubijejo žrtve.',
        2: 'Vendar bom Ariél spravil v tegobo in tam bo potrtost in bridkost in ta mi bo kakor Ariél.',
        3: 'Utaboril se bom naokoli zoper tebe in zoper tebe bom položil obleganje z nasipom in zoper tebe bom dvignil utrdbe.',
        4: 'Ponižan boš in govoril boš iz zemlje in tvoj govor iz prahu bo znižan in tvoj glas bo kakor od nekoga, ki ima osebnega duha iz zemlje in tvoj govor bo šepetal iz prahu.',
        5: 'Poleg tega bo množica tvojih tujcev podobna drobnemu prahu in množica strahovitežev bo kakor pleve, ki mineva. Da, to bo v trenutku, nenadoma.',
        6: 'Od Gospoda nad bojevniki boš obiskan z gromom in s potresom in z velikim hrupom, z viharjem, neurjem in plamenom požirajočega ognja.',
        7: 'Množica vseh narodov, ki se bori zoper Ariél, celo vsi, ki se borijo proti njemu in njegovemu oporišču in ki ga stiskajo, bodo kakor sanje nočnega videnja.',
        8: 'To bo torej kakor kadar lačen človek sanja in glej, on jé; toda zbuja se, njegova duša pa je prazna. Ali kakor kadar žejen človek sanja in glej pije; toda zbudi se in glej, je oslabel, njegova duša pa ima apetit. Takšna bo množica vseh narodov, ki se borijo zoper goro Sion.',
        9: 'Ustavite se in se čudite, strmite in glejte. Pijani so, toda ne zaradi vina; omahujejo, toda ne zaradi močne pijače.',
        10: 'Kajti Gospod je na vas izlil duha globokega spanja in zaprl vaše oči. Preroke in vaše vladarje, vidce je pokril.',
        11: 'Videnje vsega vam je postalo kakor besede knjige, ki je zapečatena, ki jo ljudje izročijo nekomu, ki je učen, rekoč: ›Beri to, prosim te.‹ Ta pa pravi: ›Ne morem, kajti zapečatena je.‹',
        12: 'In knjiga je izročena tistemu, ki ni učen, rekoč: ›Beri to, prosim te.‹ In ta pravi: ›Nisem učen.‹',
        13: 'Zato je Gospod rekel: »Ker se mi to ljudstvo približuje s svojimi usti in me časti s svojimi ustnicami, toda svoje srce so odstranili daleč proč od mene in je njihov strah proti meni naučen s človeškimi predpisi,',
        14: 'zato, glej, nadaljeval bom, da storim čudovito delo med tem ljudstvom, celó čudovito delo in čudo, kajti modrost njihovih modrih mož bo izginila in razumevanje njihovih preudarnih mož bo skrito.',
        15: 'Gorje tistim, ki globoko iščejo, da skrijejo svoj naklep pred Gospodom in so njihova dela v temi in govorijo: »Kdo nas vidi? In kdo nas pozna?«',
        16: 'Zagotovo bo vaše sprevračanje stvari na glavo veljalo kakor lončarjevo ilo. Mar bo delo reklo o tistem, ki ga je naredil: »Ta me ni naredil?« Mar bo oblikovana stvar rekla o tistem, ki jo je oblikoval: »Ta nima razumevanja?«',
        17: 'Mar ni le še malo in Libanon bo spremenjen v rodovitno polje in rodovitno polje bo veljalo kakor gozd?',
        18: 'Na ta dan bodo gluhi slišali besede iz knjige in oči slepega bodo videle iz nejasnosti in iz teme.',
        19: 'Tudi krotki bodo povečali svojo radost v Gospodu in revni med možmi se bodo razveseljevali v Svetem Izraelovem.',
        20: 'Kajti strahovitež je priveden v nič in posmehljivec je použit in vsi tisti, ki so pozorni na krivičnost, so iztrebljeni;',
        21: 'ki človeka delajo za prestopnika zaradi besede in polagajo zanko za tistega, ki graja pri velikih vratih in pravičnega odvračajo zaradi ničnosti.',
        22: 'Zato tako govori Gospod, ki je odkupil Abrahama, glede Jakobove hiše: »Jakob sedaj ne bo osramočen niti njegov obraz sedaj ne bo obledel.',
        23: 'Temveč ko vidi svoje otroke, delo mojih rok v svoji sredi, bodo posvetili moje ime in posvetili Svetega Jakobovega in se bodo bali Izraelovega Boga.',
        24: 'Tudi tisti, ki so se motili v duhu, bodo prišli k razumevanju in tisti, ki so godrnjali, se bodo naučili nauka.',
    },
    30: {
        1: '»Gorje upornim otrokom,« govori Gospod, »ki jemljejo nasvet, toda ne od mene in ki se pokrivajo s pokrivalom, toda ne od mojega duha, da lahko grehu dodajo greh,',
        2: 'ki hodijo, da bi šli dol v Egipt, pa niso vprašali pri mojih ustih, da se ojačajo v faraonovi moči in da zaupajo v egiptovsko senco!',
        3: 'Zato bo faraonova moč vaša sramota in zaupanje v egiptovsko senco vaša zmeda.',
        4: 'Kajti njegovi princi so bili pri Coanu in njegovi predstavniki so prišli do Hanésa.',
        5: 'Vsi so bili osramočeni od ljudstva, ki jim ni moglo koristiti niti jim biti v pomoč niti dobiček, temveč sramota in tudi graja.',
        6: '§ Breme živali juga. V deželo stiske in tesnobe, od koder je prišel mlad in star lev, gad in strupena leteča kača, bodo svoja bogastva odnesli na ramenih mladih oslov in svoje zaklade na kameljih grbah k ljudstvu, ki jim ne bo koristilo.',
        7: 'Kajti Egipčani bodo pomagali v prazno in zaman, zato sem glede tega klical: ›Njihova moč mora prenehati.‹',
        8: 'Torej pojdite, zapišite to pred njimi na tablo in zabeležite v knjigo, da bo lahko za čas, ki pride na veke vekov,',
        9: 'da je to uporno ljudstvo, lažnivi otroci, otroci, ki nočejo poslušati Gospodove postave,',
        10: 'ki vidcem pravijo: ›Ne vidite‹ in prerokom: ›Ne prerokujte nam pravilnih stvari, govorite nam laskave stvari, prerokujte prevare.',
        11: 'Spravite se iz poti, odvrnite se iz steze, Svetemu Izraelovemu naredite, da odide izpred nas.‹«',
        12: 'Zatorej tako govori Sveti Izraelov: »Ker prezirate to besedo in zaupate v zatiranje in perverznost in ostajate na njej,',
        13: 'zato vam bo ta krivičnost kakor vrzel, pripravljena, da pade, naraščajoča iz visokega obzidja, katerega zlom pride nenadoma, v trenutku.',
        14: 'Zlomil ga bo kakor lomljenje lončarjeve posode, ki je zdrobljena na koščke. Ne bo prizanesel, tako da tam, v lomljenju le-tega, ne bo najti črepinje, da bi vzel ogenj iz ognjišča ali da bi s tem zajel vodo iz vrča.',
        15: 'Kajti tako govori Gospod Bog, Sveti Izraelov: »›V vračanju in počivanju boste rešeni; v spokojnosti in zaupanju bo vaša moč,‹ pa niste hoteli.',
        16: 'Temveč ste rekli: ›Ne, kajti bežali bomo na konjih;‹ zatorej boste bežali. ›Jahali bomo na naglih;‹ zato bodo tisti, ki vas preganjajo, nagli.',
        17: 'Tisoč jih bo bežalo ob graji enega; ob graji petih boste bežali, dokler ne boste ostali kakor drog na vrhu gore in kakor zastava na hribu.«',
        18: 'Zato bo Gospod čakal, da vam bo lahko milostljiv in zato bo povzdignjen, da bo lahko imel usmiljenje do vas, kajti Gospod je Bog sodbe. Blagoslovljeni so vsi tisti, ki čakajo nanj.',
        19: 'Kajti ljudstvo bo prebivalo na Sionu, pri Jeruzalemu. Ne boš več jokal. Zelo ti bo milostljiv ob glasu tvojega klica; ko ga bo zaslišal, ti bo odgovoril.',
        20: 'Čeprav ti Gospod daje kruh nadloge in vodo stiske, vendar tvoji učitelji ne bodo več odstranjeni v kot, temveč bodo tvoje oči videle tvoje učitelje',
        21: 'in tvoja ušesa bodo slišala za teboj besedo, rekoč: »To je pot, po njej hodite,« ko se obrnete k desnici in ko se obrnete k levici.',
        22: 'Omadeževali boste tudi pokrivalo svojih rezanih podob iz srebra in ornament svojih ulitih podob iz zlata. Vrgel jih boš proč kakor menstrualno krpo; temu boš rekel: »Pojdi ven.«',
        23: 'Potem bo dal dež tvojemu semenu, da boš z njim posejal tla in kruh od donosa zemlje in to bo debelo in obilno. Na ta dan se bo tvoja živina pasla na velikih pašnikih.',
        24: 'Prav tako bodo voli in mladi osli, ki obdelujejo zemljišče, jedli čisto krmo, ki je bila prevejana z lopato in z vejálnikom.',
        25: 'Tam bodo na vsaki visoki gori in na vsakem visokem hribu reke in potoki vodá, na dan velikega pokola, ko bodo padli stolpi.',
        26: 'Poleg tega bo svetloba lune kakor svetloba sonca in svetloba sonca bo sedemkratna, kakor svetloba sedmih dni, na dan, ko Gospod obveže vrzel svojega ljudstva in ozdravi udarec njihove rane.',
        27: 'Glej, ime Gospoda prihaja od daleč, goreč z njegovo jezo in njegovo breme je težko. Njegove ustnice so polne ogorčenja in njegov jezik kakor požirajoč ogenj.',
        28: 'Njegov dih bo kakor preplavljajoč vodotok segel do sredine vratu, da narode preseje s sitom ničnosti in tam bo brzda v čeljustih ljudstva, ki jim bo povzročala, da se opotekajo.',
        29: 'Imeli boste pesem, kakor v noči, ko se praznuje sveta slovesnost; in veselje srca, kakor ko gre nekdo s piščaljo, da pride na Gospodovo goro, k Mogočnemu Izraelovemu.',
        30: 'Gospod bo svojemu veličastnemu glasu povzročil, da bo slišan in pokazal bo spuščanje svojega lakta, z ogorčenjem svoje jeze in s plamenom požirajočega ognja, z razprševanjem, neurjem in zrni toče.',
        31: 'Kajti preko Gospodovega glasu bo Asirec, ki je udaril s palico, potolčen.',
        32: 'Na vsakem kraju, kjer bo prešla osnovana palica, ki jo bo Gospod položil nanj, bo to z bobniči in harfami, in v bitkah vihtenja se bo boril z njo.',
        33: 'Kajti Tofet je odrejen od davnine; da, za kralja je pripravljen; naredil ga je globokega in velikega. Njegova grmada je ogenj in veliko lesa. Gospodov dih ga vname kakor tok žvepla.',
    },
    31: {
        1: 'Gorje tistim, ki gredo dol v Egipt po pomoč in se zanašajo na konje in zaupajo v bojne vozove, zato ker so številni in na konjenike, ker so zelo močni, toda ne gledajo k Svetemu Izraelovemu niti ne iščejo Gospoda!',
        2: 'Vendar je on tudi moder in privedel bo zlo in svojih besed ne bo poklical nazaj, temveč se bo vzdignil zoper hišo hudodelcev in zoper pomoč tistih, ki počno krivičnost.',
        3: 'Torej Egipčani so ljudje in ne Bog in njihovi konji meso in ne duh. Ko bo Gospod iztegnil svojo roko, bosta padla oba, tako tisti, ki pomaga in komur je pomagano, padla bosta in vsem skupaj bo spodletelo.',
        4: 'Kajti tako mi je govoril Gospod: »Podobno kakor lev in mlad lev rjoveta na svoj plen, ko je zoper njega sklicana množica pastirjev, se on ne bo bal njihovega glasu niti se Gospod nad bojevniki ne bo ponižal zaradi njihovega hrupa. Tako bo Gospod nad bojevniki prišel dol, da se bori za goro Sion in za njen hrib.',
        5: 'Kakor leteče ptice, tako bo Gospod nad bojevniki branil [prestolnico] Jeruzalem; z obrambo jo bo tudi osvobodil in s prehajanjem čeznjo jo bo ohranil.',
        6: 'Obrnite se k njemu, od katerega so se Izraelovi otroci globoko spuntali.',
        7: 'Kajti na ta dan bo vsak človek zavrgel svoje malike iz srebra in svoje malike iz zlata, ki so vam jih v greh naredile vaše lastne roke.',
        8: 'Takrat bo Asirec padel pod mečem, ne od mogočnega človeka; in meč, ne od zlobnega človeka, ga bo požiral. Toda pobegnil bo pred mečem in njegovi mladeniči bodo poraženi.',
        9: 'Zaradi strahu bo prešel k svojemu oporišču in njegovi princi se bodo bali zastave,« govori Gospod, čigar ogenj je na Sionu in njegova talilna peč v Jeruzalemu.',
    },
    32: {
        1: 'Glej, kralj bo kraljeval v pravičnosti in princi bodo vladali na sodbi.',
        2: 'Človek bo kakor skrivališče pred vetrom in zatočišče pred neurjem, kakor reke vodá na suhem kraju, kakor senca velike skale na izmučeni zemlji.',
        3: 'Oči tistih, ki vidijo, ne bodo zatemnjene in ušesa tistih, ki slišijo, bodo prisluhnila.',
        4: 'Tudi srce prenagljenega bo razumelo spoznanje in jezik jecljavih bo pripravljen razločno govoriti.',
        5: 'Podla oseba se ne bo več imenovala velikodušna niti [za] skopuha ne bo rečeno, da je radodaren.',
        6: 'Kajti podla oseba bo govorila podlost in srce le-te hoče početi krivičnost, da izvaja hinavščino in da izreka napačno zoper Gospoda, da izprazni dušo lačnega in pijači žejnega povzroči, da odpove.',
        7: 'Tudi orodja skopušnega so zla. On snuje zlobne naklepe, da ubogega uniči z lažnivimi besedami, celo ko pomoči potreben pravilno govori.',
        8: 'Toda velikodušen snuje velikodušne stvari in z velikodušnimi stvarmi bo obstal.',
        9: 'Vstanite, ve ženske, ki ste ošabne, prisluhnite mojemu glasu. Ve brezskrbne hčere, pazljivo prisluhnite mojemu govoru.',
        10: 'Mnogo dni in let boste zaskrbljene, ve brezskrbne ženske, kajti trgatev se bo izjalovila, obiranje ne bo prišlo.',
        11: 'Trepetajte, ve ženske, ki ste ošabne; bodite zaskrbljene, ve brezskrbne. Slecite se in se razgalite in opašite si vrečevino na svoja ledja.',
        12: '§ Žalovale bodo zaradi seskov, zaradi prijetnih polj, zaradi rodovitne trte.',
        13: 'Nad deželo mojega ljudstva bo prišlo trnje in osat, da, nad vse hiše radosti v radostnem mestu,',
        14: 'ker bodo palače zapuščene, množica mesta bo opuščena, utrdbe in stolpi bodo za brloge na veke, radost divjih oslov, pašnik tropov,',
        15: 'dokler nad nas ne bo izlit duh iz višave in bo divjina rodovitno polje in rodovitno polje bo šteto za gozd.',
        16: 'Potem bo sodba prebivala v divjini in pravičnost ostane na rodovitnem polju.',
        17: 'Delo pravičnosti bo mir in učinek pravičnosti spokojnost in gotovost na veke.',
        18: 'Moje ljudstvo bo prebivalo v mirnem okolju in v zanesljivih prebivališčih in v tihih počivališčih,',
        19: 'ko se bo usula toča, prihajajoča na gozd in bo mesto nizko, na nizkem kraju.',
        20: 'Blagoslovljeni ste vi, ki sejete poleg vseh vodá, ki tja pošiljate kopita vola in osla.',
    },
    33: {
        1: 'Gorje tebi, ki pleniš, pa nisi bil oplenjen in postopaš zahrbtno, oni pa niso zahrbtno postopali s teboj! Ko boš prenehal pleniti, potem boš oplenjen in ko boš naredil konec zahrbtnemu postopanju, potem bodo zahrbtno postopali s teboj.',
        2: 'Oh Gospod, bodi nam milostljiv, pričakovali smo te. Vsako jutro bodi njihov laket, tudi naša rešitev duše v času stiske.',
        3: 'Ob hrupu upora je ljudstvo pobegnilo, ob tvojem vzdigovanju so bili narodi razkropljeni.',
        4: 'Vaš plen bo zbran kakor zbiranje gosenice, kakor tekanje leteče kobilice sem ter tja bo on tekel nad njimi.',
        5: 'Gospod je povišan, kajti prebiva na višavi. Sion je napolnil s sodbo in pravičnostjo.',
        6: 'Modrost in spoznanje bosta stabilnost tvojih časov in moč rešitve duše. Gospodov strah je njegov zaklad.',
        7: 'Glej, njihovi hrabri bodo zunaj vreščali. Predstavniki miru bodo grenko jokali.',
        8: 'Glavne ceste ležijo zapuščene, popotnik peša. Prelomil je zavezo, preziral mesta, ne ozira se na nobenega človeka.',
        9: 'Zemlja žaluje in peša. Libanon je osramočen in posekan. Šarón je podoben divjini in Bašán ter Karmel otresata svoje sadove.',
        10: '»Sedaj bom vstal,« govori Gospod, »sedaj bom povišan, sedaj se bom dvignil.',
        11: 'Spočeli boste pleve, rodili boste strnišče. Vaš dih vas bo pogoltnil kakor ogenj.',
        12: 'Ljudstvo bo kakor gorenje žganega apna, kakor posekano trnje bodo sežgani v ognju.',
        13: 'Prisluhnite vi, ki ste daleč proč, kaj sem storil in vi, ki ste blizu, priznajte mojo moč.',
        14: 'Grešniki na Sionu so prestrašeni, grozljivost je presenetila hinavce. Kdo izmed nas bo bival s požirajočim ognjem? Kdo izmed nas bo bival z večnimi gorenji?',
        15: 'Kdor hodi pravično in govori iskreno, kdor prezira dobiček zatiranj, ki otresa svoji roki pred tem, da bi držal podkupnine, ki si ušesa zatiska pred poslušanjem o krvi in zatiska svoje oči pred gledanjem zla;',
        16: 'ta bo prebival na višavi. Njegov prostor obrambe bodo skalna oporišča. Dan mu bo kruh, njegove vode bodo zanesljive.',
        17: 'Tvoje oči bodo videle kralja v njegovi lepoti. Gledale bodo deželo, ki je zelo daleč proč.',
        18: 'Tvoje srce bo premišljevalo strahoto. Kje je pisar? Kje je prejemnik? Kje je tisti, ki je štel stolpe?',
        19: 'Ne boš videl krutega ljudstva, ljudstva globljega govora, kakor ga lahko zaznaš, jecljajočega jezika, ki ga ne moreš razumeti.',
        20: 'Poglej na Sion, mesto naših slovesnosti. Tvoje oči bodo videle Jeruzalem, tiho prebivališče, šotor, ki ne bo porušen; niti eden izmed njegovih klinov ne bo nikoli odstranjen niti nobena izmed njegovih vrvi pretrgana.',
        21: 'Toda tam nam bo veličasten Gospod kraj širokih rek in vodotokov, kamor ne bo plula galeja z vesli niti čedna ladja ne bo plula mimo.',
        22: 'Kajti Gospod je naš sodnik, Gospod je naš zakonodajalec, Gospod je naš kralj, on nas bo rešil.',
        23: 'Tvoja ladijska oprema je odvezana; ne morejo dobro ojačati jambora, ne morejo razpeti jadra. Potem je plen velikega ukradenega blaga razdeljen; hromi pobira plen.',
        24: 'Prebivalec ne bo rekel: »Bolan sem.« Ljudstvu, ki tam prebiva, bo odpuščena njihova krivičnost.',
    },
    34: {
        1: 'Pridite bliže, vi narodi, da slišite in prisluhnite ve ljudstva. Naj zemlja sliši in vsi, ki so na njej, zemeljski [krog] in vse stvari, ki pridejo iz njega.',
        2: 'Kajti ogorčenje od Gospoda je nad vsemi narodi in njegova razjarjenost nad vsemi njihovimi vojskami. Popolnoma jih je uničil, izročil jih je v klanje.',
        3: 'Tudi njihovi umorjeni bodo vrženi ven in njihov smrad bo prišel iz njihovih trupel in gore bodo stopljene z njihovo krvjo.',
        4: 'Vse vojske neba bodo razpadle in nebo bo zvito skupaj kakor zvitek pergamenta. Vse njihove vojske bodo padle, kakor list pade s trte in kakor figa pade iz figovega drevesa.',
        5: 'Kajti moj meč bo potešen na nebu. Glejte, ta bo prišel dol nad Edóm in nad ljudstvo mojega prekletstva, k sodbi.',
        6: 'Gospodov meč je poln krvi, zamaščen s tolščo in s krvjo jagnjet in koz, s tolščo ledvic ovnov, kajti Gospod ima klavno daritev v Bocri in velik pokol v edómski deželi.',
        7: 'Samorogi bodo z njimi prišli dol in bikci z biki in njihova dežela bo namočena s krvjo in njihov prah zamaščen z mastnostjo.',
        8: 'Kajti to je dan Gospodovega maščevanja in leto povračil zaradi Sionove pravde.',
        9: 'Njegovi vodotoki bodo spremenjeni v smolo, njegov prah v žveplo in njegova dežela bo postala goreča smola.',
        10: 'Ta ne bo pogašena ne ponoči ne podnevi; njen dim se bo dvigoval na veke. Od roda do roda bo ležala opustošena; nihče ne bo šel skoznjo na veke vekov.',
        11: 'Toda kormoran in bobnarica jo bosta vzela v last; tudi sova in krokar bosta v njej prebivala. Nadnjo bo razširil vrvico zmede in kamne praznine.',
        12: 'Njene plemenite bodo poklicali h kraljestvu, toda tam ne bo nikogar in vsi njeni princi bodo nič.',
        13: 'Trnje bo pognalo v njenih palačah, koprive in trnovo grmovje v njenih trdnjavah, in ta bo prebivališče zmajem in dvor za sove.',
        14: 'Divje živali iz puščave se bodo prav tako srečale z divjimi živalmi z otoka in kozjenog bo klical svojemu tovarišu; tudi skovir bo tam počival in zase našel mesto počitka.',
        15: 'Tam si bo velika sova naredila svoje gnezdo, polegla, izvalila in [jih] zbrala pod svojo senco. Tam bodo zbrani tudi jastrebi, vsak s svojo družico.',
        16: 'Poiščite si iz Gospodove knjige in berite. Nobeden izmed teh ne bo manjkal, nobeden ne bo pogrešal svoje družice, kajti moja usta so to zapovedala in njegov duh jih je zbral.',
        17: 'Zanje je vrgel žreb in njegova roka jim je to razdelila po vrvici. Vzeli jo bodo v last na veke, od roda do roda bodo prebivali v njej.',
    },
    35: {
        1: 'Divjina in samoten kraj bosta vesela zaradi njih in puščava se bo razveseljevala in cvetela kakor vrtnica.',
        2: 'Ta bo obilno cvetela in se razveseljevala, celo z radostjo in petjem. Dana ji bo slava Libanona, odličnost Karmela in Šaróna. Gledali bodo Gospodovo slavo in odličnost našega Boga.',
        3: 'Ojačajte šibke roke in okrepite slabotna kolena.',
        4: 'Recite tistim, ki so boječega srca: »Bodite močni, ne bojte se. Glejte, vaš Bog bo prišel z maščevanjem, celó Bog s povračilom; prišel bo in vas rešil.',
        5: 'Potem bodo oči slepega odprte in ušesa gluhega bodo odmašena.',
        6: 'Potem bo hromi človek poskakoval kakor jelen in jezik nemega bo pel, kajti v divjini bodo izbruhnile vode in vodotoki v puščavi.',
        7: 'Izsušena tla bodo postala ribnik in žejna dežela izviri vodá. V prebivališču zmajev, kjer vsak leži, bo trava s trstjem in ločjem.',
        8: 'Tam bo glavna cesta in pot in ta bo imenovana ›Pot svetosti;‹ nečisti ne bo šel preko nje, temveč bo ta zanje same. Popotniki, čeprav bedaki, ne bodo zgrešili na njej.',
        9: 'Tam ne bo nobenega leva niti katerakoli sestradana zver ne bo šla nanjo, tam je ne bo najti; temveč bodo tam hodili odkupljeni.',
        10: 'Vrnili se bodo Gospodovi odkupljenci in prišli k Sionu s pesmimi in večno radostjo na svojih glavah. Dosegli bodo radost in veselje, bridkost in vzdihovanje pa bosta zbežala proč.',
    },
    36: {
        1: 'Pripetilo se je torej v štirinajstem letu kralja Ezekíja, da je asirski kralj Senaherib prišel gor zoper vsa obrambna Judova mesta in jih zavzel.',
        2: 'Asirski kralj je poslal Rabšakéja iz Lahíša v Jeruzalem h kralju Ezekíju z veliko vojsko. In ta se je ustavil pri kanalu gornjega ribnika, na glavni cesti pralčevega polja.',
        3: 'Potem so prišli k njemu Hilkijájev sin Eljakím, ki je bil nad hišo, pisar Šebná in Asáfov sin Joáh, letopisec.',
        4: 'Rabšaké jim je rekel: »Povejte torej Ezekíju: ›Tako govori veliki kralj, kralj Asirije: ›Kakšno zaupanje je to, v katero zaupaš?‹',
        5: 'Jaz pravim, ti govoriš (toda to so samo prazne besede) imam nasvet in moč za vojno. Torej komu zaupaš, da si se uprl zoper mene?',
        6: 'Glej, zanašaš se na palico tega zlomljenega trsta, na Egipt, na katerega, če se človek naslanja, se bo zadrl v njegovo roko in jo prebodel. Tako je faraon, egiptovski kralj, vsem, ki zaupajo vanj.',
        7: 'Toda če mi rečeš: ›Mi zaupamo v Gospoda, svojega Boga.‹ Mar ni to tisti, katerega visoke kraje in katerega oltarje je Ezekíja odvzel ter Judu in Jeruzalemu rekel: ›Oboževali boste pred tem oltarjem?‹',
        8: 'Zdaj torej daj jamstva, prosim te, mojemu gospodarju, asirskemu kralju, jaz pa ti bom dal dva tisoč konjev, če boš na svoji strani nanje zmožen postaviti jezdece.',
        9: 'Kako boš potem odvrnil obličje enega poveljnika, izmed najmanjših služabnikov mojega gospodarja in svoje upanje položil v Egipt zaradi bojnih vozov in konjenikov?',
        10: 'Sem mar sedaj brez Gospoda prišel gor zoper to deželo, da jo uničim? Gospod mi je rekel: ›Pojdi gor zoper to deželo in jo uniči.‹«',
        11: 'Nato so Eljakím, Šebná in Joáh rekli Rabšakéju: »Govori, prosimo te, svojim služabnikom v sirskem jeziku, kajti razumemo ga in ne govori nam v judovskem jeziku v ušesa ljudstva, ki je na obzidju.«',
        12: 'Toda Rabšaké je rekel: »Me je mar moj gospodar poslal k tvojemu gospodarju in k tebi, da ti govorim te besede? Mar me ni poslal k možem, ki sedijo na obzidju, da bodo lahko jedli svoj lastni iztrebek in z vami pili svoj lastni seč?«',
        13: 'Potem se je Rabšaké ustopil in z močnim glasom zaklical v judovskem jeziku in rekel: »Poslušajte besede velikega kralja, asirskega kralja.',
        14: 'Tako govori kralj: ›Ne dopustite, da vas Ezekíja zavede, kajti ne bo vas mogel osvoboditi.',
        15: 'Niti naj vas Ezekíja ne primora zaupati v Gospoda, rekoč: › Gospod nas bo zagotovo osvobodil, to mesto ne bo izročeno v roko asirskega kralja.‹',
        16: 'Ne prisluhnite Ezekíju, kajti tako govori kralj Asirije: › Z darilom sklenite dogovor z menoj in pridite ven k meni in jejte vsak od svoje trte in vsak od svojega figovega drevesa in pijte vode, vsak iz svojega lastnega vodnega zbiralnika,',
        17: 'dokler ne pridem in vas ne vzamem proč v deželo, podobno vaši lastni deželi, deželo žita in vina, deželo kruha in vinogradov.',
        18: 'Pazite, da vas Ezekíja ne prepriča, rekoč: › Gospod nas bo osvobodil.‹ Mar je katerikoli izmed bogov narodov svojo deželo osvobodil iz roke asirskega kralja?',
        19: 'Kje so bogovi Hamáta in Arpáda? Kje so bogovi Sefarvájima? Mar so le-ti Samarijo osvobodili iz moje roke?',
        20: 'Kdo so tisti izmed vseh bogov teh dežel, ki so svojo deželo osvobodili iz moje roke, da bi Gospod Jeruzalem osvobodil iz moje roke?«',
        21: 'Toda molčali so in mu niso odgovorili niti besede, kajti kraljeva zapoved je bila, rekoč: »Ne odgovarjajte mu.«',
        22: 'Potem so prišli Hilkijájev sin Eljakím, ki je bil nad družino, pisar Šebná in Asáfov sin Joáh, letopisec, k Ezekíju s svojimi pretrganimi oblačili in mu povedali Rabšakéjeve besede.',
    },
    37: {
        1: 'Pripetilo se je, ko je kralj Ezekíja to slišal, da je pretrgal svoja oblačila, se pokril z vrečevino in odšel v Gospodovo hišo.',
        2: 'Poslal je Eljakíma, ki je bil nad družino, pisarja Šebná in starešine duhovnikov, pokrite z vrečevino, k preroku Izaiju, Amócovemu sinu.',
        3: 'Rekli so mu: »Tako govori Ezekíja: ›Ta dan je dan stiske, graje in bogokletja, kajti otroci so prišli do rojstva in tam ni moči za porod.',
        4: 'Morda bo Gospod, tvoj Bog, slišal besede Rabšakéja, ki ga je poslal asirski kralj, njegov gospodar, da kara živega Boga in bo pograjal besede, ki jih je slišal Gospod, tvoj Bog. Zatorej dvigni svojo molitev za ostanek, ki je ostal.«',
        5: 'Tako so služabniki kralja Ezekíja prišli k Izaiju.',
        6: 'Izaija jim je rekel: »Tako boste rekli svojemu gospodarju: ›Tako govori Gospod: ›Ne boj se besed, ki si jih slišal, s katerimi so služabniki asirskega kralja proti meni izrekali bogokletje.',
        7: 'Glej, nanj bom poslal sunek [duha] in slišal bo govorico in se vrnil v svojo lastno deželo in povzročil mu bom, da v svoji lastni deželi pade pod mečem.‹«',
        8: 'Tako se je Rabšaké vrnil in našel asirskega kralja, vojskujočega se zoper Libno, kajti slišal je, da je odpotoval iz Lahíša.',
        9: 'Slišal je reči glede Tirháka, kralja Etiopije: »Prišel je naprej, da se vojskuje s teboj.« In ko je ta to slišal, je poslal poslance k Ezekíju, rekoč:',
        10: '»Tako govorite Judovemu kralju Ezekíju, rekoč: ›Ne dopusti, da te tvoj Bog, v katerega zaupaš, zavede, rekoč: ›Jeruzalem ne bo izročen v roko asirskega kralja.‹',
        11: 'Glej, slišal si, kaj so asirski kralji storili vsem deželam z njihovim popolnim uničenjem, pa boš ti osvobojen?',
        12: 'Mar so bogovi narodov osvobodili tiste, ki so jih moji očetje uničili, kakor Gozána, Harána, Recefa in otroke Edena, ki so bili v Telasárju?',
        13: 'Kje je kralj Hamáta, kralj Arpáda in kralj mesta Sefarvájima, Hene in Avája?‹«',
        14: 'Ezekíja je prejel pismo iz roke poslancev ter ga prebral in Ezekíja je odšel gor v Gospodovo hišo in ga razprostrl pred Gospodom.',
        15: 'In Ezekíja je molil h Gospodu, rekoč:',
        16: '»Oh Gospod nad bojevniki, Izraelov Bog, ki prebivaš med kerubi, ti si Bog, celó ti sam, izmed vseh kraljestev zemlje. Ti si naredil nebo in zemljo.',
        17: 'Nagni svoje uho, oh Gospod in prisluhni; odpri svoje oči, oh Gospod in glej in poslušaj vse besede Senaheriba, ki jih je poslal, da graja živega Boga.',
        18: 'Resnično, Gospod, asirski kralji so opustošili vse narode in njihove dežele',
        19: 'in njihove bogove vrgli v ogenj, kajti to niso bili bogovi, temveč delo človeških rok, les in kamen, zato so jih uničili.',
        20: 'Zdaj torej, oh Gospod, naš Bog, reši nas pred njegovo roko, da bodo vsa kraljestva zemlje lahko vedela, da si ti Gospod, celó samo ti.«',
        21: 'Potem je Izaija, Amócov sin, poslal k Ezekíju, rekoč: »Tako govori Gospod, Izraelov Bog: ›Kakor si molil k meni zoper asirskega kralja Senaheriba;',
        22: 'to je beseda, ki jo je Gospod spregovoril glede njega: ›Devica, sionska hči, te je prezirala in se ti smejala do zaničevanja, jeruzalemska hči je nad teboj zmajevala z glavo.',
        23: 'Koga si grajal in proti komu si izrekal bogokletje? Zoper koga si povišal svoj glas in svoje oči povzdignil na višavo? Celó zoper Svetega Izraelovega.',
        24: 'S svojimi služabniki si grajal Gospoda in rekel: ›Z množico svojih bojnih vozov sem prišel gor do višin gora, k pobočjem Libanona in posekal bom njegove visoke cedre in izbrane ciprese in vstopil bom v višino njegove meje in gozd njegovega Karmela.',
        25: 'Kopál sem in pil vodo in s podplatom svojega stopala sem posušil vse reke obleganih krajev.',
        26: 'Mar nisi že dolgo nazaj slišal, kako sem to storil in od starodavnih časov, da sem to oblikoval? Sedaj sem privedel, da se je to zgodilo, da bi moral položiti opustela obrambna mesta v kupe ruševin.',
        27: 'Zato so bili njihovi prebivalci majhne moči, bili so zaprepadeni in zbegani. Bili so kakor trava polja in kakor zeleno zelišče, kakor trava na hišnih strehah in kakor ožgano žito, preden zraste.',
        28: 'Toda jaz poznam tvoje prebivališče, tvoje odhajanje, tvoje prihajanje in tvoj bes zoper mene.',
        29: 'Ker je tvoj bes zoper mene in je tvoj hrup prišel gor v moja ušesa, zato bom zataknil svoj kavelj v tvoj nos in svojo brzdo med tvoje ustnice in te obrnil nazaj po poti, po kateri si prišel.',
        30: 'To ti bo znamenje: › To leto boste jedli kar zraste samo od sebe in drugo leto to, kar požene od istega, v tretjem letu pa sejte, žanjite, sadite vinograde in jejte od njihovega sadu.',
        31: 'Preostanek od Judove hiše, ki je pobegnil, se bo ponovno ukoreninil navzdol in navzgor obrodil sad.',
        32: 'Kajti iz Jeruzalema bo izšel preostanek in tisti, ki pobegnejo z gore Sion. Gorečnost Gospoda nad bojevniki bo to storila.‹',
        33: 'Zato tako govori Gospod glede asirskega kralja: ›Ta ne bo prišel v to mesto, niti tja ne bo izstrelil puščice, niti predenj ne bo prišel s ščiti, niti zoper njega ne bo nasul okopa.',
        34: 'Po poti, po kateri je prišel, po isti se bo vrnil in ne bo prišel v to mesto,‹ govori Gospod.',
        35: '›Kajti jaz bom branil to mesto, da ga rešim zaradi sebe in zaradi svojega služabnika Davida.‹«',
        36: 'Potem je odšel naprej Gospodov angel in jih v taboru Asircev udaril sto petinosemdeset tisoč. Ko so zgodaj zjutraj vstali, glej, oni vsi so bili mrtva trupla.',
        37: 'Tako je asirski kralj Senaherib odpotoval, odšel, se vrnil in prebival v Ninivah.',
        38: 'Pripetilo se je, ko je oboževal v hiši svojega boga Nisróha, da sta ga njegova sinova Adraméleh in Sarécer udarila z mečem in pobegnila v deželo Armenijo in namesto njega je zakraljeval njegov sin Asarhadón.',
    },
    38: {
        1: 'V tistih dneh je bil Ezekíja na smrt bolan. Amócov sin, prerok Izaija, je prišel k njemu ter mu rekel: »Tako govori Gospod: ›Postavi svojo hišo v red, kajti umrl boš in ne živel.‹«',
        2: 'Potem je Ezekíja svoj obraz obrnil k steni, molil h Gospodu',
        3: 'in rekel: »Spomni se sedaj, oh Gospod, rotim te, kako sem hodil pred teboj v resnici in s popolnim srcem in delal to, kar je dobro v tvojem pogledu.« In Ezekíja je bridko zajokal.',
        4: 'Potem je prišla Gospodova beseda k Izaiju, rekoč:',
        5: '»Pojdi in povej Ezekíju: ›Tako govori Gospod, Bog tvojega očeta Davida: ›Slišal sem tvojo molitev, videl sem tvoje solze. Glej, tvojim dnevom bom dodal petnajst let.',
        6: 'Tebe in to mesto bom osvobodil iz roke asirskega kralja in jaz bom branil to mesto.',
        7: 'To ti bo znamenje od Gospoda, da bo Gospod storil to stvar, ki jo je govoril:',
        8: '›Glej, senco stopinj, ki se je na Aházovi sončni uri spustila, bom ponovno privedel deset stopinj nazaj.‹« Tako se je sonce vrnilo [za] deset stopinj, po stopinjah, po katerih se je spustilo.',
        9: 'Pisanje Judovega kralja Ezekíja, ko je bil bolan in je okreval od svoje bolezni:',
        10: '»Rekel sem o preostanku svojih dni: ›Šel bom do velikih vrat groba. Prikrajšan sem preostanka svojih let.‹',
        11: 'Rekel sem: ›Ne bom videl Gospoda, celó Gospoda, v deželi živih. Ne bom več gledal človeka s prebivalci sveta.',
        12: '§ Moja starost je odšla in od mene je odstranjena kakor pastirski šotor. Kakor tkalec sem odrezal svoje življenje. Odrezal me bo z mučno boleznijo. Od dneva, celo do noči boš naredil moj konec.',
        13: 'Štel sem do jutra, da bo, tako kakor lev, zlomil vse moje kosti. Od dneva, celó do noči boš iz mene naredil konec.',
        14: 'Kakor žerjav ali lastovka, tako sem žvrgolel. Žaloval sem kakor golobica. Moje oči pešajo z gledanjem navzgor. Oh Gospod, zatiran sem, zavzemi se zame.',
        15: 'Kaj naj rečem? On mi je tako govoril in sam je to storil. Vsa svoja leta bom mirno hodil v grenkobi svoje duše.',
        16: 'Oh Gospod, po teh stvareh ljudje živijo in v vseh teh stvareh je življenje mojega duha. Tako me boš obnovil in me pripravil, da živim.',
        17: 'Glej, za mir sem imel veliko grenkobo, toda ti si v ljubezni do moje duše le-to osvobodil iz jame izprijenosti, kajti vse moje grehe si vrgel za svoj hrbet.',
        18: 'Kajti grob te ne more hvaliti, smrt te ne more proslavljati. Tisti, ki gredo dol v jamo, ne morejo upati na tvojo resnico.',
        19: 'Živeči, živeči, ta te bo hvalil, kakor danes počnem jaz. Oče bo otrokom dal spoznati tvojo resnico.',
        20: 'Gospod je bil pripravljen, da me reši. Zato bomo peli moje pesmi, na glasbila na strune, vse dni našega življenja v hiši Gospodovi.‹«',
        21: 'Kajti Izaija je rekel: »Naj vzamejo kepo fig in jo položijo za pomirjevalo na vnetje in okreval bo.«',
        22: 'Ezekíja je tudi rekel: »Kaj je znamenje, da bom šel gor, h Gospodovi hiši?«',
    },
    39: {
        1: 'Ob tistem času je babilonski kralj Merodáh Baladán poslal Ezekíju pisma in darilo, kajti slišal je, da je bil bolan in je okreval.',
        2: 'Ezekíja jih je bil vesel in jim razkazal hišo svojih dragocenih stvari: srebro, zlato, dišave, dragoceno mazilo in vso hišo svoje orožarne in vsega, kar se je našlo v njegovih zakladnicah. Ničesar ni bilo v njegovi hiši niti v vsem njegovem gospostvu, česar jim Ezekíja ni razkazal.',
        3: 'Potem je prerok Izaija prišel h kralju Ezekíju in mu rekel: »Kaj so rekli ti možje? In od kod so prišli k tebi?« Ezekíja je rekel: »K meni so prišli iz daljne dežele, celó iz Babilona.«',
        4: 'Potem je rekel: »Kaj so videli v tvoji hiši?« Ezekíja je odgovoril: »Videli so vse, kar je v moji hiši. Ničesar ni med mojimi zakladi, česar jim ne bi pokazal.«',
        5: 'Potem Izaija reče Ezekíju: »Poslušaj besedo Gospoda nad bojevniki:',
        6: '›Glej, prihajajo dnevi, da bo vse, kar je v tvoji hiši in to, kar so tvoji očetje prihranili v shrambi do tega dne, odneseno v Babilon. Nič ne bo ostalo,‹ govori Gospod.',
        7: '›In izmed tvojih sinov, ki bodo izšli iz tebe, ki jih boš zaplodil, jih bodo odvedli proč in bodo evnuhi v palači babilonskega kralja.‹«',
        8: 'Potem je Ezekíja rekel Izaiju: »Dobra je Gospodova beseda, ki si jo povedal.« Poleg tega je rekel: »Kajti mir in resnica bosta v mojih dneh.«',
    },
    40: {
        1: '»Tolažite, tolažite moje ljudstvo,« govori vaš Bog.',
        2: '»Govorite tolažilno [prestolnici] Jeruzalem in kličite k njej, da je njeno bojevanje dovršeno, da je njena krivičnost odpuščena, kajti iz Gospodove roke je prejela dvojno za vse svoje grehe.«',
        3: 'Glas tistega, ki vpije v divjini: »Pripravite Gospodovo pot, v puščavi izravnajte glavno cesto za našega Boga.',
        4: 'Vsaka dolina naj bo povišana in vsaka gora in hrib naj bosta znižana in skrivljeno naj bo izravnano in gorski grebeni ravnina',
        5: 'in Gospodova slava se bo razodela in vse meso jo bo hkrati videlo, kajti Gospodova usta so to govorila.«',
        6: 'Glas je rekel: »Vpij.« Rekel je: »Kaj naj vpijem?« »Vse meso je trava in vsa njegova ljubkost je kakor cvetica polja.',
        7: 'Trava se suši, cvet veni, ker nanjo piha Gospodov duh. Zagotovo je ljudstvo trava.',
        8: 'Trava se suši, cvet veni, toda beseda našega Boga bo obstala na veke.«',
        9: 'Oh Sion, ki prinašaš dobre novice, pojdi gor na visoko goro. Oh Jeruzalem, ki prinašaš dobre novice, povzdigni svoj glas z močjo. Povzdigni ga, ne boj se, govóri Judovim mestom: »Glejte, vaš Bog!«',
        10: 'Glejte, Gospod Bog bo prišel z močno roko in njegov laket bo vladal zanj. Glejte, njegova nagrada je z njim in njegovo delo pred njim.',
        11: 'Svoj trop bo pasel kakor pastir. Jagnjeta bo zbral s svojim laktom in jih nosil v svojem naročju in nežno vodil tiste, ki so z mladiči.',
        12: 'Kdo je izmeril vode z dlanjo svoje roke, s pednjem premeril nebo, doumel prah zemlje po meri in odtehtal gore na vagah in hribe na tehtnici?',
        13: 'Kdo je usmerjal Gospodovega Duha ali je bil njegov svetovalec in ga učil?',
        14: 'S kom se je posvetoval in kdo ga je poučeval in ga učil na stezi sodbe in ga učil spoznanja in mu pokazal pot razumevanja?',
        15: 'Glej, narodi so kakor kapljica iz vedra in šteti so kakor majhen prah na tehtnici. Glej, otoke dviguje kakor zelo majhno stvar.',
        16: 'Libanon ni zadosten za gorenje niti njegove živali ne zadoščajo za žgalno daritev.',
        17: 'Vsi narodi pred njim so kakor nič in zanj so vsi šteti manj kot nič in ničnost.',
        18: 'Komu hočete potem primerjati Boga? Ali kakšno podobnost hočete primerjati k njemu?',
        19: 'Delavec tali rezano podobo, zlatar jo prevleče z zlatom in uliva srebrne verižice.',
        20: 'Kdor je tako obubožan, da nima daritve, izbira drevo, ki ne bo trohnelo, zanj išče spretnega delavca, da pripravi rezano podobo, ki ne bo omajana.',
        21: 'Mar niste vedeli? Mar niste slišali? Mar vam ni bilo to povedano od začetka? Mar niste razumeli od temeljev zemlje?',
        22: 'On je, ki sedi nad zemeljskim krogom, njegovi prebivalci pa so kakor kobilice, ki razprostira nebesa kakor zaveso in jih razširja kakor šotor za prebivanje v njem,',
        23: 'ki prince daje v nič, sodnike zemlje dela kakor ničnost.',
        24: 'Da, ne bodo posajeni, da, ne bodo posejani. Da, njihova klada se ne bo zakoreninila v zemlji in nanje bo tudi pihal in se bodo izsušili in vrtinčast veter jih bo odnesel kakor slamo.',
        25: '»H komu me boste potem primerjali ali [komu] bom enak?« govori Sveti.',
        26: 'Povzdignite svoje oči na visoko in glejte, kdo je ustvaril te stvari, ki njihovo vojsko vodi ven po številu. Vse jih kliče po imenih z veličino svoje moči, ker je močan v moči; niti ena ne manjka.',
        27: 'Zakaj praviš, oh Jakob in govoriš, oh Izrael: »Moja pot je skrita pred Gospodom in moja sodba je šla mimo mojega Boga?',
        28: 'Mar nisi spoznal? Mar nisi slišal, da večen Bog, Gospod, Stvarnik koncev zemlje, ne slabi niti ni izmučen? Njegovega razumevanja ni možno preiskati.',
        29: 'Silo daje slabotnim in tistim, ki nimajo moči, povečuje moč.',
        30: 'Celo mladostniki bodo oslabeli in bodo izmučeni in mladeniči bodo popolnoma padli,',
        31: 'toda tisti, ki čakajo na Gospoda, bodo obnavljali svojo moč, vzpenjali se bodo s perutmi kakor orli, tekli bodo in ne bodo izmučeni in hodili bodo in ne oslabeli.',
    },
    41: {
        1: 'Molčite pred menoj, oh otoki in naj ljudstvo obnavlja svojo moč. Naj pridejo bliže, potem jim pustite govoriti. Pridimo blizu skupaj k sodbi.',
        2: 'Kdo je dvignil pravičnega človeka od vzhoda in ga poklical k svojemu stopalu, dal predenj narode in ga naredil, [da] vlada nad kralji? Izročil jih je kakor prah njegovemu meču in kakor slamo gnano k njegovemu loku.',
        3: 'Zasledoval jih je in varno prešel; celó po poti, [po] kateri [še] ni šel s svojimi stopali.',
        4: 'Kdo je delal in to storil, kličoč rodove od začetka? Jaz, Gospod, prvi in s poslednjimi; jaz sem ta.',
        5: 'Otoki so to videli in se bali; konci zemlje so bili prestrašeni, se približali in prišli.',
        6: 'Pomagali so vsak svojemu sosedu in vsak je svojemu bratu rekel: »Bodi odločnega poguma.«',
        7: 'Tako je tesar hrabril zlatarja in kdor gladi s kladivom, tistega, ki udarja nakovalo, rekoč: »Ta je pripravljen za spajanje« in ga pritrdil z žeblji, da ta ne bi bil premaknjen.',
        8: 'Toda ti, Izrael, si moj služabnik, Jakob, ki sem ga izbral, seme Abrahama, mojega prijatelja.',
        9: 'Ti, ki sem te vzel od koncev zemlje in te poklical od njihovih glavnih mož in ti rekel: »Ti si moj služabnik, izbral sem te in te nisem zavrgel.',
        10: 'Ne boj se, kajti jaz sem s teboj. Ne bodi potrt, kajti jaz sem tvoj Bog. Okrepil te bom, da, jaz ti bom pomagal, da, podpiral te bom z desnico svoje pravičnosti.',
        11: 'Glej, vsi tisti, ki so bili ogorčeni zoper tebe, bodo osramočeni in zbegani. Oni bodo kakor nič in tisti, ki se prepirajo s teboj, bodo propadli.',
        12: 'Iskal jih boš in jih ne boš našel, celó tiste, ki so se pričkali s teboj. Tisti, ki se vojskujejo zoper tebe, bodo kakor nič in kakor stvar ničnosti.',
        13: 'Kajti jaz, Gospod, tvoj Bog, bom držal tvojo desnico, rekoč ti: »Ne boj se, jaz ti bom pomagal.«',
        14: 'Ne boj se, ti ličinka Jakob in vi, Izraelovi možje, pomagal ti bom, govori Gospod in tvoj odkupitelj, Sveti Izraelov.',
        15: 'Glej, naredil te bom [za] novo ostro mlatilno pripravo z zobmi. Mlatil boš gore, jih razdrobil in hribe boš naredil kakor pleve.',
        16: 'Vejál jih boš in veter jih bo odnesel proč in vrtinčast veter jih bo razkropil, ti pa se boš razveseljeval v Gospodu in slavil boš v Svetem Izraelovem.',
        17: 'Kadar ubogi in pomoči potrebni iščejo vode in je tam ni in njihov jezik odpoveduje zaradi žeje, jih bom jaz, Gospod, uslišal in jaz, Izraelov Bog, jih ne bom zapustil.',
        18: 'Odprl bom reke na visokih krajih in studence v sredi dolin. Divjino bom spremenil [v] vodni ribnik in suho deželo [v] izvire voda.',
        19: 'V divjini bom zasadil cedro, akacijevo drevo, mirto in olivno drevo; v puščavi bom skupaj posadil cipreso, bor in pušpan,',
        20: 'da bodo lahko videli, spoznali, preudarili in skupaj razumeli, da je to storila Gospodova roka in Sveti Izraelov je to ustvaril.',
        21: 'Prinesite svojo pravdo,‹ govori Gospod; ›prinesite naprej svoje močne razloge, govori Kralj Jakobov.',
        22: 'Naj jih prinesejo naprej in nam pokažejo kaj se bo zgodilo. Naj nam pokažejo prejšnje stvari, kakršne so, da jih lahko preudarimo in spoznamo njihov zadnji konec; ali nam oznanite stvari, ki pridejo.',
        23: 'Pokažite stvari, ki bodo odslej, da bomo lahko vedeli, da ste vi bogovi. Da, delajte dobro ali delajte zlo, da bomo lahko zaprepadeni in to skupaj gledali.',
        24: 'Glejte, vi ste od ničnosti in vaše delo je ničevo; ogabnost je, kdor vas izbere.',
        25: 'Dvignil sem nekoga iz severa in bo prišel. Od sončnega vzhoda bo klical moje ime in prišel bo nad prince kakor nad malto in kakor lončar gnete ilo.',
        26: 'Kdo je razglasil od začetka, da bi mi lahko vedeli? In poprej, da bi lahko rekli: » On je pravičen?« Da, tam ni nikogar, ki kaže; da, tam ni nikogar, ki razglaša; da, tam ni nikogar, ki sliši vaše besede.',
        27: 'Prvi bo rekel Sionu: »Poglej, poglej jih.« In Jeruzalemu bom dal nekoga, ki prinaša dobre novice.',
        28: 'Kajti gledal sem in tam ni bilo človeka, celo med njimi in tam ni bilo svetovalca, da bi lahko, ko sem jih povprašal, odgovoril besedo.',
        29: 'Glej, vsi so ničnost, njihova dela so nič. Njihove ulite podobe so veter in zmešnjava.',
    },
    42: {
        1: 'Glej, moj služabnik, ki ga podpiram; moj izvoljeni, v katerem se moja duša razveseljuje; svojega duha sem položil nanj. Oznanil bo sodbo poganom.',
        2: 'Ne bo vpil, niti povzdignil [glasu], niti svojemu glasu ne bo povzročil, da bi bil slišan na ulici.',
        3: 'Poškodovanega trsta ne bo zlomil in kadečega stenja ne bo ugasnil. Sodbo bo privedel k resnici.',
        4: 'Ne bo opešal niti ne bo izgubil poguma, dokler ne postavi sodbe na zemlji in otoki bodo čakali na njegovo postavo.',
        5: 'Tako govori Gospod Bog, ki je ustvaril nebesa in jih razpel; ki je razprostrl zemljo in to, kar prihaja iz nje; on, ki daje dih ljudstvu na njej in duha tem, ki hodijo po njej:',
        6: '»Jaz, Gospod, sem te poklical v pravičnosti in držal bom tvojo roko in te varoval in dam te za zavezo ljudstvu, za svetlobo poganom,',
        7: 'da odpreš slepe oči, da privedeš jetnike iz ječe in te, ki sedijo v temi, ven iz jetnišnice.',
        8: 'Jaz sem Gospod. To je moje ime in svoje slave ne bom dal drugemu niti svoje hvale rezanim podobam.',
        9: 'Glej, prejšnje stvari so se zgodile in razglašam nove stvari. Preden vzbrstijo ti povem o njih.«',
        10: 'Zapojte Gospodu novo pesem in njegovo hvalo s konca zemlje, vi, ki greste dol do morja in vse, kar je v njem, otoki in njegovi prebivalci.',
        11: 'Naj divjina in njena mesta dvignejo svoj glas, vasi, ki jih naseljuje Kedár. Naj skalni prebivalci pojejo, naj zavpijejo z vrhov gora.',
        12: 'Naj dajo slavo Gospodu in razglašajo njegovo hvalo na otokih.',
        13: 'Gospod bo šel naprej kakor mogočen mož, ljubosumnost bo razvnel kakor bojevnik. Vpil bo, da, rjovel, prevladal bo zoper svoje sovražnike.',
        14: '»Dolgo časa sem zadrževal svoj mir, bil sem tiho in se zadrževal. Sedaj [pa] bom vpil kakor ženska v porodnih mukah; hkrati bom uničil in požrl.',
        15: 'Opustošil bom gore in hribe in posušil vsa njihova zelišča in reke bom naredil otoke in posušil bom ribnike.',
        16: 'Privedel bom slepe po poti, ki je niso poznali, vodil jih bom po stezah, ki jih niso poznali. Temo pred njimi bom naredil svetlobo in skrivljene stvari ravne. Te stvari jim bom storil in ne bom jih zapustil.',
        17: 'Obrnjeni bodo nazaj, silno bodo osramočeni tisti, ki zaupajo v rezane podobe, ki ulitim podobam pravijo: ›Vi ste naši bogovi.‹',
        18: 'Poslušajte, vi gluhi, in glejte, vi slepi, da boste lahko videli.',
        19: 'Kdo je slep, razen mojega služabnika? Ali gluh kakor moj poslanec, ki sem ga poslal? Kdo je slep, kakor kdor je popoln in slep kakor Gospodov služabnik?',
        20: 'Gleda mnoge stvari, toda ti jih ne obeležuješ; odpira ušesa, toda on ne sliši.',
        21: 'Gospod je zelo zadovoljen zaradi svoje pravičnosti; poveličeval bo postavo in jo naredil častitljivo.',
        22: 'Toda to je ljudstvo, oropano in oplenjeno; vsi izmed njih so ujeti v luknje in skriti v jetnišnicah. Za plen so in nihče ne osvobaja; za ukradeno blago in nihče ne reče: ›Povrni.‹',
        23: 'Kdo izmed vas bo temu pazljivo prisluhnil? Kdo bo prisluhnil in slišal za čas, ki pride?',
        24: 'Kdo je Jakoba izročil v plen in Izraela roparjem? Mar ne Gospod, on, zoper katerega smo grešili? Kajti niso želeli hoditi po njegovih poteh niti niso bili poslušni njegovi postavi.',
        25: 'Zato je nanj izlil razjarjenost svoje jeze in moč bitke. To ga je vžgalo vsenaokoli, vendar ni vedel. To ga je žgalo, vendar si tega ni vzel k srcu.«',
    },
    43: {
        1: 'Toda sedaj tako govori Gospod, ki te je ustvaril, oh Jakob in tisti, ki te je oblikoval, oh Izrael: »Ne boj se, kajti odkupil sem te, poklical sem te s tvojim imenom, moj si.',
        2: 'Ko hodiš skozi vode, bom s teboj in skozi reke, te ne bodo preplavile. Ko hodiš skozi ogenj, ne boš ožgan niti se plamen ne bo vnel na tebi.',
        3: 'Kajti jaz sem Gospod, tvoj Bog, Sveti Izraelov, tvoj Odrešenik. Egipt sem dal za tvojo odkupnino, Etiopijo in Sebo zate.',
        4: 'Ker si bil dragocen v mojem pogledu, bil si častitljiv in jaz sem te ljubil. Zato bom zate dal ljudi in ljudstva za tvoje življenje.',
        5: 'Ne boj se, kajti jaz sem s teboj. Tvoje seme bom privedel od vzhoda in te zbral od zahoda.',
        6: 'Severu bom rekel: ›Izroči‹ in jugu: ›Ne zadržuj.‹ Moje sinove privedi od daleč in moje hčere od koncev zemlje,',
        7: 'celó vsakega, ki je klican z mojim imenom, kajti jaz sem ga ustvaril za svojo slavo, jaz sem ga oblikoval; da, jaz sem ga naredil.',
        8: 'Privedi slepo ljudstvo, ki ima oči in gluhe, ki imajo ušesa.',
        9: 'Naj bodo vsi narodi zbrani skupaj in naj bo ljudstvo zbrano. Kdo izmed njih lahko to razglasi in nam pokaže prejšnje stvari? Naj privedejo naprej svoje priče, da bodo lahko opravičeni. Ali naj slišijo in rečejo: › To je resnica.‹',
        10: 'Vi ste moje priče,‹ govori Gospod in moj služabnik, ki sem ga izbral, da me boste lahko poznali in mi verjeli in razumeli, da jaz sem ta. Pred menoj ni bil oblikovan noben Bog niti ne bo za menoj.',
        11: 'Jaz, celó jaz sem Gospod in poleg mene ni rešitelja.',
        12: 'Razglasil sem, rešil in pokazal, ko med vami ni bilo nobenega tujega boga. Zato ste vi moje priče,‹ govori Gospod, ›da jaz sem Bog.',
        13: 'Da, preden je bil dan, jaz sem in nobenega ni, ki lahko osvobodi iz moje roke. Delal bom in kdo bo to dopustil?‹',
        14: 'Tako govori Gospod, vaš odkupitelj, Sveti Izraelov: ›Zaradi vas sem poslal v Babilon in ponižal vse njihove plemiče in Kaldejce, katerih vpitje je na ladjah.',
        15: 'Jaz sem Gospod, vaš Sveti, stvarnik Izraela, vaš Kralj.‹',
        16: 'Tako govori Gospod, ki dela pot v morju in stezo v mogočnih vodah,',
        17: 'ki privede naprej bojni voz in konja, vojsko in moč; skupaj se bodo ulegli, ne bodo vstali. Izumrli so, pogašeni so kakor predivo.',
        18: 'Ne spominjajte se prejšnjih stvari niti ne preudarjajte stvari od davnine.',
        19: 'Glejte, storil bom novo stvar. Sedaj bo ta vzbrstela; mar tega ne boste spoznali? Naredil bom celo pot v divjini in reke v puščavi.',
        20: 'Divja žival polja me bo spoštovala, zmaji in sove, ker dam vode v divjino in reke v puščavo, da dam piti svojemu ljudstvu, svojim izbranim.',
        21: 'To ljudstvo sem oblikoval zase, naznanjali bodo mojo hvalo.',
        22: 'Toda ti nisi klical k meni, oh Jakob, temveč si se me naveličal, oh Izrael.',
        23: 'Nisi mi privedel majhne živine od svojih žgalnih daritev niti me nisi častil s svojimi klavnimi daritvami. Nisem ti storil, da služiš z daritvijo niti te nisem mučil s kadilom.',
        24: 'Z denarjem mi nisi kupil nobenega sladkornega trsta niti me nisi nasičeval s tolščo svojih klavnih daritev, temveč si me s svojimi grehi primoral, da služim; izmučil si me s svojimi krivičnostmi.',
        25: 'Jaz, celó jaz, sem tisti, ki zaradi sebe izbrisujem tvoje prestopke in se ne bom spominjal tvojih grehov.',
        26: 'Spomni me, skupaj se pravdajva. Ti razglasi, da boš lahko opravičen.',
        27: 'Tvoj prvi oče je grešil in tvoji učitelji so se pregrešili zoper mene.',
        28: 'Zato sem oskrunil prince svetišča in dal Jakoba v prekletstvo in Izraela v graje.',
    },
    44: {
        1: 'Vendar sedaj poslušaj, oh Jakob, moj služabnik in Izrael, ki sem ga izbral:',
        2: '»Tako govori Gospod, ki te je naredil in te oblikoval iz maternice, ki ti bo pomagal: ›Ne boj se, oh Jakob, moj služabnik in ti Ješurún, ki sem ga izbral.',
        3: 'Kajti vodo bom izlil na tistega, ki je žejen in poplave na suha tla. Svojega duha bom izlil na tvoje seme in svoj blagoslov na tvoje potomstvo.',
        4: 'Pognali bodo kakor med travo, kakor vrbe ob vodnih tokovih.',
        5: 'Nekdo bo rekel: ›Jaz sem Gospodov,‹ drugi se bo imenoval po Jakobovem imenu, drugi se bo s svojo roko podpisal Gospodu in se poimenoval po imenu Izrael.',
        6: 'Tako govori Gospod, Izraelov Kralj in njegov odkupitelj, Gospod nad bojevniki: ›Jaz sem prvi in jaz sem zadnji in poleg mene ni Boga.',
        7: 'Kdo bo klical kakor jaz in bo to razglasil in bo to uredil zame, odkar sem določil starodavno ljudstvo? Stvari, ki prihajajo in bodo prišle, naj jim jih oni pokažejo.',
        8: 'Ne bojte se niti ne bodite prestrašeni. Mar ti nisem povedal od tistega časa in ti to razglasil? Vi ste celo moje priče. Mar je Bog razen mene? Da, tam ni Boga, jaz ne poznam nobenega.',
        9: 'Tisti, ki delajo rezano podobo, so vsi izmed njih ničnost in njihove izvrstne stvari ne bodo koristile in oni so svoje lastne priče; ne vidijo niti ne vedo, da bi jih bilo sram.',
        10: 'Kdo je oblikoval boga ali ulil rezano podobo, ki ni koristna za nič?',
        11: 'Glej, vsi njegovi tovariši bodo osramočeni in delavci, oni so izmed ljudi. Naj bodo vsi zbrani skupaj, naj vstanejo; vendar se bodo bali in skupaj bodo osramočeni.',
        12: 'Kovač s kleščami dela tako v oglju, kakor ga oblikuje s kladivi in ga izdeluje z močjo svojih laktov. Da, lačen je in njegova moč peša. Ne pije vode in je slaboten.',
        13: 'Lesorezec izteza svoje merilo, označuje s črtalom, oblikuje z dleti in ga začrtuje s šestilom in ga dela po podobi človeka, glede na človeško lepoto, da bi ta lahko ostal v hiši.',
        14: 'Poseka si cedre in jemlje cipreso in hrast, ki si jih je okrepil med gozdnimi drevesi, zasadi veliki jesen in dež ga neguje.',
        15: 'Potem bo to za človeka, da zakuri, kajti vzel bo od tega in se ogrel; da, to vžge in speče kruh; da, naredi boga in ga obožuje; izdela rezano podobo in pada dol k njej.',
        16: 'Del od tega zakuri v ognju, z delom od tega jé meso, speče pečenko in je nasičen. Da, ogreje se in reče: ›Aha, topel sem, videl sem ogenj.‹',
        17: 'Od preostanka pa si izdela boga, celó svojo rezano podobo, pada dol k njej in jo obožuje in moli k njej ter pravi: ›Osvobodi me, kajti ti si moj bog.‹',
        18: 'Niso spoznali niti razumeli, kajti zaprl je njihove oči, da ne morejo videti in njihova srca, da ne morejo razumeti.',
        19: 'In nihče ne preudari v svojem srcu niti tam ni spoznanja niti razumevanja, da reče: ›Del tega sem spekel v ognju; da, na njegovi žerjavici sem spekel tudi kruh, spekel sem meso in ga pojedel in njegov preostanek bom naredil [za] ogabnost? Ali bom padal dol k štoru?',
        20: 'Hrani se s pepelom, zavedeno srce ga je obrnilo vstran, da ne more osvoboditi svoje duše niti reči: › Mar ni laž v moji desnici?‹',
        21: 'Spomni se tega, oh Jakob in Izrael, kajti ti si moj služabnik. Jaz sem te oblikoval, ti si moj služabnik. Oh Izrael, ne bom te pozabil.',
        22: 'Tvoje prestopke sem izbrisal kakor gost oblak in kakor oblak tvoje grehe. Vrni se k meni, kajti jaz sem te odkupil.',
        23: 'Pojte, oh ve nebesa, kajti Gospod je to storil. Vpijte globočine zemlje. Izbruhnite v petje, ve gore, oh gozd in vsako drevo v njem, kajti Gospod je odkupil Jakoba in se proslavil v Izraelu.',
        24: 'Tako govori Gospod, tvoj odkupitelj in on, ki te je oblikoval iz maternice, jaz sem Gospod, ki delam vse stvari, ki sam razprostiram nebo, ki sam na široko razširjam zemljo;',
        25: 'ki onemogočam simbole lažnivcev in vedeževalce delam besne; ki modre može obračam nazaj in njihovo znanje delam nespametno;',
        26: 'ki potrjujem besedo svojega služabnika in izvajam nasvet svojih poslancev; ki [prestolnici] Jeruzalemu pravim: ›Naseljena boš‹ in Judovim mestom: ›Zgrajena boste‹ in jaz bom vzdignil njihove razpadle kraje.',
        27: 'Ki pravim globini: ›Bodi suha‹ in posušil bom tvoje reke;',
        28: 'ki pravim o Kiru: › On je moj pastir‹ in izvršil bo vse moje zadovoljstvo. Celo Jeruzalemu govorim: ›Zgrajen boš;‹ in templju: ›Tvoj temelj bo položen.‹«',
    },
    45: {
        1: 'Tako govori Gospod svojemu maziljencu Kiru, čigar desnico sem prijel, da bi pred njim podjarmil narode in odpasal bom ledja kraljev, da pred njim odprem dvoje opuščenih velikih vrat in velika vrata ne bodo zaprta:',
        2: '»Jaz bom šel pred teboj in naredil skrivljene kraje ravne, bronasta velika vrata bom razbil na koščke in železne zapahe presekal na dvoje.',
        3: 'Dal ti bom zaklade teme in skrita bogastva skrivnih krajev, da boš lahko vedel, da sem jaz, Gospod, ki te kličem s tvojim imenom, Izraelov Bog.',
        4: 'Zaradi Jakoba, mojega služabnika in Izraela, mojega izvoljenega, sem te celó poklical po tvojem imenu. Imenoval sem te, čeprav me nisi poznal.',
        5: 'Jaz sem Gospod in nobenega drugega ni, ni Boga poleg mene. Opasal sem te, čeprav me nisi poznal,',
        6: 'da bi lahko vedeli od sončnega vzhoda in od zahoda, da ni nikogar poleg mene. Jaz sem Gospod in nobenega drugega ni.',
        7: 'Jaz oblikujem svetlobo in ustvarjam temo, sklepam mir in ustvarjam zlo. Jaz, Gospod, delam vse te stvari.',
        8: 'Kapljajte, ve nebesa od zgoraj in naj nebo izlije pravičnost. Naj se zemlja odpre in naj rodi rešitev duš in naj skupaj požene pravičnost; jaz, Gospod, sem to ustvaril.',
        9: 'Gorje tistemu, ki se prepira s svojim Stvarnikom! Naj se črepinja prička s črepinjami zemlje. Mar bo ilo reklo tistemu, ki ga oblikuje: »Kaj delaš?« Ali tvoje delo: »On nima rok?«',
        10: 'Gorje tistemu, ki pravi svojemu očetu: »Čemu si zaplodil?« Ali ženski: »Kaj si rodila?«',
        11: 'Tako govori Gospod, Sveti Izraelov in njegov Stvarnik: »Vprašajte me o stvareh, ki pridejo, glede mojih sinov in glede dela mojih rok mi zapovejte.',
        12: 'Naredil sem zemljo in na njej ustvaril človeka. Jaz, celó moje roke so razprostrle nebo in zapovedal sem vsej njegovi vojski.',
        13: 'Dvignil sem ga v pravičnosti in jaz bom usmerjal vse njegove poti. Zgradil bo moje mesto in izpustil bo moje ujetnike, ne za ceno niti [ne za] nagrado,« govori Gospod nad bojevniki.',
        14: 'Tako govori Gospod: »Trud Egipta in trgovanje Etiopije in Sabejcev, postavnih mož, bo prišlo k tebi in oni bodo tvoji. Prišli bodo za teboj, v verigah bodo prišli in padli dol k tebi, ponižno te bodo prosili, rekoč: ›Zagotovo je Bog v tebi in tam ni nikogar drugega, tam ni Boga.‹',
        15: 'Resnično, ti si Bog, ki samega sebe skrivaš, oh Izraelov Bog, Odrešenik.',
        16: 'Osramočeni bodo in tudi zbegani, vsi izmed njih. Skupaj bodo šli v zmešnjavo, ki so izdelovalci malikov.',
        17: 'Toda Izrael bo rešen v Gospodu z večno rešitvijo duš. Ne boste osramočeni niti zbegani, od veka do veka.',
        18: 'Kajti tako govori Gospod, ki je ustvaril nebo; sam Bog, ki je oblikoval zemljo in jo naredil, osnoval jo je, ni je ustvaril zaman, oblikoval jo je, da bi bila naseljena. Jaz sem Gospod in nobenega drugega ni.',
        19: 'Nisem govoril na skrivnem, na temnem kraju zemlje. Jakobovemu semenu nisem rekel: ›Zaman me iščite.‹ Jaz, Gospod, govorim pravičnost, razglašam stvari, ki so pravilne.',
        20: 'Zberite se in pridite, približajte se skupaj, vi, ki ste pobegnili narodom. Nimajo spoznanja, ki postavljajo les svojih rezanih podob in molijo k bogu, ki ne more rešiti.',
        21: 'Povejte in privedite jih blizu; da, naj se skupaj posvetujejo. Kdo je to razglasil od starodavnega časa? Kdo je to povedal od tistega časa? Mar nisem jaz, Gospod? In nobenega drugega Boga ni poleg mene, pravičnega Boga in Odrešenika, nobenega ni poleg mene.',
        22: 'Poglejte k meni in bodite rešeni, vsi konci zemlje, kajti jaz sem Bog in nobenega drugega ni.',
        23: 'Prisegel sem sam pri sebi, beseda je izšla iz mojih ust v pravičnosti in se ne bo vrnila: ›Da se bo k meni priklonilo vsako koleno, vsak jezik bo prisegel.‹',
        24: 'Zagotovo bo nekdo rekel: ›V Gospodu imam pravičnost in moč.‹ Celó k njemu bodo prišli ljudje in vsi tisti, ki so ogorčeni zoper njega, bodo osramočeni.',
        25: 'V Gospodu bo vse seme Izraela opravičeno in bo slavilo.',
    },
    46: {
        1: 'Bel se je upognil dol, Nebó se sklanja, njihovi maliki so bili na živalih in na živini. Vaši vozovi so bili težko obloženi, breme so vsaki izmučeni živini.',
        2: 'Sklonili so se, skupaj so se upognili, niso mogli osvoboditi bremena, temveč so sami šli v ujetništvo.',
        3: 'Prisluhnite mi, oh hiša Jakobova in ves ostanek Izraelove hiše, ki vas nosim od trebuha, ki ste nošeni od maternice.',
        4: 'Celó do vaše visoke starosti jaz sem in celó do osivelih las vas bom prenašal. Jaz sem naredil, jaz bom vzdignil, celó jaz bom nosil in vas osvobodil.',
        5: 'S kom me boste primerjali in me naredili enakega in me primerjali, da bi bila lahko podobna?',
        6: 'Iz torbe iztresajo zlato in na tehtnici tehtajo srebro in najemajo zlatarja in ta ga naredi boga. Padajo dol, da, obožujejo.',
        7: 'Vzdignejo ga na ramo, prenašajo ga in ga postavljajo na njegov prostor in ta stoji, iz svojega prostora se ne bo odstranil. Da, nekdo bo vpil k njemu, vendar mu ne more odgovoriti niti ga rešiti iz njegove stiske.',
        8: 'Spomnite se tega in bodite možje. Ponovno premislite, oh vi, prestopniki.',
        9: 'Spominjajte se prejšnjih stvari od davnine, kajti jaz sem Bog in ni nikogar drugega, jaz sem Bog in nobenega ni podobnega meni,',
        10: 'konec razglašam od začetka in od starodavnih časov stvari, ki še niso storjene, rekoč: ›Moj nasvet bo obstal in storil bom vse, kar mi ugaja.',
        11: 'Ptico roparico kličem od vzhoda, moža, ki izvršuje mojo namero iz daljne dežele. Da, jaz sem to govoril, jaz bom tudi privedel, da se zgodi, to sem namenil in to bom tudi storil.',
        12: 'Prisluhnite mi, vi arogantni, ki ste daleč od pravičnosti,',
        13: 'svojo pravičnost privedem blizu; ta ne bo daleč stran in moja rešitev duš ne bo mudila. Rešitev duš bom postavil na Sion zaradi Izraela, svoje slave.',
    },
    47: {
        1: 'Pridi dol in se usedi v prah, oh devica, hči babilonska. Sedi na tla; ni prestola, oh hči Kaldejcev, kajti ne boš več imenovana nežna in prefinjena.',
        2: 'Vzemi mlinske kamne in melji moko. Odkrij svoja zagrinjala, razgali nogo, odkrij stegno, prebredi reke.',
        3: '§ Tvoja nagota bo odkrita, da, tvoja sramota bo vidna. Maščeval se bom in ne bom te srečal kakor človek.',
        4: 'Glede našega odkupitelja, Gospod nad bojevniki je njegovo ime, Sveti Izraelov.',
        5: 'Sedi tiho in pojdi v temo, oh hči Kaldejcev, kajti ne boš več imenovana: ›Gospa kraljestev.‹',
        6: 'Ogorčen sem bil nad svojim ljudstvom, umazal sem svojo dediščino in jih predal v tvojo roko. Nobenega usmiljenja jim nisi pokazala, na starce si zelo težko položila svoj jarem.',
        7: 'In ti praviš: ›Jaz bom gospa na veke.‹ Tako, da si teh stvari nisi vzela k srcu niti se nisi spomnila zadnjega konca tega.',
        8: 'Zato poslušaj sedaj to, ti, ki si predana užitkom, ki brezskrbno prebivaš, ki v svojem srcu praviš: ›Jaz sem in nihče drug poleg mene; ne bom sedela kakor vdova niti ne bom poznala izgube otrok.‹',
        9: 'Toda ti dve stvari bosta prišli k tebi v trenutku, v enem dnevu, izguba otrok in vdovstvo. Nadte bodo prišli v svoji popolnosti zaradi množice tvojih čarodejstev in zaradi silnega obilja tvojih izrekanj urokov.',
        10: 'Kajti zaupala si v svojo zlobnost. Rekla si: ›Nihče me ne vidi.‹ Tvoja modrost in tvoje znanje te je sprevrglo in v svojem srcu si rekla: ›Jaz sem in nihče drug poleg mene.‹',
        11: 'Zato bo nadte prišlo zlo; ne boš vedela od kod vstaja in nate bo padla vragolija; ne boš je sposobna odložiti in opustošenje bo nenadoma prišlo nadte, ki ga ne boš poznala.',
        12: 'Postavi se sedaj s svojimi izrekanji urokov in z množico svojih čarodejstev, s katerimi si se trudila od svoje mladosti, če ti bo to lahko koristilo, če boš lahko prevladala.',
        13: 'Izmučena si v množici svojih nasvetov. Naj sedaj astrologi, zvezdogledi in mesečni napovedovalci vstanejo in te rešijo pred temi stvarmi, ki bodo prišle nadte.',
        14: 'Glej, so kakor strnišče, ogenj jih bo sežgal, ne bodo se osvobodili iz oblasti plamena. Tam ne bo žerjavice, da bi se ob njej ogreli niti ognja, da bi pred njim sedeli.',
        15: 'Takšni ti bodo tisti, s katerimi si se trudila, celó tvoji trgovci od tvoje mladosti. Tavali bodo vsakdo k svoji četrti, nihče te ne bo rešil.',
    },
    48: {
        1: 'Poslušajte to, oh hiša Jakobova, ki ste imenovani z imenom Izrael in ste izšli iz Judovih vodá, ki prisegate pri Gospodovem imenu in omenjate Izraelovega Boga, vendar ne v resnici niti ne v pravičnosti.',
        2: 'Kajti imenujejo se po svetem mestu in se naslanjajo na Izraelovega Boga; Gospod nad bojevniki je njegovo ime.',
        3: 'Razglasil sem prejšnje stvari od začetka in izšle so iz mojih ust in pokazal sem jih; nenadoma sem jih naredil in zgodile so se.',
        4: 'Ker sem vedel, da si trdovratna in je tvoj vrat železna kita in tvoja obrv bron,',
        5: 'sem ti to celo od začetka razglasil; preden se je zgodilo, sem ti to pokazal, da ne bi rekla: ›Moj malik jih je naredil, moja rezana podoba in moja ulita podoba jim je zapovedala.‹',
        6: 'Slišal si, videl si vse to in ali ne boš tega razglasil? Od tega časa sem ti pokazal nove stvari, celo skrite stvari in ti jih nisi poznal.',
        7: 'Sedaj so ustvarjene in ne od začetka; celo pred dnevom, ko jih nisi slišal, da ne bi rekel: »Glej, poznal sem jih.«',
        8: 'Da, ne slišiš; da, ne poznaš; da, od tistega časa, ko tvoje uho ni bilo odprto, kajti vedel sem, da boš postopal zelo zahrbtno in si bil od maternice imenovan prestopnik.',
        9: 'Zaradi svojega imena bom odložil svojo jezo in zaradi svoje hvale se bom zadržal, da te ne odsekam.',
        10: 'Glej, prečistil sem te, toda ne s srebrom; izbral sem te v talilni peči stiske.',
        11: 'Zaradi sebe, celó zaradi sebe, bom to storil, kajti kako bi bilo moje ime umazano? In svoje slave ne bom dal drugemu.',
        12: 'Prisluhni mi, oh Jakob in Izrael, moj poklicani; jaz sem; jaz sem prvi, jaz sem tudi zadnji.',
        13: 'Moja roka je tudi položila temelj zemlji in moja desnica je razpela nebo. Ko kličem k njima, skupaj vstaneta.',
        14: 'Vsi vi, zberite se in poslušajte; kdo izmed njih je razglasil te stvari? Gospod ga je ljubil. Storil bo, kar mu ugaja nad Babilonom in njegov laket bo na Kaldejcih.',
        15: 'Jaz, celó jaz, sem govoril. Da, poklical sem ga. Privedel sem ga in svojo pot bo naredil uspešno.',
        16: 'Pridite blizu k meni, poslušajte to; od začetka nisem govoril na skrivnem; od časa, ko je to bilo, tam jaz sem. In sedaj me je poslal Gospod Bog in njegov Duh.«',
        17: 'Tako govori Gospod, tvoj Odkupitelj, Sveti Izraelov: »Jaz sem Gospod, tvoj Bog, ki te učim, da boš imel koristi, ki te vodim po poti, po kateri naj bi šel.',
        18: 'Oh, da bi prisluhnil mojim zapovedim! Potem bi bil tvoj mir kakor reka in tvoja pravičnost kakor morski valovi.',
        19: 'Tudi tvojega semena bi bilo kakor peska in potomstvo tvoje notranjosti podobno njegovemu gramozu; njegovo ime ne bi bilo odrezano niti uničeno izpred mene.',
        20: 'Pojdite naprej iz Babilona, pobegnite od Kaldejcev, z glasom petja razglasite, povejte to, izustite to celó do konca zemlje. Recite: › Gospod je odkupil svojega služabnika Jakoba.‹',
        21: 'Niso bili žejni, ko jih je vodil skozi puščave. Zanje je vodam veleval, da tečejo iz skale. Razklal je tudi skalo in iz nje so pridrle vode.',
        22: 'Tam ni miru,« govori Gospod, »zlobnemu.«',
    },
    49: {
        1: 'Poslušajte me, oh otoki in prisluhnite, ve ljudstva od daleč. Gospod me je poklical iz maternice, od notranjosti moje matere je naredil omembo mojega imena.',
        2: 'Moja usta je naredil kakor oster meč; v senco svoje roke me je skril in me naredil zglajeno puščico; v svojem tulu me je skril',
        3: 'in mi rekel: »Ti si moj služabnik, oh Izrael, v katerem bom proslavljen.«',
        4: 'Potem sem rekel: »V prazno sem se trudil, svojo moč sem porabil zaman in v prazno. Vendar je zagotovo moja sodba z Gospodom in moje delo z mojim Bogom.«',
        5: '»In sedaj,« govori Gospod, ki me je oblikoval od maternice, da bi bil njegov služabnik, da Jakoba ponovno privedem k njemu: »Čeprav Izrael ne bi bil zbran, bom vendar veličasten v Gospodovih očeh in moj Bog bo moja moč.«',
        6: 'Rekel je: »To je lahka stvar, da bi bil moj služabnik, da vzdigneš Jakobove rodove in da obnoviš Izraelove ohranjene. Prav tako te bom dal za svetlobo poganom, da boš lahko moja rešitev duš do konca zemlje.',
        7: 'Tako govori Gospod, Izraelov Odkupitelj in njegov Sveti tistemu, ki ga človek prezira, tistemu, ki ga narod zaničuje, služabniku vladarjev: ›Kralji bodo videli in vstali, tudi princi bodo oboževali zaradi Gospoda, ki je zvest in Svetega Izraelovega in on bo izbral tebe.‹«',
        8: 'Tako govori Gospod: »Ob sprejemljivem času sem te uslišal in na dan rešitve duše sem ti pomagal in ohranil te bom in te dal za zavezo ljudstvu, da povzdigneš deželo, da povzročiš, da podedujejo zapuščene dediščine,',
        9: 'da boš lahko ujetnikom rekel: ›Pojdite naprej;‹ tistim, ki so v temi: ›Pokažite se.‹ Pasli bodo po poteh in njihovi pašniki bodo na vseh visokih krajih.',
        10: 'Ne bodo niti lačni niti žejni, niti jih ne bosta udarila, niti vročina, niti sonce, kajti on, ki ima usmiljenje do njih, jih bo vodil, celo pri vodnih izvirih jih bo usmerjal.',
        11: 'Vse svoje gore bom naredil pot in moje glavne ceste bodo povišane.',
        12: 'Glej, ti bodo prišli od daleč in glej, ti od severa in od zahoda in ti iz dežele Siním.«',
        13: 'Prepevaj, oh nebo in bodi radostna, oh zemlja in izbruhnite v petje, oh gore. Kajti Gospod je potolažil svoje ljudstvo in usmiljen bo do svojih trpečih.',
        14: 'Toda Sion je rekel: » Gospod me je zapustil in moj Gospod me je pozabil.«',
        15: 'Mar lahko ženska pozabi svojega doječega otroka, da ne bi imela sočutja do sina svoje maternice? Da, one lahko pozabijo, vendar jaz ne bom pozabil tebe.',
        16: 'Glej, vrezal sem te na dlani svojih rok, tvoja obzidja so nenehno pred menoj.',
        17: 'Tvoji otroci se bodo podvizali, tvoji uničevalci in tisti, ki so te naredili opustošeno, bodo šli od tebe.',
        18: 'Dvigni svoje oči naokoli in poglej. Vsi ti se zbirajo skupaj in prihajajo k tebi. Kakor jaz živim,‹ govori Gospod, ›zanesljivo se boš oblekla z njimi vsemi, kakor z ornamentom in si jih privezala nase, kakor stori nevesta.',
        19: 'Kajti tvoji opustošeni in tvoji zapuščeni kraji in dežela tvojega uničenja bo sedaj torej preozka zaradi prebivalcev in tisti, ki so te pogoltnili, bodo daleč proč.',
        20: 'Otroci, ki jih boš imela, potem ko si izgubila druge, bodo v tvoja ušesa ponovno govorili: ›Kraj je preozek zame. Daj mi prostor, da bom lahko prebival.‹',
        21: 'Potem boš v svojem srcu rekla: ›Kdo mi je te rodil, glede na to, da sem izgubila svoje otroke in sem zapuščena, ujetnica in se selim sem ter tja? In kdo je te vzgojil? Glej, sama sem ostala, kje so bili tile?‹«',
        22: '§ Tako govori Gospod Bog: »Glej, svojo roko bom dvignil k poganom in svoj prapor postavil k ljudstvu in tvoje sinove bodo privedli na njihovih rokah in tvoje hčere bodo nošene na njihovih ramah.',
        23: 'Kralji bodo tvoji negovalni očetje in njihove kraljice tvoje negovalne matere. S svojim obrazom se bodo priklonili k tebi proti zemlji in lizali prah tvojih stopal in vedela boš, da jaz sem Gospod, kajti tisti, ki čakajo name, ne bodo osramočeni.',
        24: 'Mar bo plen vzet od mogočnega, mar bo pravično ujetništvo osvobojeno?«',
        25: 'Toda tako govori Gospod: »Celo ujetniki mogočnega bodo odvzeti in plen strašnega bo osvobojen, kajti jaz se bom spoprijel s tistim, ki se spoprijema s teboj in jaz bom rešil tvoje otroke.',
        26: 'Z njihovim lastnim mesom bom hranil tiste, ki te zatirajo in pijani bodo s svojo lastno krvjo kakor s sladkim vinom in vse meso bo vedelo, da jaz sem Gospod, tvoj Odrešenik in tvoj Odkupitelj, Mogočni Jakobov.‹«',
    },
    50: {
        1: 'Tako govori Gospod: »Kje je ločitveni list vaše matere, ki sem jo odslovil? Ali kateri izmed mojih upnikov je ta, h kateremu sem vas prodal? Glejte, zaradi svojih krivičnosti ste se sami prodali in zaradi vaših prestopkov je vaša mati odslovljena.',
        2: 'Zakaj ni bilo človeka, ko sem prišel? Ko sem klical ni bilo nobenega, da odgovori? Mar je moja roka precej skrajšana, da ne more odkupiti? Mar nimam moči, da osvobodim? Glejte, ob svoji graji posušim morje, reke naredim za divjino. Njihove ribe zaudarjajo, ker tam ni vode in poginjajo zaradi žeje.',
        3: 'Jaz obláčim nebo s črnino in vrečevino delam [za] njihovo pokrivalo.',
        4: 'Gospod Bog mi je dal jezik učenega, da bi vedel kako ob pravem času govoriti besedo tistemu, ki je izmučen. Zbuja [me] jutro za jutrom, on zbuja moje uho, da slišim kakor učeni.',
        5: 'Gospod Bog mi je odprl moje uho in nisem bil uporen, niti se nisem odvrnil nazaj.',
        6: 'Svoj hrbet sem dal tistim, ki so me udarjali in svoja lica tistim, ki so mi pulili brado. Svojega obraza nisem skril pred sramoto in pljuvanjem.',
        7: 'Kajti Gospod Bog mi bo pomagal, zato ne bom zbegan. Zato sem svoj obraz naravnal kakor kremen in vem, da ne bom osramočen.',
        8: 'Blizu je ta, ki me opravičuje. Kdo se bo spoprijel z menoj? Stopiva skupaj. Kdo je moj nasprotnik? Naj pride bliže k meni.',
        9: 'Glej, Gospod Bog mi bo pomagal; kdo je tisti, ki me bo obsojal? Glej, vsi se bodo postarali kakor obleka, molj jih bo požrl.',
        10: 'Kdo je med vami, ki se boji Gospoda, ki uboga glas svojega služabnika, ki hodi v temi in nima svetlobe? Naj zaupa v Gospodovo ime in se naslanja na svojega Boga.',
        11: 'Glejte, vsi vi, ki prižigate ogenj, ki se naokrog obdajate z iskrami. Hodite v svetlobi svojega ognja in v iskrah, ki ste jih vžgali. To boste imeli od moje roke; ulegli se boste v bridkosti.',
    },
    51: {
        1: 'Prisluhnite mi, vi, ki sledite pravičnosti, vi, ki iščete Gospoda. Glejte na skalo, iz katere ste izklesani in k luknji jame, iz katere ste izkopani.',
        2: 'Poglejte na Abrahama, svojega očeta in na Saro, ki vas je rodila. Kajti poklical sem ga samega, ga blagoslovil in namnožil.',
        3: 'Kajti Gospod bo tolažil Sion, tolažil bo vse njegove opustošene kraje in njegovo divjino bo naredil podobno Edenu in njegovo puščavo podobno Gospodovemu vrtu. V njem bo najti radost in veselje, zahvaljevanje in glas melodije.',
        4: 'Prisluhni mi, moje ljudstvo; pazljivo mi prisluhni, oh moj narod. Kajti postava bo izšla od mene in svojo sodbo bom naredil, da počiva za svetlobo ljudstvu.',
        5: 'Moja pravičnost je blizu, moja rešitev duš je odšla naprej in moji lakti bodo sodili ljudstvo; otoki bodo čakali name in v moj laket bodo zaupali.',
        6: 'Povzdignite svoje oči k nebu in poglejte dol na zemljo spodaj, kajti nebo bo izginilo proč kakor dim in zemlja se bo postarala kakor obleka in tisti, ki prebivajo na njej, bodo umrli na podoben način, toda moja rešitev duš bo večna in moja pravičnost ne bo odpravljena.',
        7: 'Prisluhnite mi vi, ki poznate pravičnost, ljudstvo, v čigar srcu je moja postava. Ne bojte se graje ljudi niti ne bodite prestrašeni ob njihovih zasramovanjih.',
        8: 'Kajti molj jih bo pojedel kakor obleko in ličinka jih bo pojedla kakor volno, toda moja pravičnost bo na veke in moja rešitev duš od roda do roda.',
        9: 'Zbudi se, zbudi se, nadeni si moč, oh Gospodov laket. Zbudi se kakor v starodavnih dneh in rodovih od davnine. Mar nisi ti tisti, ki je posekal Rahaba in ranil zmaja?',
        10: 'Mar nisi ti tisti, ki je osušil morje, vode velike globine, ki je globine morja spremenil v pot za odkupljene, da so prešli?',
        11: 'Zato se bodo Gospodovi odkupljenci vrnili in s petjem prišli na Sion in večna radost bo na njihovi glavi. Dosegli bodo veselje in radost, bridkost in žalovanje pa bosta pobegnila.',
        12: 'Jaz, celó jaz sem ta, ki vas tolaži. Kdo si ti, da bi se bal človeka, ki bo umrl in človeškega sina, ki bo narejen kot trava,',
        13: 'pozabljaš pa Gospoda, svojega stvarnika, ki je razprostrl nebo in položil temelje zemlji in si se nenehno vsak dan bal zaradi razjarjenosti zatiralca, kakor če bi bil ta pripravljen, da uniči? In kje je zatiralčeva razjarjenost?',
        14: 'Ujeti popotnik hiti, da bi bil lahko izpuščen in da ne bi umrl v jami niti da njegovega kruha ne bi zmanjkalo.',
        15: 'Toda jaz sem Gospod, tvoj Bog, ki je razdelil morje, katerega valovi rjovijo: » Gospod nad bojevniki je njegovo ime.«',
        16: 'Svoje besede sem položil v tvoja usta in te zakril v senco svoje roke, da lahko zasadim nebo in položim temelje zemlji in rečem Sionu: ›Ti si moje ljudstvo.‹',
        17: 'Zbudi se, zbudi se, vstani, oh [prestolnica] Jeruzalem, ki si pila pri Gospodovi roki čašo njegove razjarjenosti. Pila si droži iz čaše trepetanja in jih posrebala.',
        18: 'Nikogar ni, da jo usmerja med vsemi sinovi, ki jih je rodila niti ni nikogar izmed njenih sinov, ki jih je vzgojila, da jo prime za roko.',
        19: 'Ti dve stvari sta prišli nadte; komu bo žal zate? Opustošenje, poguba, lakota in meč. Po kom te bom potolažil?',
        20: 'Tvoji sinovi so oslabeli, ležijo na vrhu vseh ulic, kakor divji bik v mreži. Polni so Gospodove razjarjenosti, graje tvojega Boga.',
        21: 'Zato poslušaj sedaj to, ti trpeča in pijana, toda ne z vinom.',
        22: 'Tako govori tvoj Gospod, Gospod in tvoj Bog, ki se poteguje za stvar svojega ljudstva: »Glej, iz tvoje roke sem vzel čašo trepetanja, celó droži iz čaše svoje razjarjenosti. Ne boš je več ponovno pila,',
        23: 'temveč jo bom položil v roko tistih, ki te stiskajo, ki so tvoji duši rekli: ›Skloni se, da lahko gremo preko‹ in svoje telo si položila kakor tla in kakor ulico tistim, ki so šli preko.',
    },
    52: {
        1: 'Prebudi se, prebudi se, nadeni svojo moč, oh Sion, nadeni svoje krasne obleke, oh [prestolnica] Jeruzalem, sveto mesto, kajti odslej vate ne bo več vstopil neobrezani in nečisti.',
        2: 'Otresi si prah, vstani in usedi se, oh [prestolnica] Jeruzalem, odveži si vezi iz svojega vratu, oh ujeta hči sionska.',
        3: 'Kajti tako govori Gospod: ›Prodali ste se za nič in odkupljeni boste brez denarja.‹',
        4: 'Kajti tako govori Gospod Bog: ›Moje ljudstvo je poprej šlo dol v Egipt, da začasno prebiva tam in Asirec jih je zatiral brez vzroka.',
        5: 'Sedaj torej, kaj imam tukaj,‹ govori Gospod, ›da je moje ljudstvo vzeto proč za nič? Tisti, ki vladajo nad njimi, jim povzročajo, da tulijo,‹ govori Gospod ›in moje ime je nenehno vsak dan preklinjano.',
        6: 'Zato bo moje ljudstvo spoznalo moje ime, zato bodo na tisti dan vedeli, da jaz sem tisti, ki govori. Glejte, jaz sem.',
        7: 'Kako lepa so na gorah stopala tistega, ki prinaša dobre novice, ki objavlja mir, ki prinaša dobre novice o dobrem, ki objavlja rešitev duš, ki Sionu pravi: ›Tvoj Bog kraljuje!‹',
        8: 'Tvoji stražarji bodo povzdignili glas, z glasom bodo skupaj peli, kajti videli bodo iz oči v oči, ko bo Gospod ponovno privedel Sion.',
        9: 'Izbruhnite v radost, skupaj prepevajte, vi opustošeni kraji [prestolnice] Jeruzalem, kajti Gospod je potolažil svoje ljudstvo, odkupil je [prestolnico] Jeruzalem.',
        10: 'Gospod je svoj sveti laket razgalil v očeh vseh narodov in vsi konci zemlje bodo videli rešitev duš našega Boga.',
        11: 'Odidite, odidite, pojdite ven od tod, ne dotikajte se nobene nečiste stvari, pojdite ven iz njene srede, bodite čisti vi, ki nosite Gospodove posode.',
        12: 'Kajti ven ne boste šli z naglico niti s pobegom, kajti Gospod bo šel pred vami in Izraelov Bog bo vaša zadnja straža.',
        13: 'Glejte, moj služabnik bo ravnal razsodno, povzdignjen bo, povišan in bo zelo visok.',
        14: 'Kakor so bili mnogi osupli nad teboj. Njegov videz je bil tako iznakažen, bolj kakor [od] kateregakoli človeka in njegova oblika bolj kakor od človeških sinov;',
        15: 'tako bo poškropil mnoge narode; kralji bodo zaprli svoja usta pred njim. Kajti to, kar jim ni bilo povedano, bodo videli, in česar niso slišali, bodo preudarjali.',
    },
    53: {
        1: 'Kdo je veroval našemu poročilu? In komu se je razodel Gospodov laket?',
        2: 'Kajti pred njim bo pognal kakor nežna rastlina in kakor korenina iz suhih tal. Nima oblike niti ljubkosti in ko ga bomo videli, ni lepote, da bi ga želeli.',
        3: 'Preziran je in zavrnjen od ljudi, mož bridkosti in seznanjen z žalostjo in mi smo, kakor bi skrili svoje obraze pred njim; bil je preziran, mi pa ga nismo cenili.',
        4: 'Zagotovo je nosil naše žalosti in prenašal naše bridkosti, vendar smo ga imeli [za] zadetega, udarjenega od Boga in trpečega.',
        5: 'Toda ranjen je bil zaradi naših prestopkov, poškodovan je bil zaradi naših krivičnosti. Kazen za naš mir je bila na njem in z njegovimi udarci z bičem smo ozdravljeni.',
        6: 'Vsi smo zašli kakor ovce, obrnili smo se vsak k svoji lastni poti in Gospod je nanj položil krivičnost nas vseh.',
        7: 'Bil je zatiran in trpel, vendar ni odprl svojih ust. Priveden je kakor jagnje h klanju in kakor je ovca pred svojimi strižci nema, tako on ne odpre svojih ust.',
        8: 'Vzet je bil iz ječe in iz sodbe in kdo bo razglasil njegov rod? Kajti odrezan je bil iz dežele živih, zaradi prestopka mojega ljudstva je bil udarjen.',
        9: 'Njegov grob v njegovi smrti mu je določil z zlobnimi in z bogatimi, čeprav ni storil nobenega nasilja niti ni bilo nobene prevare v njegovih ustih.',
        10: '§ Vendar je Gospodu ugajalo, da ga rani; položil ga je v žalost. Ko boš naredil njegovo dušo v daritev za greh, bo videl svoje seme, podaljšal bo svoje dni in Gospodovo zadovoljstvo bo uspevalo v njegovi roki.',
        11: '§ Videl bo muko svoje duše in bo zadovoljen. S svojim spoznanjem bo moj pravični služabnik opravičil mnoge, kajti nosil bo njihove krivičnosti.',
        12: 'Zato mu bom razdelil delež z velikimi in plen bo razdelil z močnimi, zato ker je svojo dušo izlil do smrti in prištet je bil med prestopnike; nosil je greh mnogih in opravil posredovanje za prestopnike.',
    },
    54: {
        1: '»Zapoj, oh jalova, ti, ki nisi nosila, izbruhni v petje in glasno zavpij, ti, ki se nisi mučila z otrokom, kajti več je otrok zapuščene kakor otrok poročene žene,« govori Gospod.',
        2: 'Povečaj kraj svojega šotora in naj razprostrejo zagrinjala tvojih prebivališč. Ne šparaj, podaljšaj svoje vrvi in ojačaj svoje kline,',
        3: 'kajti izbruhnila boš na desno roko in na levo in tvoje seme bo podedovalo pogane in naredila boš, da bodo opustela mesta naseljena.',
        4: 'Ne boj se, kajti ne boš osramočena niti ne bodi zbegana, kajti ne prideš v sramoto, kajti pozabila boš sramoto svoje mladosti in ne boš se več spominjala graje svojega vdovstva.',
        5: 'Kajti tvoj Stvarnik je tvoj soprog, Gospod nad bojevniki je njegovo ime in tvoj Odkupitelj Sveti Izraelov; imenovali ga bodo Bog celotne zemlje.',
        6: 'Kajti Gospod te je poklical kakor žensko, zapuščeno in užaloščeno v duhu in ženo mladosti, ko si bila zavržena,« govori tvoj Bog.',
        7: '»Kajti za kratek trenutek sem te zapustil, toda z velikimi usmiljenji te bom zbral.',
        8: 'Z malce besa sem za trenutek skril svoj obraz pred teboj, toda z večno prijaznostjo bom imel usmiljenje nad teboj,« govori Gospod, tvoj Odkupitelj.',
        9: '»Kajti to mi je kakor so bile Noetove vode, kajti kakor sem prisegel, da Noetove vode ne bodo več šle preko zemlje, tako sem prisegel, da ne bom ogorčen nad teboj niti te ne bom več oštel.',
        10: 'Kajti gore se bodo umaknile in hribi bodo odstranjeni, toda moja prijaznost ne bo odšla od tebe niti zaveza mojega miru ne bo odstranjena,« govori Gospod, ki ima usmiljenje do tebe.',
        11: '»Oh ti trpeča, premetavana z viharjem in nepotolažena, glej, tvoje kamne bom položil z lepimi barvami in tvoje temelje bom položil s safirji.',
        12: 'Tvoja okna bom naredil iz ahata in tvoja velika vrata iz granata in vse tvoje meje iz prijetnih kamnov.',
        13: 'Vsi tvoji otroci bodo poučevani od Gospoda in velik bo mir tvojih otrok.',
        14: 'V pravičnosti boš utrjena, daleč boš od zatiranja, kajti ne boš se bala in [daleč boš] od strahote, kajti ta se ti ne bo približala.',
        15: '§ Glej, zagotovo se bodo zbrali skupaj, toda to ni od mene. Kdorkoli se bo skupaj zbral proti tebi, bo padel zaradi tebe.',
        16: 'Glej, jaz sem ustvaril kovača, ki v ognju razpihuje ogorke in ki prinaša orodje za svoje delo in jaz sem ustvaril kvarilca, da uničuje.',
        17: 'Nobeno orožje, ki je oblikovano zoper tebe, ne bo uspelo in vsak jezik, ki se bo na sodbi dvignil zoper tebe, boš obsodila. To je dediščina Gospodovih služabnikov in njihova pravičnost je od mene,« govori Gospod.',
    },
    55: {
        1: 'Hej, vsi, ki ste žejni, pridite k vodam in tisti, ki nimate denarja; pridite, kupite in jejte; da, pridite, kupite vino in mleko, brez denarja in brez cene.',
        2: 'Zakaj trošite denar za to, kar ni kruh? In svoj trud za to, kar ne nasičuje? Marljivo mi prisluhnite in jejte to, kar je dobro in naj se vaša duša razveseljuje v obilju.',
        3: 'Nagnite svoje uho in pridite k meni. Prisluhnite in vaša duša bo živela in z vami bom sklenil večno zavezo, celó zanesljive Davidove milosti.',
        4: 'Glej, izročil sem ga za pričo ljudstvu, voditelja in poveljnika ljudstvu.',
        5: 'Glej, poklical boš narod, ki ga nisi poznal in narodi, ki te niso poznali, bodo tekli k tebi zaradi Gospoda, tvojega Boga in zaradi Svetega Izraelovega, ker te je proslavil.',
        6: 'Iščite Gospoda, dokler se daje najti, kličite k njemu, dokler je blizu.',
        7: 'Naj zlobni zapusti svojo pot in nepravičen človek svoje misli in naj se vrne h Gospodu in se ga bo usmilil; in k našemu Bogu, kajti obilno bo odpustil.',
        8: 'Kajti moje misli niso vaše misli niti vaše poti niso moje poti,« govori Gospod.',
        9: '»Kajti kakor je nebo višje od zemlje, tako so moje poti višje od vaših poti in moje misli višje od vaših misli.',
        10: 'Kajti kakor dež prihaja dol in sneg z neba in se ne vrača tja, temveč zaliva zemljo in jo pripravlja, da poganja in brsti, da lahko da seme sejalcu in kruh jedcu,',
        11: 'tako bo moja beseda, ki gre ven iz mojih ust. Le-ta se k meni ne bo vrnila prazna, temveč bo le-ta dovršila to, kar mi ugaja in uspela v stvari, h kateri sem jo poslal.',
        12: 'Kajti ven boste odšli z radostjo in vodeni boste z mirom. Gore in hribi bodo izbruhnili pred vami s petjem in vsa poljska drevesa bodo ploskala s svojimi rokami.«',
        13: 'Namesto trnja bo zrasla cipresa in namesto osata bo pognalo mirtino drevo in to bo Gospodu v ime in za večno znamenje, ki ne bo iztrebljeno.',
    },
    56: {
        1: 'Tako govori Gospod: »Varujte sodbo in ravnajte pravično, kajti moja rešitev duš je blizu, da pride in moja pravičnost, da se razodene.',
        2: 'Blagoslovljen je človek, ki to počne in človeški sin, ki se tega oprime, ki varuje šabat pred omadeževanjem in zadržuje svojo roko pred početjem kakršnega koli zla.',
        3: 'Niti ne pusti sinu tujca, ki se je pridružil Gospodu, govoriti, rekoč: › Gospod me je popolnoma ločil od svojega ljudstva.‹ Niti naj evnuh ne reče: ›Glej, jaz sem suho drevo.‹',
        4: 'Kajti tako govori Gospod evnuhom, ki se držijo mojih šabat in izbirajo stvari, ki mi ugajajo in se držijo moje zaveze;',
        5: 'celo njim bom dal, v svoji hiši in znotraj svojih zidov, prostor in ime, boljše kakor od sinov in hčera. Dal jim bom večno ime, ki ne bo iztrebljeno.',
        6: 'Tudi sinove tujca, ki se pridružijo Gospodu, da bi mu služili in da bi ljubili Gospodovo ime, da bi bili njegovi služabniki, vsak, kdor ohranja šabat pred tem, da bi ga omadeževal in se drži moje zaveze,',
        7: 'celó pripeljal jih bom na svojo sveto goro in jih razveselil v svoji hiši molitve. Njihove žgalne daritve in njihove klavne daritve bodo sprejete na mojem oltarju, kajti moja hiša se bo imenovala hiša molitve za vsa ljudstva.‹«',
        8: 'Gospod Bog, ki zbira Izraelove pregnance, govori: »Še bom zbral k njemu druge, poleg tistih, ki so zbrani k njemu.',
        9: 'Vse ve poljske živali, pridite, da požrete, da, vse ve živali v gozdu.',
        10: 'Njegovi stražarji so slepi. Vsi so nevedni, vsi so nemi psi, ne morejo lajati; spijo, legajo, radi dremajo.',
        11: 'Da, pohlepni psi so, ki nikoli ne morejo imeti dovolj in pastirji, ki ne morejo razumeti. Vsi gledajo na svojo lastno pot, vsak za svojim dobičkom, od svoje meje.',
        12: 'Pridite, pravijo: ›Šel bom po vino in nalili se bomo z močno pijačo in jutrišnji dan bo kakor ta dan in mnogo obilnejši.‹«',
    },
    57: {
        1: 'Pravični propada in nihče si tega ne jemlje k srcu. Usmiljeni ljudje so odvzeti, nihče ne preudarja, da je pravični odvzet pred zlom, ki pride.',
        2: 'Vstopil bo v mir. Počivali bodo v svojih posteljah, vsakdo, ki hodi v svoji poštenosti.',
        3: 'Toda približajte se sèm, vi sinovi čarodejk, seme zakonolomca in vlačuge.',
        4: 'Zoper koga se zabavate? Zoper koga širite usta in iztezate jezik? Mar niste otroci prestopka, seme neresnice,',
        5: 'ki se vnemate z maliki pod vsakim zelenim drevesom, ki koljete otroke v dolinah pod skalnimi pečinami?',
        6: 'Med gladkimi kamni vodotoka je tvoj delež; ti, ti so tvoj žreb. Celo njim si izlivala pitno daritev, darovala si jedilno daritev. Mar naj prejmem tolažbo v teh?',
        7: 'Na vzvišeni in visoki gori si si postavila svojo posteljo, celo tja gor odhajaš, da daruješ klavno daritev.',
        8: 'Tudi za vrati in podboji si postavila svoj spomin, kajti odkrila si se drugemu kot meni in odšla gor. Razširila si svojo posteljo in sklenila zavezo z njimi; ljubila si njihovo posteljo, kjer si jo videla.',
        9: '§ Odhajaš h kralju z mazilom, množila si svoje dišave, svoje poslance si poslala daleč in sebe si ponižala celo do pekla.',
        10: 'Izmučena si v veličini svojih poti, vendar ne praviš: ›Tam ni upanja.‹ Našla si življenje svoje roke, zato nisi bila užaloščena.',
        11: 'Pred kom si bila prestrašena ali si se bala, da si lagala in se nisi spomnila mene niti si tega nisi vzela k srcu? Mar nisem molčal celo od davnine in se me ne bojiš?',
        12: 'Razglašal bom tvojo pravičnost in tvoja dela, kajti ne bodo ti koristila.',
        13: 'Ko vpiješ, naj te tvoje trume rešijo; toda veter jih bo vse odnesel proč, ničevost jih bo vzela. Toda tisti, ki svoje trdno upanje polaga vame, bo vzel v last deželo in podedoval mojo sveto goro',
        14: 'in rekel bo: ›Nasujte, nasujte, pripravite pot, vzemite kamen spotike iz poti mojega ljudstva.‹',
        15: 'Kajti tako govori Visoki in Vzvišeni, ki naseljuje večnost, čigar ime je Sveti: ›Prebivam na visokem in svetem kraju, pa tudi s tistim, ki je skesanega in ponižnega duha, da oživim duha ponižnega in da oživim srce skesanega.',
        16: 'Kajti ne bom se prepiral na veke niti ne bom vedno besen, kajti duh bi opešal pred menoj in duše, ki sem jih naredil.',
        17: 'Zaradi krivičnosti njegove pohlepnosti sem bil besen in ga udaril. Skril sem se in bil besen, on pa je kljubovalno odšel po poti svojega srca.',
        18: 'Videl sem njegove poti in ozdravil ga bom. Prav tako ga bom vodil in obnovil tolažbe njemu in njegovim žalovalcem.',
        19: 'Jaz ustvarjam sad ustnic: ›Mir, mir tistemu, ki je daleč proč in tistemu, ki je blizu,‹ govori Gospod ›in jaz ga bom ozdravil.',
        20: 'Toda zlobni so kot razburkano morje, kadar ne more počivati, katerega vode bljuvajo blato in umazanijo.',
        21: 'Tam ni miru,‹ govori moj Bog, ›zlobnemu.‹«',
    },
    58: {
        1: 'Vpij naglas, ne brzdaj se, svoj glas povzdigni kakor šofar in mojemu ljudstvu pokaži njihov prestopek in Jakobovi hiši njihove grehe.',
        2: 'Vendar me dnevno iščejo in se veselijo spoznati moje poti kakor narod, ki je ravnal pravično in ni zapustil odredbe svojega Boga. Sprašujejo me odredbe o pravici, razveseljujejo se v približevanju Bogu.',
        3: '›Zakaj smo se postili,‹ pravijo ›ti pa ne vidiš? Zakaj smo mučili svojo dušo, ti pa se za to ne meniš?‹ Glejte, na dan svojega posta si najdete užitek in priganjate vse svoje delavce.',
        4: 'Glejte, postite se za prepir in razpravljanje in da udarjate s pestjo zlobnosti. Ne boste se postili, kakor delate ta dan, da bi svojemu glasu dali, da se sliši na višavi.',
        5: 'Mar je to takšen post, ki sem ga izbral? Dan za človeka, da muči svojo dušo? Ali je to, da skloni svojo glavo kakor ločje in pod seboj razširja vrečevino in pepel? Mar boš to imenoval post in sprejemljiv dan Gospodu?',
        6: 'Mar ni to post, ki sem ga izbral? Da razvežeš vezi zlobnosti, da odstraniš težka bremena in da izpustiš zatirane prosto oditi in da zlomiš vsak jarem?',
        7: 'Mar ni to, da deliš svoj kruh lačnemu in da privedeš revne, ki so izobčeni, k svoji hiši? Ko vidiš nagega, da ga pokriješ in da se ne skrivaš pred svojim lastnim mesom?',
        8: '§ Potem bo tvoja svetloba izbruhnila kakor jutro in tvoje zdravje bo naglo vzbrstelo in tvoja pravičnost bo šla pred teboj, Gospodova slava bo tvoja zadnja straža.',
        9: 'Potem boš klical in Gospod bo odgovoril; vpil boš in rekel bo: ›Tukaj sem.‹ Če odstraniš jarem iz svoje srede, kazanje s prstom in govorjenje ničnosti',
        10: '§ in če svojo dušo iztezaš k lačnemu in zadovoljiš trpečo dušo, potem bo v nejasnosti vstala tvoja svetloba in tvoja tema bo kakor poldan.',
        11: 'Gospod te bo nenehno usmerjal in tvojo dušo zadovoljil v suši in tvoje kosti odebelil. In ti boš kakor namakan vrt in podoben boš vodnemu izviru, katerega vode ne usahnejo.',
        12: 'Tisti, ki bodo od tebe, bodo gradili stare opustošene kraje. Vzdignil boš temelje mnogih rodov in imenovan boš: ›Popravljavec vrzeli, obnovitelj steza za prebivanje.‹',
        13: 'Če odvrneš svoje stopalo pred šabat, pred tem, da počneš svoje zadovoljstvo na moj sveti dan in imenuješ šabat veselje, [dan] svet Gospodu, častitljiv in ga boš častil in ne izvajal svojih lastnih poti niti iskal svojega lastnega zadovoljstva niti govoril svojih lastnih besed,',
        14: 'potem se boš veselil v Gospodu in povzročil ti bom, da jezdiš na visokih krajih zemlje in te hranil z dediščino svojega očeta Jakoba, kajti Gospodova usta so to govorila.‹«',
    },
    59: {
        1: 'Glej, Gospodova roka ni skrajšana, da ne more rešiti niti njegovo uho zamašeno, da ne more slišati,',
        2: 'temveč so vaše krivičnosti ločile med vami in vašim Bogom in vaši grehi so skrili njegov obraz pred vami, da ne bi slišal.',
        3: 'Kajti vaše roke so omadeževane s krvjo in vaši prsti s krivičnostjo, vaše ustnice so govorile laži, vaš jezik je mrmral perverznost.',
        4: 'Nihče ne kliče za pravico niti se kdorkoli ne poteguje za resnico. Zaupajo v ničnost in govorijo laži, spočnejo vragolijo in obrodijo krivičnost.',
        5: 'Valijo jajca strupene kače in tkejo pajkovo mrežo. Kdor od njihovih jajc jé, umira in to, kar je zdrobljeno, se izvali v gada.',
        6: 'Njihove mreže ne bodo postale obleke niti se ne bodo pokrili s svojimi deli. Njihova dela so dela krivičnosti in dejanje nasilja je v njihovih rokah.',
        7: 'Njihova stopala tečejo k zlu in hitijo, da prelijejo nedolžno kri. Njihove misli so misli krivičnosti; pustošenje in uničenje sta na njihovih stezah.',
        8: 'Poti miru ne poznajo in na njihovih poteh ni sodbe. Naredili so si sprijene steze. Kdorkoli tam hodi, ne bo poznal miru.',
        9: 'Zato je sodba daleč od nas niti nas pravica ne doseže. Čakamo na svetlobo, toda glej, nejasnost; na sijaj, toda hodimo v temi.',
        10: 'Tipamo za zidom kakor slepi in tipamo, kakor ne bi imeli oči. Spotikamo se opoldan kakor ponoči, na zapuščenih krajih smo kakor mrtvi možje.',
        11: 'Vsi rjovemo kakor medvedje in boleče žalujemo kakor golobice. Pričakujemo sodbo, toda ni je; rešitev duš, toda ta je daleč od nas.',
        12: 'Kajti naši prestopki so pomnoženi pred teboj in naši grehi pričujejo zoper nas. Naši prestopki so z nami in glede naših krivičnosti, mi jih poznamo:',
        13: 'prestopanje in laganje zoper Gospoda in odhajanje proč od našega Boga, govorjenje zatiranja in punta, spočenjanje in izgovarjanje besed neresnice iz srca.',
        14: 'Sodba je odvrnjena nazaj in pravica stoji daleč proč, kajti resnica je padla na ulici in nepristranskost ne more vstopiti.',
        15: 'Da, resnica peša in tisti, ki odhaja od zla, se izpostavlja za plen in Gospod je to videl in to ga je razžalilo, da ni bilo sodbe.',
        16: 'Videl je, da ni bilo nobenega človeka in se čudil, da ni bilo nobenega posredovalca, zato mu je njegov laket prinesel rešitev duše in njegova pravičnost ga je podpirala.',
        17: 'Kajti nadel si je pravičnost kakor prsni oklep in na svojo glavo čelado rešitve duš in za oblačila si je nadel obleke maščevanja in z gorečnostjo je bil odet kakor z ogrinjalom.',
        18: 'Glede na njihova dejanja bo primerno poplačal: razjarjenost svojim nasprotnikom, povračilo svojim sovražnikom, otokom bo poplačal povračilo.',
        19: '§ Tako se bodo bali Gospodovega imena od zahoda in njegove slave od sončnega vzhoda. Ko bo sovražnik vstopil kot povodenj, bo Gospodov duh dvignil prapor zoper njega.',
        20: 'Odkupitelj bo prišel na Sion in k tistim, ki se obračajo od prestopka v Jakobu,‹ govori Gospod.',
        21: '›Kar se tiče mene, to je moja zaveza z njimi,‹ govori Gospod: ›Moj duh, ki je na tebi in moje besede, ki sem ti jih položil v tvoja usta, ne bodo odšle iz tvojih ust niti iz ust tvojega semena niti iz ust semena tvojega semena,‹ govori Gospod, ›od tega časa naprej in na veke.',
    },
    60: {
        1: 'Vstani, zasij, kajti tvoja svetloba je prišla in Gospodova slava je vstala nad teboj.',
        2: 'Kajti glej, tema bo prekrila zemljo in velika tema ljudstva, toda Gospod bo vstal nad teboj in njegova slava bo vidna na tebi.',
        3: 'Pogani bodo prišli k tvoji svetlobi in kralji k siju tvojega vzhajanja.',
        4: 'Dvigni svoje oči naokoli in poglej. Vsi se zbirajo skupaj, prihajajo k tebi. Tvoji sinovi bodo prišli od daleč in tvoje hčere bodo negovane ob tvoji strani.',
        5: 'Takrat boš videla in tekla skupaj in tvoje srce se bo balo in bo povečano, ker bo obilje morja obrnjeno k tebi, sile poganov bodo prišle k tebi.',
        6: 'Pokrila te bo množica kamel, [enogrbi] velblodi iz Midjána in Efe, vsi tisti iz Sabe bodo prišli. Prinesli bodo zlato in kadilo in naznanjali bodo Gospodove hvalnice.',
        7: 'Vsi kedárski tropi bodo zbrani skupaj k tebi, Nebajótovi ovni ti bodo služili. Na moj oltar bodo prišli s sprejetjem in jaz bom proslavil hišo svoje slave.',
        8: 'Kdo so ti, ki letijo kakor oblak in kakor golobice k svojim oknom?',
        9: 'Otoki bodo zagotovo čakali name in spredaj ladje iz Taršíša, da privedejo tvoje sinove od daleč, njihovo srebro in njihovo zlato z njimi, k imenu Gospoda, tvojega Boga in k Svetemu Izraelovemu, ker te je proslavil.',
        10: 'Sinovi tujcev bodo zgradili tvoja obzidja in njihovi kralji ti bodo služili, kajti v svojem besu sem te udaril, toda v svoji naklonjenosti sem imel usmiljenje nad teboj.',
        11: 'Zato bodo tvoja velika vrata nenehno odprta; ne podnevi ne ponoči ne bodo zaprta, da ti bodo ljudje lahko prinašali sile poganov in da bodo lahko privedeni njihovi kralji.',
        12: 'Kajti narod in kraljestvo, ki ti ne bo služilo, bo propadlo; da, ti narodi bodo popolnoma opustošeni.',
        13: 'Slava Libanona bo prišla k tebi, cipresa, bor in pušpan skupaj, da olepšajo kraj mojega svetišča in kraj svojih stopal bom naredil veličasten.',
        14: 'Tudi sinovi tistih, ki so te prizadeli, bodo prišli, upogibajoč se k tebi in vsi, ki so te prezirali, se bodo priklonili pri podplatih tvojih stopal in imenovali te bodo: › Gospodovo mesto, Sion Svetega Izraelovega.‹',
        15: 'Kakor si bila zapuščena in osovražena, tako da noben človek ni šel skozi tebe, te bom naredil za večno odličnost, radost mnogih rodov.',
        16: 'Prav tako boš sesala mleko poganov in sesala prsi kraljev in vedela boš, da sem jaz, Gospod, tvoj Odrešenik in tvoj Odkupitelj, Mogočni Jakobov.',
        17: 'Za bron bom prinesel zlato in za železo bom prinesel srebro in za les bron in za kamne železo. Prav tako bom postavil [za] tvoje častnike mir in tvoje priganjače pravičnost.',
        18: 'Nasilja ne bo več slišati v tvoji deželi niti pustošenja niti uničenja znotraj tvojih meja, temveč boš svoja obzidja imenovala Odrešenje in svoja velika vrata Hvala.',
        19: 'Sonce ne bo več tvoja svetloba podnevi niti ti za sijaj luna ne bo dajala svetlobe, temveč ti bo Gospod večna svetloba in tvoj Bog tvoja slava.',
        20: 'Tvoje sonce ne bo več zašlo niti se tvoja luna ne bo umaknila, kajti Gospod bo tvoja večna svetloba in dnevi tvojega žalovanja bodo končani.',
        21: 'Prav tako tvoje ljudstvo – vsi bodo pravični. Podedovali bodo deželo na veke, mladiko mojega sajenja, delo mojih rok, da bom lahko proslavljen.',
        22: 'Najmanjši bo postal tisoč in malček mogočen narod. Jaz, Gospod, bom to pospešil ob svojem času.',
    },
    61: {
        1: 'Duh Gospoda Boga je nad menoj, ker me je Gospod mazilil, da oznanjam dobre novice krotkim, poslal me je, da povežem potrte v srcu, da razglasim svobodo ujetnikom in odprtje ječe tem, ki so zvezani,',
        2: 'da razglasim sprejemljivo leto Gospodovo in dan maščevanja našega Boga, da potolažim vse tiste, ki žalujejo,',
        3: '§ da določim tem, ki žalujejo na Sionu, da jim dam lepoto namesto pepela, olje veselja namesto žalovanja, obleko hvale namesto duha potrtosti, da se bodo lahko imenovali drevesa pravičnosti, Gospodov nasad, da bo on lahko proslavljen.',
        4: 'Zgradili bodo stare opustošenosti, dvignili bodo prejšnja opustošenja in popravili bodo opustošena mesta, zapuščenosti mnogih rodov.',
        5: 'Tujci bodo stali in pasli vaše trope in sinovi neznanca bodo vaši orači in vaši obrezovalci trte.',
        6: 'Toda vi boste imenovani Gospodovi duhovniki. Ljudje vas bodo klicali Služabniki našega Boga. Jedli boste bogastva poganov in v njihovi slavi se boste bahali.',
        7: 'Zaradi vaše sramote boste imeli dvojno in zaradi nečasti se bodo veselili v svojem deležu, zato bodo v svoji deželi posedovali dvojno, njim bo v večno radost.',
        8: 'Kajti jaz, Gospod, ljubim sodbo, sovražim naropano za žgalno daritev in njihovo delo bom vodil v resnici in z njimi bom sklenil večno zavezo.',
        9: 'Njihovo seme bo znano med pogani in njihovo potomstvo med ljudstvom. Vsi, ki jih vidijo, jim bodo priznali, da so seme, ki ga je Gospod blagoslovil.',
        10: 'Silno se bom razveseljeval v Gospodu, moja duša bo radostna v mojem Bogu, kajti oblekel me je z oblačili rešitve duše, pokril me je s svečanim oblačilom pravičnosti, kakor ženin sebe odene z okrasjem in kakor nevesta sebe okrasi s svojimi dragocenostmi.',
        11: 'Kajti kakor zemlja prinaša svoj brst in kakor vrt povzroča stvarem, ki so posejane vanj, da poženejo, tako bo Gospod Bog povzročil pravičnosti in hvali, da poženeta pred vsemi narodi.',
    },
    62: {
        1: 'Zaradi Siona ne bom molčal in zaradi Jeruzalema ne bom počival, dokler njegova pravičnost ne gre naprej kakor sijaj in njegova rešitev duš kakor svetilka, ki gori.',
        2: 'Pogani bodo videli tvojo pravičnost in vsi kralji tvojo slavo in imenovana boš z novim imenom, ki ga bodo poimenovala Gospodova usta.',
        3: 'Krona slave boš v Gospodovi roki in kraljevski diadem v roki svojega Boga.',
        4: 'Ne boš več imenovana Zapuščena niti ne bo tvoja dežela imenovana Opustošena, temveč se boš imenovala Hefziba in tvoja dežela Beula. Kajti Gospod se razveseljuje v tebi in tvoja dežela bo omožena.',
        5: 'Kajti kakor mladenič poroči devico, tako se bodo tvoji sinovi poročili s teboj in kakor se ženin razveseljuje nad nevesto, tako se bo tvoj Bog veselil nad teboj.',
        6: 'Postavil sem stražarje na tvoja obzidja, oh Jeruzalem, ki niti podnevi niti ponoči ne bodo nikoli mirovali. Vi, ki omenjate Gospoda, ne molčite',
        7: 'in njemu ne dajajte nobenega počitka, dokler ne osnuje in dokler ne naredi [prestolnice] Jeruzalem [za] hvalo na zemlji.',
        8: 'Gospod je prisegel pri svoji desnici in pri laktu svoje moči: »Zagotovo ne bom več dajal tvojega žita, da bi bil hrana tvojim sovražnikom in sinovi tujca ne bo pili tvojega vina, za katerega si se trudila,',
        9: 'temveč tisti, ki so ga nabrali, ga bodo jedli in hvalili Gospoda in tisti, ki so ga zbrali skupaj, ga bodo pili na dvorih moje svetosti.',
        10: 'Pojdite skozi, pojdite skozi velika vrata, pripravite pot ljudstvu, nasujte, nasujte glavno cesto, poberite kamne, dvignite prapor za ljudstvo.',
        11: 'Glejte, Gospod je razglasil do konca sveta: »Sionski hčeri recite: ›Glej tvoja rešitev duš prihaja, glej, njegova nagrada je z njim in njegovo delo pred njim.‹«',
        12: 'Klicali jih bodo Sveto ljudstvo, Odkupljeni od Gospoda in ti boš imenovana ›Poiskana,‹ ›Mesto, ki ni zapuščeno.‹',
    },
    63: {
        1: '»Kdo je ta, ki prihaja iz Edóma, s pobarvanimi oblekami iz Bocre? Ta, ki je veličasten v svojem oblačilu, potujoč v veličini svoje moči?« »Jaz, ki govorim v pravičnosti, močan, da rešim.«',
        2: '»Zakaj si rdeč v svojem oblačilu in so tvoje obleke podobne tistemu, ki tlači v vinski kadi?«',
        3: 'Sam sem tlačil vinsko stiskalnico in izmed ljudstva ni bilo nikogar z menoj, kajti jaz jih bom pomendral v svoji jezi in jih poteptal v svoji razjarjenosti in njihova kri bo poškropljena na moje obleke in omadeževal si bom vse svoje oblačilo.',
        4: 'Kajti dan maščevanja je v mojem srcu in leto mojih odkupljenih je prišlo.',
        5: 'Pogledal sem in nikogar ni bilo, da pomaga in čudil sem se, da ni bilo nikogar, da podpre. Zato mi je moj lastni laket prinesel rešitev duše in moja razjarjenost me je podpirala.',
        6: 'V svoji jezi bom pomendral ljudstvo in jih opijanil v svoji razjarjenosti in njihovo moč bom privedel dol do zemlje.',
        7: 'Omenil bom Gospodove ljubeče skrbnosti in Gospodove hvalnice, glede na vse, kar je Gospod podelil na nas in veliko dobroto do Izraelove hiše, ki jo je podelil nanje, glede na njegova usmiljenja in glede na množino njegovih ljubečih skrbnosti.',
        8: 'Kajti rekel je: »Zagotovo so moje ljudstvo, otroci, ki ne bodo lagali.« Tako je bil njihov Odrešenik.',
        9: 'V vsej njihovi stiski je bil stiskan in angel njegove prisotnosti jih je rešil. V svoji ljubezni in svojem usmiljenju jih je odkupil in nosil jih je in prenašal vse dni davnine.',
        10: 'Toda uprli so se in jezili njegovega Svetega Duha, zato se je obrnil, da bi bil njihov sovražnik in se boril proti njim.',
        11: 'Potem se je spomnil dni davnine, Mojzesa in njegovega ljudstva, rekoč: »Kje je tisti, ki jih je s pastirjem svojega tropa privedel iz morja? Kje je tisti, ki je znotraj njega položil svojega Svetega Duha?',
        12: 'Ki jih je vodil z Mojzesovo desnico, svojim veličastnim laktom, razdeljujoč vode pred njimi, da si naredi večno ime?',
        13: 'Ki jih je vodil skozi globino kakor konja v divjini, da se ne bi spotaknili?',
        14: 'Kakor gre žival dol v dolino, mu je Gospodov Duh naklonil, da počiva. Tako si vodil svoje ljudstvo, da si narediš veličastno ime.',
        15: 'Poglej dol iz nebes in glej iz prebivališča svoje svetosti in svoje slave. Kje je tvoja gorečnost in tvoja moč, odzvanjanje tvoje notranjosti in tvoja usmiljenja do mene? Ali so zadržana?',
        16: 'Nedvomno si ti naš oče, čeprav je Abraham neveden o nas in nas Izrael ne prizna. Ti, oh Gospod, si naš oče, naš odkupitelj; tvoje ime je od vekomaj.',
        17: 'Oh Gospod, zakaj si nam povzročil, da zaidemo s tvojih poti in si naše srce zakrknil pred tvojim strahom? Vrni se zaradi svojih služabnikov, rodov svoje dediščine.',
        18: 'Ljudstvo tvoje svetosti ga je imelo v lasti le kratek čas. Naši nasprotniki so pomendrali tvoje svetišče.',
        19: 'Mi smo tvoji. Nikoli nisi vladal nad njimi; niso bili imenovani s tvojim imenom.',
    },
    64: {
        1: 'Oh, da bi pretrgal nebo, da bi prišel dol, da bi gore lahko tekle ob tvoji prisotnosti,',
        2: 'kakor ko topilni ogenj žge, ogenj povzroča vodam, da vrejo, da tvoje ime naredi znano tvojim nasprotnikom, da bodo narodi lahko trepetali ob tvoji prisotnosti!',
        3: 'Ko si delal strašne stvari, ki jih nismo pričakovali, si prišel dol, gore so tekle ob tvoji prisotnosti.',
        4: 'Kajti od začetka sveta ljudje niso slišali niti z ušesom zaznali niti ni oko videlo, oh Bog, razen tebe, kaj je on pripravil za tistega, ki čaka nanj.',
        5: 'Ti srečaš tistega, ki se razveseljuje in dela pravično, tiste, ki se te spominjajo na tvojih poteh. Glej, besen si, kajti mi smo grešili. V tistih je vztrajanje in mi bomo rešeni.',
        6: 'Toda mi vsi smo kakor nečista stvar in vse naše pravičnosti so kakor umazane cunje in mi vsi venemo kakor list in naše krivičnosti so nas kakor veter odnesle proč.',
        7: 'Nikogar ni, ki kliče k tvojemu imenu, ki se razvnema, da bi se te oprijel. Kajti svoj obraz si skril pred nami in nas použil zaradi naših krivičnosti.',
        8: 'Toda sedaj, oh Gospod, si ti naš oče. Mi smo ilo in ti naš lončar in mi vsi smo delo tvojih rok.',
        9: 'Ne bodi zelo boleče ogorčen, oh Gospod niti se ne spominjaj krivičnosti na veke. Glej, preišči, rotimo te, mi vsi smo tvoje ljudstvo.',
        10: 'Tvoja sveta mesta so divjina, Sion je divjina, Jeruzalem opustošenje.',
        11: 'Naša sveta in naša krasna hiša, kjer so te naši očetje hvalili, je požgana z ognjem in vse naše prijetne stvari so opustošene.',
        12: 'Mar se boš zadrževal zaradi teh stvari, oh Gospod? Mar boš molčal in nas zelo boleče prizadel?',
    },
    65: {
        1: 'Poiskan sem od tistih, ki niso spraševali po meni; najden sem od tistih, ki me niso iskali: »Rekel sem: ›Glejte me, glejte me,‹« narodu, ki ni bil klican po mojem imenu.',
        2: 'Svoje roke sem ves dan razprostiral k upornemu ljudstvu, ki hodi po poti, ki ni bila dobra, po svojih lastnih mislih',
        3: 'in ljudstvu, ki me nenehno draži do jeze v moj obraz, ki žrtvuje na vrtovih in zažiga kadilo na oltarjih iz opek,',
        4: 'ki se zadržuje med grobovi in prenočuje v spomenikih, ki jé svinjsko meso in juha iz gnusnih stvari je v njihovih posodah,',
        5: 'ki pravijo: »Stoj zase, ne približaj se mi, kajti bolj svet sem kakor ti.« Ti so dim v mojem nosu, ogenj, ki ves dan gori.',
        6: 'Glej, to je zapisano pred menoj. Ne bom molčal, temveč bom poplačal, celo poplačal v njihovo naročje',
        7: 'vaše krivičnosti in krivičnosti vaših očetov skupaj,‹ govori Gospod, ›ki so zažigali kadilo na gorah in zoper mene izrekali bogokletje na hribih, zato bom njihovo prejšnje delo odmeril v njihovo naročje.‹',
        8: 'Tako govori Gospod: ›Kakor je novo vino najti v grozdu in nekdo pravi: ›Ne uniči ga, kajti blagoslov je v njem,‹ tako bom jaz storil zaradi svojih služabnikov, da jih ne bi vse uničil.',
        9: 'Privedel bom seme iz Jakoba in iz Juda dediča svojih gora in moj izvoljeni bo to podedoval in moji služabniki bodo tam prebivali.',
        10: 'Šarón bo staja tropov in dolina Ahór kraj za črede, da se uležejo, za moje ljudstvo, ki me je iskalo.',
        11: '§ Toda vi ste tisti, ki zapuščate Gospoda, ki pozabljate mojo sveto goro, ki pripravljate mizo za to krdelo in ki pripravljate pitno daritev temu številu.',
        12: 'Zato vas bom štel k meču in vsi se boste priklonili za zakol, ker ko sem klical niste odgovorili, ko sem govoril niste slišali, temveč ste počeli zlo pred mojimi očmi in izbirali to, v čemer se nisem razveseljeval.‹',
        13: 'Zato tako govori Gospod Bog: ›Glejte, moji služabniki bodo jedli, toda vi boste lačni. Glejte, moji služabniki bodo pili, toda vi boste žejni. Glejte, moji služabniki se bodo veselili, toda vi boste osramočeni.',
        14: 'Glejte, moji služabniki bodo prepevali zaradi srčne radosti, toda vi boste vpili zaradi bridkosti srca in tulili zaradi draženja duha.',
        15: 'Svoje ime boste pustili za prekletstvo mojim izbranim, kajti Gospod Bog te bo ubil in svoje služabnike klical z drugim imenom,',
        16: '§ da se bo tisti, ki se blagoslavlja na zemlji, blagoslavljal v Bogu resnice in kdor prisega na zemlji, bo prisegal pri Bogu resnice, kajti prejšnje težave so pozabljene in ker so skrite pred mojimi očmi.',
        17: 'Kajti glej, ustvarim novo nebo in novo zemljo in prejšnjega se ne bo spominjalo niti ne bo prišlo v misli.',
        18: 'Toda bodite veseli in se na veke veselite tega, kar ustvarim. Kajti glejte, [prestolnico] Jeruzalem ustvarim za razveseljevanje in njeno ljudstvo za radost.',
        19: 'Razveseljeval se bom v [prestolnici] Jeruzalem in se veselil v svojem ljudstvu. Glasu jokanja ne bo več slišati v njej niti glasu vpitja.',
        20: 'Tam ne bo več otročička po dnevih niti starca, ki ne bi izpolnil svojih dni, kajti otrok bo umrl star sto let, toda grešnik, ki bo star sto let, bo preklet.',
        21: 'Gradili bodo hiše in jih poselili in posadili bodo vinograde ter jedli od njihovega sadu.',
        22: 'Ne bodo gradili in drug naselil, ne bodo sadili in drug jedel, kajti kakor so dnevi drevesa, so dnevi mojega ljudstva in moji izvoljeni bodo dolgo uživali delo svojih rok.',
        23: 'Ne bodo se trudili zaman niti rojevali za težavo, kajti oni so seme blagoslovljenih od Gospoda in njihovo potomstvo z njimi.',
        24: 'In zgodilo se bo, da bom odgovarjal, preden bodo klicali in medtem ko še govorijo, bom usliševal.',
        25: 'Volk in jagnje se bosta skupaj pasla, lev bo jedel slamo kakor bikec in prah bo hrana kači. Ne bodo škodovali niti uničevali na vsej moji sveti gori,‹ govori Gospod.«',
    },
    66: {
        1: '»Tako govori Gospod: ›Nebo je moj prestol in zemlja je moja pručka. Kje je hiša, ki mi jo gradite? In kje je kraj mojega počitka?',
        2: 'Kajti vse te stvari je naredila moja roka in vse te stvari so bile,‹ govori Gospod, ›toda gledal bom k temu človeku, celó k njemu, ki je reven in skesanega duha in trepeta ob moji besedi.',
        3: 'Kdor kolje vola, je kakor če usmrti človeka; kdor žrtvuje jagnje, kakor če odseka pasji vrat; kdor daruje daritev kakor, če bi daroval svinjsko kri; kdor sežiga kadilo, kakor če bi blagoslovil malika. Da, izbrali so si svoje lastne poti in njihova duša se razveseljuje v njihovih ogabnostih.',
        4: 'Tudi jaz bom izbral njihove zablode in nanje privedel njihove strahove, ker ko sem klical nihče ni odgovoril, ko sem govoril niso poslušali, temveč so pred mojimi očmi počeli zlo in izbirali tisto, v čemer se nisem veselil.‹',
        5: 'Poslušajte Gospodovo besedo vi, ki trepetate ob njegovi besedi: ›Vaši bratje, ki so vas sovražili, ki so vas metali ven zaradi mojega imena, so rekli: ›Naj bo Gospod proslavljen.‹ Toda pojavil se bo v vašo radost, oni pa bodo osramočeni.‹',
        6: 'Glas hrupa iz mesta, glas iz templja, glas Gospoda, ki vrača povračilo svojim sovražnikom.',
        7: 'Preden je bila v porodnih mukah, je rodila, preden je prišla njena bolečina, je rodila fantka.',
        8: 'Kdo je slišal takšno stvar? Kdo je videl takšne stvari? Mar bo zemlja primorana, da rodi v enem dnevu? Ali bo narod hkrati rojen? Kajti takoj, ko je bila [hči] sionska v porodnih mukah, je rodila svoje otroke.',
        9: 'Mar bom privedel do rojstva in ne bom povzročil, da rodi?‹ govori Gospod: ›Mar bom povzročil, da rodi in zaprl maternico?‹ govori tvoj Bog.',
        10: 'Veselite se s [prestolnico] Jeruzalem in bodite veseli z njo, vsi vi, ki jo ljubite. Veselite se zaradi radosti z njo, vsi vi, ki žalujete nad njo,',
        11: 'da boste lahko sesali in boste nasičeni s prsi njenih tolažb, da boste srkali in boste veseli z obiljem njene slave,‹',
        12: 'kajti tako govori Gospod: ›Glejte, mir bom iztegnil k njej kakor reko in slavo poganov kakor tekoč vodotok. Potem boste sesali, nošeni boste na njenih straneh in ujčkani na njenih kolenih.',
        13: 'Kakor nekdo, ki ga njegova mati tolaži, tako bom jaz potolažil vas in v Jeruzalemu boste potolaženi.',
        14: 'Ko to zagledate, se bo vaše srce veselilo in vaše kosti bodo cvetele kakor zelišče in Gospodova roka bo poznana njegovim služabnikom in njegovo ogorčenje proti njegovim sovražnikom.',
        15: 'Kajti glej, Gospod bo prišel z ognjem in s svojimi bojnimi vozovi kakor z vrtinčastim vetrom, da povrne svojo jezo z razjarjenostjo in svoje oštevanje s plameni ognja.',
        16: 'Kajti z ognjem in s svojim mečem se bo Gospod pravdal z vsem mesom in mnogo bo umorjenih od Gospoda.',
        17: 'Tisti, ki se posvetijo in se očistijo na vrtovih za enim drevesom na sredi, jedoč svinjsko meso, ogabnost in miš, bodo skupaj použiti,‹ govori Gospod.',
        18: 'Kajti poznam njihova dela in njihove misli. Zgodilo se bo, da bom zbral vse narode in jezike in prišli bodo in videli mojo slavo.',
        19: 'Med njimi bom postavil znamenje in poslal bom tiste, ki izmed njih pobegnejo k narodom, k Taršíšu, Pulu in Ludu, ki napenjajo lok, k Tubálu in Javánu, k oddaljenim otokom, ki niso slišali mojega slovesa niti niso videli moje slave in mojo slavo bodo razglašali med pogani.',
        20: 'K moji sveti gori Jeruzalem bodo privedli vse vaše brate v dar Gospodu iz vseh narodov na konjih, bojnih vozovih, nosilnicah, na mulah in na hitrih živalih,‹ govori Gospod, ›kakor Izraelovi otroci prinesejo daritev v čisti posodi v Gospodovo hišo.',
        21: 'Tudi od njih [jih] bom vzel za duhovnike in za Lévijevce,‹ govori Gospod.',
        22: '›Kajti kakor bosta novo nebo in nova zemlja, ki ju bom naredil, ostala pred menoj,‹ govori Gospod, ›tako bo ostalo vaše seme in vaše ime.',
        23: 'In zgodilo se bo, da bo od enega do drugega mlaja in od enega do drugega šabata, prišlo vse meso, da obožuje pred menoj,‹ govori Gospod.',
        24: '›Šli bodo naprej in gledali na trupla ljudi, ki so se pregrešili zoper mene, kajti njihov črv ne bo umrl niti njihov ogenj ne bo pogašen in gnus bodo vsemu mesu.‹«',
    },
}
